        achievementId = 33,
        name = "Nothing Boring About Borean",
        category = "Quests",
        sourceType = "Achievement",
        source = "Nothing Boring About Borean",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Start at Valiance Keep in Borean Tundra and complete its military and Farshire branches. Finish Hiding in Plain Sight, A Family Reunion and To the Aid of Farshire rather than leaving after the first hub hand-in.\n\n2. Go to the D.E.H.T.A. camp (57.1, 44.3). Complete ALL its parallel animal-rescue chains until Arch Druid Lathorius offers The Assassination of Harold Lane, then defeat Lane and turn it in. Completing one rescue branch does not finish this chapter.\n\n3. For Friends from the Sea, finish the Kaskala/Unu'pe and Karuk chains, including Karuk's Oath on the southwest coast. Continue the emissary/diplomatic follow-ups; stopping at The Tides Turn can leave this chapter incomplete.\n\n4. For Participant Observation, follow King Mrgl-Mrgl's Winterfin Retreat chain at the northwest coast. Enter Winterfin Caverns and check the captive Glrggl for The Escape; his in-cave escort is an easily missed part of the chain.\n\n5. For The Blue Dragonflight, finish the Amber Ledge quests, including the Monitoring the Rift series and Traversing the Rift, then continue at Transitus Shield in Coldarra. Use the Augmented Arcane Prison in your bags to summon Keristrasza for her quests through Springing the Trap. If the item was discarded, ask Raelorasz at Transitus Shield for another.\n\n6. Finish Thassarian's Last Rites chain at Death's Stand/Temple City of En'kilah. Review all eight chapter ticks. Fizzcrank Airstrip's unrelated quests are not a substitute for a missing Blue Dragonflight or emissary follow-up.",
