    [34] = {
        achievementId = 34,
        name = "I've Toured the Fjord",
        category = "Quests",
        sourceType = "Achievement",
        source = "I've Toured the Fjord",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Begin at Valgarde and finish its Vrykul/Scourge quests. For The Ill-Equipped Port, continue all the way to To Westguard Keep! and turn it in to Captain Adams; Let's Go Surfing Now is not the final chapter hand-in.\n\n2. At Westguard Keep, follow the Skorn campaign, Iron Dwarf work and Iron Rune Construct quests. Return to Captain Adams and the related field quest givers after each branch; the construct vehicle quests are part of the Alliance checklist.\n\n3. Complete the northern Fort Wildervar/Camp Winterhoof branches through Alpha Worg. Check the Sisters of the Fjord chain and the nearby forest quest givers if those chapters remain unfinished.\n\n4. Visit Kamagua and Ancient Lift, then follow the pirate story to Scalawag Point. Finish The Debt Collector and The End of Jonah Sterling. Board Captain Ellis's moving ghost ship, The Sister Mercy, for its required quests; he is easy to miss when no land quest marker is visible.\n\n5. Finish the remaining faction-specific chapter shown in your checklist, then check all twelve ticks. On Horde, The Book of Runes chain and Captain Ellis's ship are frequent missing links; on Alliance, verify To Westguard Keep! and the complete Iron Rune Construct sequence.",
