    [35] = {
        achievementId = 35,
        name = "Might of Dragonblight",
        category = "Quests",
        sourceType = "Achievement",
        source = "Might of Dragonblight",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Start at Stars' Rest and Wintergarde Keep. Complete The Warden's Task and the Wintergarde/Wrathgate military branches. Follow the cemetery, rescue and commander quests through the chapter endings rather than moving on after the first battle.\n\n2. Complete the ley-line chain from your faction's west-side camp through Redirecting the Ley Lines. Follow its summons and dragon introductions to Wyrmrest Temple; finish Informing the Queen and the Dragonflights branches there.\n\n3. At Moa'ki Harbor, complete the coastal Tuskarr chain through Oacha'noa. At the Crystal Vice, check Nozzlerust Post and Zort's cave-side quests for Strategic Alliance. These neutral hubs are not replaced by completing your faction's military chain.\n\n4. Finish the Dragonblight campaign to Alexstrasza and Return to Angrathar for the Wrathgate chapter. The cinematic and achievement remain available; the old follow-up Battle for Undercity was removed and is not required.\n\n5. Complete the Frostmourne/Arthas chain as shown in the Alliance chapter list, then check all eight chapter ticks. If no quests appear, inspect quest-starting drops already in your bags and revisit the neutral hubs.",
