    [36] = {
        achievementId = 36,
        name = "The Empire of Zul'Drak",
        category = "Quests",
        sourceType = "Achievement",
        source = "The Empire of Zul'Drak",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Start at Light's Breach and complete its rescue/fire/troll quests for Finding Allies. Follow Crusader Forward Camp to Gymer's rescue and The Storm King's Vengeance. Use Gymer's vehicle actions and healing pickups; finish the full Storm King's Crusade turn-in.\n\n2. At Ebon Watch, start Stefan Vadu's Kickin' Nass and Takin' Manes. Loot the Unliving Choker to start An Invitation of Sorts, then follow the disguise chain into Voltarus. Alternate Drakuru's tasks with Stefan's sabotage work, using Stefan's horn to summon him when required. Finish Betrayal and loot Drakuru's skull.\n\n3. At the Argent Stand, complete Pa'Troll and each captain's assignment, including Lab Work. Continue the Captain Rupert/Dr. Rogers rescue and spider chains through Malas the Corrupter for The Argent Patrol. Check the camp east of the stand if its chapter remains missing.\n\n4. For Sseratus, loot Strange Mojo from the altar trolls and follow Hexxer Ubungo's Precious Elemental Fluids, Mushroom Mixer and Too Much of a Good Thing. Combine the elemental links and use the resulting item as the quest instructs.\n\n5. Continue through Zim'Torga to Har'koa, Rhunok and Quetz'lun. Finish the linked gods' chains, including the underworld spirit interactions, through You Reap What You Sow. Then complete the Key of Warlord Zol'Maz, Rampage, The Gods Have Spoken and Convocation at Zol'Heb for Akali.\n\n6. At the Amphitheater of Anguish, take and turn in EACH arena challenge in order: Yggdras, Magnataur, From Beyond, Tuskarrmageddon, Korrak and the Champion of Anguish. Check all eight chapters. The current achievement uses these endings, not the old 100-quest total.",
