    [37] = {
        achievementId = 37,
        name = "Fo' Grizzle My Shizzle",
        category = "Quests",
        sourceType = "Achievement",
        source = "Fo' Grizzle My Shizzle",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Start at Amberpine Lodge, then follow Lieutenant Dumont's introduction to the Westfall Brigade Encampment. Complete Captain Gryan Stoutmantle's work until he sends you to Mountaineer Kilian and Raegar Breakbrow; their chains finish Loken's Orders and The Iron Thane.\n\n2. Complete the Ursoc, the Bear God chain in the northern Grizzlemaw/Ursoc's Den area. Follow the quests through Ursoc's own encounter and final turn-in; simply killing the bear without the quest does not complete the chapter.\n\n3. Work through the Silverbrook, trapper and Sasha chains in western Grizzly Hills to Hour of the Worg. Loot and inspect Mikhail's Journal where your branch requires its quest-starting drop.\n\n4. At Granite Springs, start Truce? with Drakuru and finish Vial of Visions, Subject to Interpretation, Sacrifices Must Be Made and the remaining spirit tasks. Keep the summoning items; use the Elixir of Visions when entering Drak'Tharon for the Revelation! conclusion.\n\n5. Complete the remaining Eons of Misery storyline and check all faction chapters. If a Drakuru task appears to have vanished, look for the vial/summons quest in your log and bags. Do not substitute unrelated PvP dailies or assume Harrison Jones is mandatory for the present chapter checklist.",
