    [38] = {
        achievementId = 38,
        name = "The Summit of Storm Peaks",
        category = "Quests",
        sourceType = "Achievement",
        source = "The Summit of Storm Peaks",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Start at K3 and finish Defending K3. Follow Gretchen Fizzlespark's They Took Our Men! chain into the disguised Brunnhildar village. Complete its bear, prisoner and drake-competition sequence through the Thorim introduction and Mending Fences.\n\n2. Continue Thorim's story and repair your standing with the Sons of Hodir. Finish the yellow quest chain through The Reckoning for Heartbreak/Loken and the Sons of Hodir chapter; repeatable reputation turn-ins alone do not replace the storyline.\n\n3. Complete the faction branch from Frosthold (Alliance) or Grom'arsh Crash-Site/Camp Tunka'lo (Horde). Follow the Frostborn king or Stormhoof story, and the Iron Colossus/Norgannon quests, checking which faction-specific criteria your character sees.\n\n4. Follow the Brann/Creteus investigation and Pursuing a Legend branches to their final hand-ins. On Horde, follow Xarantaur, the Witness to Camp Tunka'lo and complete The Witness and the Hero and its scroll investigation. Check Brann's Communicator in your bags if no NPC marker appears.\n\n5. Finish Bearly Ready and The Harpy Problem through the remaining Brunnhildar/Frosthold side chains, then review every current chapter tick. Flying access is useful for this mountainous route. The old Engineering-only SCRAP-E quest and an exact 100-quest count are not required by the chapter system.",
