    [39] = {
        achievementId = 39,
        name = "Into the Basin",
        category = "Quests",
        sourceType = "Achievement",
        source = "Into the Basin",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. At Nesingwary Base Camp in Sholazar Basin, complete the engine/repair introduction, then the rhino, dreadsaber and crocolisk mastery chains. Follow Hemet's In Search of Bigger Game to Dorian Drakestalker's camp and finish the mammoth/dragon conclusion for Hunting Bigger Game and Teeth, Spikes, and Talons.\n\n2. At the Avatar of Freya in the northeast, follow her Scourge, pillar and Lifewarden work. Finish the late Lifewarden/Waygate turn-ins rather than stopping at Trust of a Lifewarden. These complete The Lifewarden and Watching Over the Basin.\n\n3. For The Wolvar, kill Pitch at 50.6, 76.8 and immediately accept Playing Along from Tracker Gekgek. Work through the Frenzyheart chain. If progression disappears, use Goregek's Shackles from your bags, or ask Elder Harkek at Frenzyheart Hill for a replacement.\n\n4. Continue the injured Oracle rescue and the Rainspeaker Canopy storyline. Use Lafoo's Bug Bag or the other supplied Oracle summon item for quests that do not appear over a fixed NPC. Ask High-Oracle Soo-say for a replacement if needed.\n\n5. Continue the Oracle investigation through the cave confrontation with Artruis and A Hero's Burden where offered. Check all six story chapters. You do not need both factions Exalted for Into the Basin; that is the separate Mercenary of Sholazar achievement.",
        stepCount = 5,
        waypoints = {
