    [40] = {
        achievementId = 40,
        name = "Icecrown: The Final Goal",
        category = "Quests",
        sourceType = "Achievement",
        source = "Icecrown: The Final Goal",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Begin at Argent Vanguard, not the raid entrance. Complete Tirion's defense chain: Honor Above All Else, the rescue/Skytalon work, A Cold Front Approaches, The Last Line of Defense, then the Scourgeholme campaign and The Battle for Crusaders' Pinnacle. Finish In Defiance of the Scourge.\n\n2. Take the introduction to your faction's moving airship, Skybreaker or Orgrim's Hammer. Talk to ALL its quest givers even when they show blue daily markers: they can also offer necessary yellow quests. Follow Broken Front/Mord'rethar and the Retest Now/It's All Fun and Games branch to Baron Sliver. Finish I Have an Idea, But First..., Free Your Mind and If He Cannot Be Turned to capture The Shadow Vault.\n\n3. At the captured Shadow Vault, finish the Death's Rise/Grand Admiral work for What's Yours Is Mine. Follow Keritose Bloodblade's Parting Gifts, vehicle and saronite chains through Amidst the Confusion for Seizing Saronite. Continue to Vereth the Cunning, New Recruit, the Lithe Seeker missions and the three Riders through The Fate of Bloodbane for Malykriss.\n\n4. For The Unthinkable, follow The Leaper to the Bone Witch. In the Underhalls (entrance 32.45, 31.89), loot Apprentice Osterkilgr's key quest and finish The Sum Is Greater than the Parts. Complete the Bone Witch's Water Terror, ancient hero and Banshee's Revenge chain, then each Battle at Valhalas challenge in order.\n\n5. At Blackwatch (35.4, 66.3), follow Darkrider Arly and Crusader Olakin: Where Are They Coming From?, Destroying the Altars, Jagged Shards, the doctor/reassembly sequence, and The Flesh Giant Champion. Use the quest's vehicle and body-part interactions, and wait for the reassembly dialogue. This finishes Teaching the Meaning of Fear.\n\n6. Return to the airship for the Matthias Lehner investigation. Follow the Ymirheim mine and later Lehner appearances through Army of the Damned, Futility, Where Dragons Fell, The Hunter and the Prince, Knowledge Is a Terrible Burden and Argent Aid. Finish Tirion's Gambit under the cultist disguise, following Tirion through the whole scene for The Heart of the Lich King.\n\n7. At Tirion, start A Tale of Valor and visit Crusader Bridenbrad. Complete all three attempts to save him: Keeper Remulos in Moonglade, Alexstrasza in Dragonblight, and A'dal in Shattrath. Use the offered quest portals when available. Return each boon to Bridenbrad and finish the chest's Light Within the Darkness.\n\n8. Back on the faction airship, check Thassarian (Alliance) or Koltira (Horde) for the later Aldur'thar and Corp'rethar orders. Finish Drag and Drop, Not a Bug, Need More Info and No Rest for the Wicked; then Raise the Barricades, the Ironwall/sky campaign and The Guardians of Corp'rethar/Shatter the Shards. Keep checking the CURRENT chapter list and final hand-ins.",
        stepCount = 8,
        waypoints = {
            { mapID = 118, x = 0.87, y = 0.769, step = 1, label = "Argent Vanguard - Tirion's original campaign" },
            { mapID = 118, x = 0.8, y = 0.72, step = 1, label = "Crusaders' Pinnacle - finish the defense chain" },
            {
                mapID = 125,
                x = 0.6970000000000001,
                y = 0.45399999999999996,
                step = 2,
                label = "Krasus' Landing - faction-airship introduction",
            },
            { mapID = 118, x = 0.435, y = 0.252, step = 2, label = "Shadow Vault - capture before later chains" },
            { mapID = 118, x = 0.203, y = 0.478, step = 3, label = "Death's Rise - Grand Admiral branch" },
