            { mapID = 80, x = 0.36200000000000004, y = 0.418, step = 7, label = "Keeper Remulos - Moonglade boon" },
            { mapID = 115, x = 0.598, y = 0.546, step = 7, label = "Alexstrasza - Wyrmrest Temple boon" },
