            { mapID = 118, x = 0.5193, y = 0.3329, step = 8, label = "Aldur'thar interior - No Rest for the Wicked" },
        },
        tips = "Enable Trivial Quests in tracking and follow the full named chapter to its final turn-in. A missing quest marker can mean a prerequisite, a quest-starting item in your bags, or a summons item with its own quest giver. Old 100/130/150-quest counters no longer describe this Retail achievement. Stay on one character for the interconnected campaign when possible. Its phase and hub unlocks are character-specific even when Warband chapter credit is shared. Airships move: use their world-map icons rather than a fixed ground pin. Argent Tournament dailies do not finish these chapters.",
        sources = {
            "https://www.wowhead.com/achievement=40#comments:id=2558388",
            "https://www.wowhead.com/achievement=40#comments:id=2558389",
            "https://www.wowhead.com/achievement=40#comments:id=2567129",
