            "https://www.wowhead.com/achievement=40#comments:id=6241328",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=40",
        sourceURL = "https://www.wowhead.com/achievement=40#comments",
        difficultyReason = "Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.",
        difficulty = "medium",
    },
    [41] = {
        achievementId = 41,
        name = "Loremaster of Northrend",
        category = "Quests",
        sourceType = "Achievement",
        source = "Loremaster of Northrend",
        acquisition = "Difficulty: Hard - Complete all eight Northrend zone quest achievements; the full continent is a lengthy quest project.\n\n1. Track the eight zone-story achievements: Borean Tundra, Howling Fjord, Dragonblight, Grizzly Hills, Zul'Drak, Sholazar Basin, Storm Peaks and Icecrown. The Retail criteria are completed STORY CHAPTERS, not a fixed total of random quests.\n\n2. Work through one zone's complete guide before starting another. Follow the appropriate faction variant in the four split-faction zones. Enable Trivial Quests and keep quest-starting/summoning items until their story branches are finished.\n\n3. Plan flying access for Storm Peaks and complete Icecrown's hub-unlock campaign on one character where practical. Warband credit can combine zone achievements, but it does not unlock another character's phased quest givers.\n\n4. Check the meta after all eight zones credit. Crystalsong Forest and Wintergrasp exploration are not additional quest-story requirements. If a chapter is missing, use that zone guide's specific late-chain and bag-item corrections.",
        stepCount = 4,
        waypoints = {
            { mapID = 114, x = 0.585, y = 0.682, step = 2, label = "Borean Tundra" },
            { mapID = 117, x = 0.599, y = 0.645, step = 2, label = "Howling Fjord" },
            { mapID = 115, x = 0.598, y = 0.546, step = 2, label = "Dragonblight" },
            { mapID = 116, x = 0.318, y = 0.6, step = 2, label = "Grizzly Hills" },
            { mapID = 121, x = 0.32, y = 0.75, step = 2, label = "Zul'Drak" },
            { mapID = 119, x = 0.27, y = 0.585, step = 2, label = "Sholazar Basin" },
            { mapID = 120, x = 0.41100000000000003, y = 0.861, step = 3, label = "Storm Peaks" },
            { mapID = 118, x = 0.87, y = 0.769, step = 3, label = "Icecrown - Argent Vanguard" },
        },
        sources = {
            "https://www.wowhead.com/achievement=41#comments:id=1957237",
            "https://www.wowhead.com/achievement=41#comments:id=2567334",
            "https://www.wowhead.com/achievement=41#comments:id=6085224",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=41",
        sourceURL = "https://www.wowhead.com/achievement=41#comments",
        difficultyReason = "Complete all eight Northrend zone quest achievements; the full continent is a lengthy quest project.",
        difficulty = "hard",
    },
    [45] = {
        achievementId = 45,
        name = "Northrend Explorer",
        category = "Exploration",
        sourceType = "Achievement",
        source = "Nine Northrend exploration achievements",
        acquisition = "Difficulty: Medium - Finish all nine Northrend zone exploration checklists; the route spans the whole continent.\n\n1. Track the nine zone achievements: Explore Borean Tundra, Howling Fjord, Dragonblight, Grizzly Hills, Zul'Drak, Sholazar Basin, Storm Peaks, Icecrown and Crystalsong Forest.\n\n2. Follow each zone's numbered discovery circuit and check its actual achievement criteria. Fog disappearing near another location does not necessarily credit the missing area.\n\n3. Use flying for Sholazar's Stormwright's Shelf/Makers' Overlook and Storm Peaks' high temples. Crystalsong means the forest BELOW Dalaran; neither Wintergrasp nor Dalaran is a tenth zone criterion.\n\n4. Finish all nine component achievements and check Northrend Explorer. If one remains incomplete, inspect its checklist for the named missing subzone rather than repeatedly flying across the whole continent.",
        stepCount = 4,
        waypoints = {
            { mapID = 114, x = 0.5878, y = 0.6855, step = 2, label = "Borean Tundra circuit" },
            { mapID = 117, x = 0.25, y = 0.57, step = 2, label = "Howling Fjord circuit" },
