    [125] = {
        achievementId = 125,
        name = "Northrend Cook",
        category = "Professions",
        sourceType = "Achievement",
        source = "Northrend Cook",
        acquisition = "Difficulty: Medium - Raise the required Northrend profession categories to 75 using expansion-specific recipes or gathering.\n\n1. Learn Northrend Cooking from Katherine Lee in A Hero's Welcome (Alliance, 40.3, 66.1) or Awilo Lon'gomba in the Horde inn (70.0, 38.9), in Northrend Dalaran. Open the Northrend category: another expansion's Cooking skill does not count.\n\n2. Use the orange/yellow trainer recipes and available Northrend meat/fish to raise that category. Rhino Dogs use Rhino Meat and are a practical early recipe; keep them and Chilled Meat for the Dalaran cooking dailies.\n\n3. Do the daily from your cooking trainer for Epicurean's Awards. At Derek Odds or Misensi beside the faction kitchen, buy a higher-skill recipe such as Mighty Rhino Dogs and Northern Spices for its ingredients. Switch recipes when your current one no longer grants skill.\n\n4. Continue to 75 base Northrend Cooking skill. The original 450 total-skill requirement was replaced by this expansion-specific cap. Crafting different needed recipes also advances The Northrend Gourmet.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 125,
                x = 0.40299999999999997,
                y = 0.6609999999999999,
                step = 1,
                label = "Katherine Lee - Alliance Northrend Cooking",
            },
            { mapID = 125, x = 0.7, y = 0.389, step = 1, label = "Awilo Lon'gomba - Horde Northrend Cooking" },
            { mapID = 125, x = 0.406, y = 0.6579999999999999, step = 3, label = "Derek Odds - Alliance recipes and spices" },
            { mapID = 125, x = 0.7020000000000001, y = 0.39, step = 3, label = "Misensi - Horde recipes and spices" },
        },
        sources = { "https://www.wowhead.com/achievement=125#comments:id=3245217" },
        wowheadUrl = "https://www.wowhead.com/achievement=125",
        sourceURL = "https://www.wowhead.com/achievement=125#comments",
        difficultyReason = "Raise the required Northrend profession categories to 75 using expansion-specific recipes or gathering.",
        difficulty = "medium",
    },
    [130] = {
        achievementId = 130,
        name = "Northrend Fisherman",
        category = "Professions",
        sourceType = "Achievement",
        source = "Northrend Fisherman",
        acquisition = "Difficulty: Medium - Raise the required Northrend profession categories to 75 using expansion-specific recipes or gathering.\n\n1. Visit Marcia Chase beside the Eventide fountain in Northrend Dalaran (52.6, 64.8) and learn Northrend Fishing. Check the Northrend skill bar rather than your current-expansion Fishing bar.\n\n2. Fish Northrend water until this category reaches 75. The Eventide fountain lets you work on all three coin checklists at the same time; the Underbelly is an alternative while trying for Giant Sewer Rat.\n\n3. Loot your catches and keep fishing after casts that do not increase skill. Higher levels can take several catches per point. Return to the skill window to confirm 75 Northrend Fishing and achievement credit.",
        stepCount = 3,
        waypoints = {
            { mapID = 125, x = 0.526, y = 0.648, step = 1, label = "Marcia Chase - learn Northrend Fishing" },
            { mapID = 125, x = 0.525, y = 0.662, step = 2, label = "Eventide fountain - skill and coin fishing" },
            { mapID = 126, x = 0.44, y = 0.65, step = 2, label = "Underbelly - alternate skill / Giant Sewer Rat" },
        },
        sources = { "https://www.wowhead.com/achievement=130#comments:id=5350969" },
        wowheadUrl = "https://www.wowhead.com/achievement=130",
        sourceURL = "https://www.wowhead.com/achievement=130#comments",
        difficultyReason = "Raise the required Northrend profession categories to 75 using expansion-specific recipes or gathering.",
        difficulty = "medium",
    },
    [137] = {
        achievementId = 137,
        name = "Stocking Up",
        category = "Professions",
        sourceType = "Achievement",
        source = "Stocking Up",
        acquisition = "Difficulty: Medium - Learn the heavy bandage recipe and personally craft five hundred bandages from gathered or bought cloth.\n\n1. Use a character with Tailoring. Learn Northrend Tailoring, then visit the First to Your Aid shop in Northrend Dalaran (37.4, 36.6) for the Frostweave bandage recipes. First Aid is no longer a separate profession.\n\n2. Raise Northrend Tailoring to the Heavy Frostweave Bandage recipe's requirement (15). If starting at skill 1, reserve extra cloth for the ordinary bandages needed to reach it.\n\n3. Obtain 1,000 Frostweave Cloth for 500 Heavy Frostweave Bandages, less any progress already credited. Each heavy bandage consumes two cloth. Buying 500 finished bandages does not satisfy a crafting achievement.\n\n4. Personally craft the heavy bandages, allowing bag space and enough time for the queue. Check the achievement counter before selling or using the results. This remains earnable through Tailoring despite its original First Aid classification.",
        stepCount = 4,
        waypoints = {
            { mapID = 125, x = 0.365, y = 0.335, step = 1, label = "Charles Worth - Northrend Tailoring" },
            { mapID = 125, x = 0.374, y = 0.366, step = 1, label = "First to Your Aid - bandage recipes" },
        },
        tips = "Starting from skill 1 requires additional cloth; the comment's 1,014 total includes 14 cloth for preparation. Prices and crafting time vary.",
        sources = {
            "https://www.wowhead.com/achievement=137#comments:id=611551",
            "https://www.wowhead.com/achievement=137#comments:id=3290588",
            "https://www.wowhead.com/achievement=137#comments:id=5458583",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=137",
        sourceURL = "https://www.wowhead.com/achievement=137#comments",
        difficultyReason = "Learn the heavy bandage recipe and personally craft five hundred bandages from gathered or bought cloth.",
        difficulty = "medium",
    },
    [141] = {
        achievementId = 141,
        name = "Ultimate Triage",
        category = "Professions",
        sourceType = "Achievement",
        source = "Ultimate Triage",
        acquisition = "Difficulty: Easy - Buy a qualifying bandage and heal a controlled low-health target; the retired First Aid profession is unnecessary.\n\n1. Obtain a Heavy Frostweave Bandage or an Embersilk/Windwool Bandage. You may buy the finished bandage; you do not need the retired First Aid profession. Check its level requirement before arranging the attempt.\n\n2. A repeatable setup is a duel with a friend in a safe outdoor area, such as the ground below Northrend Dalaran. Let your friend win the duel, leaving you at very low health. Stop automatic healing effects and avoid nearby enemies.\n\n3. Immediately use the qualifying bandage on yourself while below 5% health. Let its healing begin without moving or taking damage. Alternatively bandage the losing player while they are still below the threshold.\n\n4. If health regenerated above 5% or Recently Bandaged prevents another attempt, wait for the restriction, then repeat the duel. Buying or using an unrelated low-level bandage does not meet the named-bandage requirement.",
        stepCount = 4,
        waypoints = { { mapID = 127, x = 0.15, y = 0.42, step = 2, label = "Crystalsong Forest below Dalaran - arrange a safe duel" } },
        tips = "Use the qualifying bandage while the target is still below 5% health. A controlled duel lets you repeat the setup without searching for a particular low-health training dummy.",
        sources = {
            "https://www.wowhead.com/achievement=141#comments:id=484444",
            "https://www.wowhead.com/achievement=141#comments:id=2335854",
            "https://www.wowhead.com/achievement=141#comments:id=5892794",
            "https://www.wowhead.com/achievement=141#comments:id=5953872",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=141",
        sourceURL = "https://www.wowhead.com/achievement=141#comments",
        difficultyReason = "Buy a qualifying bandage and heal a controlled low-health target; the retired First Aid profession is unnecessary.",
        difficulty = "easy",
    },
    [477] = {
        achievementId = 477,
        name = "Utgarde Keep",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Utgarde Keep",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Normal difficulty is sufficient; a full Heroic clear also awards the Normal achievement. Enter the LOWER Utgarde Keep portal beside the water in Howling Fjord. The upper ledge leads to Utgarde Pinnacle, a different dungeon.\n\n2. Follow the forge corridor and dragon pens to Prince Keleseth. Defeat him, then climb the Dragonflayer Ascent and kill BOTH Skarvald the Constructor and Dalronn the Controller; the surviving partner must also die.\n\n3. Continue upstairs to Tyr's Terrace and defeat Ingvar the Plunderer. WAIT for Annhylde to resurrect him, then kill his undead form. The first apparent death does not finish the encounter.",
