    [479] = {
        achievementId = 479,
        name = "The Culling of Stratholme",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "The Culling of Stratholme",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Normal difficulty is sufficient; a full Heroic clear also awards the Normal achievement. Enter the Caverns of Time in Tanaris, descend into the main cavern and take the Culling of Stratholme portal. Present-day Stratholme in Eastern Plaguelands is the wrong instance.\n\n2. Speak to Chromie and complete or skip the crate introduction using the dialogue available to your character. If asked to expose suspicious crates, use the supplied Arcane Disruptor on all five. Meet Arthas at Stratholme and speak to him to start the culling.\n\n3. Clear the marked street waves and defeat Meathook and Salramm the Fleshcrafter. Follow Arthas into the town hall, complete the Infinite Dragonflight waves and defeat Chrono-Lord Epoch. Speak to Arthas whenever progression pauses.\n\n4. Escort Arthas through the burning streets, speak to him at the last square and defeat Mal'Ganis. Wait for the encounter to end and check the boss criteria. The optional Infinite Corruptor is a separate Heroic timed objective, not a requirement for this clear.",
        stepCount = 4,
        waypoints = {
            { mapID = 75, x = 0.569, y = 0.8240000000000001, step = 1, label = "The Culling of Stratholme - entrance" },
