    [482] = {
        achievementId = 482,
        name = "Drak'Tharon Keep",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Drak'Tharon Keep",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Normal difficulty is sufficient; a full Heroic clear also awards the Normal achievement. Enter Drak'Tharon Keep at the southwestern edge of Zul'Drak, above the Grizzly Hills approach. Use the dungeon portal inside the keep.\n\n2. Defeat Trollgore, then Novos the Summoner. At Novos, kill the Crystal Handlers as they arrive to disable his barrier, then kill Novos. Continue through King Dred's raptor courtyard and defeat Dred.\n\n3. Climb to the overlook and defeat The Prophet Tharon'ja. If he transforms you into a skeleton, use the temporary abilities until your normal action bar returns, then finish him. Confirm that Tharon'ja's criterion credited before leaving.",
        stepCount = 3,
        waypoints = {
