        sourceURL = "https://www.wowhead.com/achievement=483#comments",
        difficultyReason = "Clear the named legacy dungeon in the required mode and complete its scripted boss events.",
        difficulty = "easy",
    },
    [484] = {
        achievementId = 484,
        name = "Gundrak",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Gundrak",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Normal difficulty is sufficient; a full Heroic clear also awards the Normal achievement. Use Gundrak's NORTHWEST entrance in northeastern Zul'Drak (76.4, 21.3). The southeast entrance at 81.1, 28.8 is another usable entrance to the same dungeon.\n\n2. Defeat Slad'ran, the Drakkari Colossus and Moorabi. CLICK THE ALTAR near each defeated boss; all three altar activations are needed to rotate the bridge to Gal'darah.\n\n3. Cross the activated central bridge and defeat Gal'darah, completing his troll/rhino phases if he survives. Confirm all the named boss criteria.",
        stepCount = 3,
        waypoints = {
            { mapID = 121, x = 0.764, y = 0.213, step = 1, label = "Gundrak - entrance" },
