    [485] = {
        achievementId = 485,
        name = "Halls of Stone",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Halls of Stone",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Normal difficulty is sufficient; a full Heroic clear also awards the Normal achievement. Fly to the Ulduar complex in northern Storm Peaks and enter Halls of Stone on the WEST side of the approach. The central Ulduar raid and eastern Halls of Lightning portal are different instances.\n\n2. Clear the side branches to Krystallus and the Maiden of Grief and defeat both. Neither should be skipped even if the route toward Brann is open.\n\n3. Find Brann Bronzebeard and speak to him to begin his escort. Follow him to the Tribunal of Ages and defend him through the complete event. Talk to him again after the dialogue, follow him to Sjonnir's door and let him open it. Defeat Sjonnir the Ironshaper.",
        stepCount = 3,
        waypoints = {
