        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Normal difficulty is sufficient; a full Heroic clear also awards the Normal achievement. Enter the UPPER Utgarde Pinnacle portal in Howling Fjord. The lower Utgarde Keep entrance leads to a different dungeon.\n\n2. Defeat Svala Sorrowgrave after her introduction. At Gortok's trophy room, activate the stasis controller and defeat the released beasts until Gortok Palehoof awakens; kill Gortok too.\n\n3. Start Skadi's gauntlet and collect HARPOONS from the Ymirjar Harpooners. At the launcher end, wait until Grauf is in range and fire three harpoons to bring Skadi down. Defeat Skadi, continue through the last hall and defeat King Ymiron.",
