    [489] = {
        achievementId = 489,
        name = "Heroic: Utgarde Keep",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Heroic: Utgarde Keep",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Set Dungeon Difficulty to HEROIC outside the instance. Enter the LOWER Utgarde Keep portal beside the water in Howling Fjord. The upper ledge leads to Utgarde Pinnacle, a different dungeon.\n\n2. Follow the forge corridor and dragon pens to Prince Keleseth. Defeat him, then climb the Dragonflayer Ascent and kill BOTH Skarvald the Constructor and Dalronn the Controller; the surviving partner must also die.\n\n3. Continue upstairs to Tyr's Terrace and defeat Ingvar the Plunderer. WAIT for Annhylde to resurrect him, then kill his undead form. The first apparent death does not finish the encounter.",
