    [490] = {
        achievementId = 490,
        name = "Heroic: The Nexus",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Heroic: The Nexus",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Set Dungeon Difficulty to HEROIC outside the instance. Fly to the Coldarra island west of Borean Tundra. Descend to the LOWEST portal beneath the Nexus tower; the Oculus entrance is on a higher ring.\n\n2. Work around the dungeon's three branches: defeat Grand Magus Telestra, Anomalus and Ormorok the Tree-Shaper. Activate the containment sphere near EACH defeated boss; all three are needed to release Keristrasza.\n\n3. Return to the central frozen dragon, Keristrasza, and finish activating the containment spheres if she is still imprisoned. Defeat her after she becomes attackable. Move or jump to clear Intense Cold and break roots promptly if the fight lasts.",
        stepCount = 3,
        waypoints = {
