    [491] = {
        achievementId = 491,
        name = "Heroic: Azjol-Nerub",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Heroic: Azjol-Nerub",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Set Dungeon Difficulty to HEROIC outside the instance. Enter the pit at 26.3, 49.5 in western Dragonblight. At the meeting stone, take the RIGHT branch to Azjol-Nerub; the left branch leads to Ahn'kahet.\n\n2. Defeat Krik'thir the Gatewatcher beyond the three watcher packs. Continue down into Hadronox's lair, let the spider encounter advance until Hadronox can be engaged, and defeat it.\n\n3. Follow the downward route and drop into the Brood Pit. Enter Anub'arak's arena and defeat him; kill the summoned waves whenever he burrows so he resurfaces. Check all three boss criteria before leaving.",
