    [492] = {
        achievementId = 492,
        name = "Heroic: Ahn'kahet: The Old Kingdom",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Heroic: Ahn'kahet: The Old Kingdom",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Set Dungeon Difficulty to HEROIC outside the instance. Enter the pit at 26.3, 49.5 in western Dragonblight and take the LEFT branch from the Azjol-Nerub meeting stone to Ahn'kahet.\n\n2. Defeat Elder Nadox, then reach Prince Taldaram's platform. Activate BOTH nearby devices to remove Taldaram's barrier and defeat him. Continue to Jedoga Shadowseeker, kill her initial worshippers and complete her sacrifice phase before finishing her.\n\n3. Reach Herald Volazj and defeat him. If Insanity occurs, kill the hostile copies in your phase, then resume attacking Volazj. Check each named boss criterion; skipping a side encounter can leave the clear unfinished.\n\n4. On HEROIC, also take the side path into the mushroom cavern and kill Amanitar. He is required for Heroic: Ahn'kahet even though he is unnecessary for the Normal achievement. Do this before leaving after Volazj.",
