    [494] = {
        achievementId = 494,
        name = "Heroic: The Violet Hold",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Heroic: The Violet Hold",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Set Dungeon Difficulty to HEROIC outside the instance. Go to the ORIGINAL Dalaran in Northrend and enter the Violet Hold prison. Legion Dalaran's Assault on Violet Hold is a different dungeon and cannot award these achievements.\n\n2. Speak to Lieutenant Sinclari inside and confirm that you are ready. Stay inside when the guards leave. Kill every portal's attackers before they damage the prison seal; the event advances through eighteen waves.\n\n3. Defeat the random prisoners released at waves 6 and 12, then Cyanigosa at wave 18. Kill Cyanigosa and wait for credit. The random prisoner selection matters for Lockdown!, but this clear only requires Cyanigosa.",
        stepCount = 3,
        waypoints = {
            { mapID = 125, x = 0.665, y = 0.6779999999999999, step = 1, label = "The Violet Hold - entrance" },
