    [495] = {
        achievementId = 495,
        name = "Heroic: Gundrak",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Heroic: Gundrak",
        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Set Dungeon Difficulty to HEROIC outside the instance. Use Gundrak's NORTHWEST entrance in northeastern Zul'Drak (76.4, 21.3). The southeast entrance at 81.1, 28.8 is another usable entrance to the same dungeon.\n\n2. Defeat Slad'ran, the Drakkari Colossus and Moorabi. CLICK THE ALTAR near each defeated boss; all three altar activations are needed to rotate the bridge to Gal'darah.\n\n3. Cross the activated central bridge and defeat Gal'darah, completing his troll/rhino phases if he survives. Confirm all the named boss criteria.\n\n4. On HEROIC, also take the passage behind Moorabi into the side cavern. Clear the living inhabitants to bring out Eck the Ferocious and kill him. Eck is a separate optional boss required for the Heroic clear; he is not the Drakkari Colossus.",
        stepCount = 4,
        waypoints = {
