        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Set Dungeon Difficulty to HEROIC outside the instance. Fly to the EASTERN dungeon entrance beside Ulduar in The Storm Peaks. Check that the instance name is Halls of Lightning before continuing.\n\n2. Defeat the patrolling General Bjarngrim on the lower platforms. Cross the slag room, climb to Volkhan's forge and defeat Volkhan.\n\n3. Continue along the Walk of the Makers to Ionar. If he disperses, wait for his sparks to return and finish the reformed boss. Clear the final hall and defeat Loken; this requires all four bosses, not just Loken.",
