        acquisition = "Difficulty: Easy - Clear the named legacy dungeon in the required mode and complete its scripted boss events.\n\n1. Set Dungeon Difficulty to HEROIC outside the instance. Fly to Coldarra in Borean Tundra and use the Oculus portal on the ring ABOVE the Nexus ground-level entrance. Defeat Drakos the Interrogator to release the three friendly drakes.\n\n2. Speak to a freed drake for an Amber, Emerald or Ruby Essence. Use it to fly between platforms. Kill the Centrifuge Constructs powering Varos's shield, then land, dismount and defeat Varos Cloudstrider.\n\n3. Fly to each of Mage-Lord Urom's platforms, kill the summoned packs and follow his teleports. Finish Urom on the inner ring. Use your drake to reach Ley-Guardian Eregos on the highest ring and defeat him to complete all four criteria.",
