    [547] = {
        achievementId = 547,
        name = "Veteran of the Wrathgate",
        category = "Quests",
        sourceType = "Achievement",
        source = "Veteran of the Wrathgate",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Enable Trivial Quests and follow your faction's Dragonblight campaign. ALLIANCE: begin The Lost Courier at Stars' Rest and continue Of Traitors and Treason to High Commander Halford Wyrmbane at Wintergarde. Finish Naxxramas and the Fall of Wintergarde, Flight of the Wintergarde Defender and Return to the High Commander.\n\n2. ALLIANCE: finish BOTH Wintergarde branches. Rescue from Town Square leads through Find Durkon!, The Noble's Crypt, the clickable Secrets of the Scourge tome, Mystery of the Tome and A Righteous Sermon. The Demo-gnome leads through The Search for Slinkin, Leave Nothing to Chance and Understanding the Scourge War Machine. Replies correct The Bleeding Ore: complete it too if the next quest is locked.\n\n3. ALLIANCE: follow Into Hostile Territory, Steamtank Surprise, Scattered to the Wind, The Chain Gun And You, Plunderbeard's journal and both Chasing Icestorm quests through Finality. Continue An End And A Beginning and To Fordragon Hold! to Audience With The Dragon Queen.\n\n4. HORDE: start Into the Fold/Blood Oath of the Horde, then report to Agmar's Hammer. Finish Victory Nears through Blightbeasts be Damned, and the Strength of Icemist/Chains of the Anub'ar/Return of the High Chief branch through All Hail Roanauk!.\n\n5. HORDE: complete the Venomspite plague branch: Imbeciles Abound!, The Forsaken Blight and You, Emerald Dragon Tears, Spread the Good Word and The Forsaken Blight. Continue The Kor'kron Vanguard! and Audience With The Dragon Queen.\n\n6. BOTH FACTIONS: at Wyrmrest Temple finish Galakrond and the Scourge, then use the Ruby Beacon's dragon for On Ruby Wings. Continue Return to Angrathar to the Wrathgate and finish the cinematic/turn-in for achievement credit.",
        stepCount = 6,
        waypoints = {
            { mapID = 115, x = 0.29, y = 0.55, step = 1, label = "Stars' Rest - Alliance Lost Courier" },
            { mapID = 115, x = 0.78, y = 0.48, step = 2, label = "Wintergarde - BOTH military branches" },
            {
                mapID = 115,
                x = 0.37799999999999995,
                y = 0.23399999999999999,
                step = 3,
                label = "Fordragon Hold - Alliance final introduction",
            },
            { mapID = 115, x = 0.38, y = 0.46, step = 4, label = "Agmar's Hammer - Horde military/Taunka" },
            { mapID = 115, x = 0.765, y = 0.625, step = 5, label = "Venomspite - Horde plague branch" },
            { mapID = 115, x = 0.598, y = 0.546, step = 6, label = "Wyrmrest Temple - Dragon Queen" },
            { mapID = 115, x = 0.385, y = 0.195, step = 6, label = "Angrathar - Wrathgate conclusion" },
        },
        tips = "Use only your faction's branches. The old Battle for Undercity follow-up was removed; it is not needed for this still-obtainable achievement.",
        sources = {
            "https://www.wowhead.com/achievement=547#comments:id=387111",
            "https://www.wowhead.com/achievement=547#comments:id=447601",
            "https://www.wowhead.com/achievement=547#comments:id=1182131",
            "https://www.wowhead.com/achievement=547#comments:id=1191185",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=547",
        sourceURL = "https://www.wowhead.com/achievement=547#comments",
        difficultyReason = "Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.",
        difficulty = "medium",
    },
    [561] = {
        achievementId = 561,
        name = "D.E.H.T.A's Little P.I.T.A.",
        category = "Quests",
        sourceType = "Achievement",
        source = "D.E.H.T.A's Little P.I.T.A.",
        acquisition = "Difficulty: Easy - Complete the camp's short rescue quest branches and final Harold Lane turn-in.\n\n1. Visit the D.E.H.T.A. camp in Borean Tundra (57.1, 44.3), enable Trivial Quests and accept its parallel tasks. Avoid killing protected wildlife while working for the camp; if Animal Blood makes the druids hostile, wait for it to clear before approaching.\n\n2. Complete Ears of Our Enemies by collecting 15 Nesingwary Lackey Ears from the poachers. Also finish Ned, Lord of Rhinos... by killing Nedar and Lunchbox. Further repeatable ear turn-ins do not replace the one-time chains.\n\n3. Finish the mammoth branch: Help Those That Cannot Help Themselves (free eight calves), Khu'nok Will Know (escort the calf), then Kaw the Mammoth Destroyer. Use the supplied quest interactions/vehicle and take Kaw's War Halberd.\n\n4. Finish the caribou branch: Unfit for Death (trap eight Nesingwary Trappers), then The Culler Cometh. Use the traps as instructed rather than killing the rescued animals.\n\n5. Finish the clam branch: Happy as a Clam, The Abandoned Reach, Not On Our Watch (12 animal-part shipments), and The Nefarious Clam Master.... Follow Hierophant Liandra's coastal follow-ups as well as the original camp tasks.\n\n6. Return to Arch Druid Lathorius and TALK to him even if his marker is blue for repeatable ears. Accept The Assassination of Harold Lane, kill Lane at the far side of Lake Kum'uya and turn it in. If the final quest is missing, check all branches and the initial ear turn-in before grinding unrelated reputation.",
        stepCount = 6,
        waypoints = {
            {
                mapID = 114,
                x = 0.5710000000000001,
                y = 0.44299999999999995,
                step = 1,
                label = "D.E.H.T.A. - all parallel rescue chains",
            },
            {
                mapID = 114,
                x = 0.5710000000000001,
                y = 0.44299999999999995,
                step = 2,
                label = "Lathorius - initial ear turn-in",
            },
            { mapID = 114, x = 0.595, y = 0.306, step = 3, label = "Khu'nok - mammoth chain" },
            { mapID = 114, x = 0.578, y = 0.551, step = 5, label = "Abandoned Reach - Liandra's coastal chain" },
            { mapID = 114, x = 0.494, y = 0.40399999999999997, step = 6, label = "Lake Kum'uya - Harold Lane" },
        },
        sources = {
            "https://www.wowhead.com/achievement=561#comments:id=334612",
            "https://www.wowhead.com/achievement=561#comments:id=1383285",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=561",
        sourceURL = "https://www.wowhead.com/achievement=561#comments",
        difficultyReason = "Complete the camp's short rescue quest branches and final Harold Lane turn-in.",
