    },
    [562] = {
        achievementId = 562,
        name = "The Arachnid Quarter (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "The Arachnid Quarter (10 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Outside Naxxramas, set Legacy Raid Size to 10 players. Fly to the floating necropolis over eastern Dragonblight and enter the portal underneath it (87.4, 51.0). This is the Northrend raid, not the removed Eastern Plaguelands version.\n\n2. Take the spider-lined Arachnid Quarter from the central hub. Kill Anub'Rekhan, Grand Widow Faerlina and Maexxna in that order. Faerlina is the boss surrounded by worshippers; Maexxna is at the end of the webbed passage.\n\n3. Check the wing's boss checklist before taking the return portal. Being outside the instance at a kill can leave that criterion missing.",
