    [568] = {
        achievementId = 568,
        name = "The Military Quarter (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "The Military Quarter (10 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Outside Naxxramas, set Legacy Raid Size to 10 players. Fly to the floating necropolis over eastern Dragonblight and enter the portal underneath it (87.4, 51.0). This is the Northrend raid, not the removed Eastern Plaguelands version.\n\n2. Take the Military Quarter and kill Instructor Razuvious. Start Gothik the Harvester's event and clear the arriving waves until he descends. Keep pets passive until he is on the floor; kill Gothik, wait for the gate to open, and enter the Four Horsemen's chamber.\n\n3. Walk up to the Four Horsemen without damaging them. Let all four leave their starting platform, then kill Thane Korth'azz, Baron Rivendare, Lady Blaumeux and Sir Zeliek. Attacking too early can reset the encounter.\n\n4. Check the wing's boss checklist before taking the return portal. Being outside the instance at a kill can leave that criterion missing.",
