    [572] = {
        achievementId = 572,
        name = "Sapphiron's Demise (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Sapphiron's Demise (10 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Outside Naxxramas, set Legacy Raid Size to 10 players. Fly to the floating necropolis over eastern Dragonblight and enter the portal underneath it (87.4, 51.0). This is the Northrend raid, not the removed Eastern Plaguelands version.\n\n2. From Naxxramas's entrance hub, use the central portal to Frostwyrm Lair. The old requirement to clear all four wings before using this route was removed.\n\n3. Defeat Sapphiron in the large ice chamber. At high level a direct kill is sufficient. If an air phase occurs, hide behind an ice block for Frost Breath, then resume attacking after the landing.",
