        name = "Kel'Thuzad's Defeat (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Kel'Thuzad's Defeat (10 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Outside Naxxramas, set Legacy Raid Size to 10 players. Fly to the floating necropolis over eastern Dragonblight and enter the portal underneath it (87.4, 51.0). This is the Northrend raid, not the removed Eastern Plaguelands version.\n\n2. Use the central portal to Frostwyrm Lair and defeat Sapphiron. Enter the chamber behind him and walk into the green circle to begin Kel'Thuzad's event.\n\n3. Stay near the central circle and kill the enemies that approach. Do not run around the outside alcoves or leave the room. The opening phase is timed; killing the first wave does not immediately make Kel'Thuzad attackable.\n\n4. When Kel'Thuzad joins the fight, defeat him and any surviving adds. For Just Can't Get Enough, follow that separate guide BEFORE killing the abominations or boss.",
