    [622] = {
        achievementId = 622,
        name = "The Spellweaver's Downfall (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "The Spellweaver's Downfall (10 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Set Legacy Raid Size to 10 players outside the instance. Fly to Coldarra in Borean Tundra and enter the EYE OF ETERNITY on the highest ring of the Nexus tower. The Nexus and Oculus portals are different instances.\n\n2. Use the central focusing device to start Malygos. Damage him to trigger phase 2. He can remain at 1 health until the scripted transitions finish; this is not a reason to reset.\n\n3. In phase 2, kill every Nexus Lord and Scion of Eternity. Ranged attacks can reach the flying enemies; otherwise kill a descending Nexus Lord and mount its dropped disc to fly to them. Stay inside the anti-magic bubbles if damage matters.\n\n4. When the platform breaks, wait for your red drake and its vehicle bar. Target Malygos and use Flame Spike (1), Flame Spike (1), Engulf in Flames (2); repeat, adding Revivify (3) to heal if needed and moving out of Static Fields. Finish the dragon and wait for credit.",
        stepCount = 4,
        waypoints = { { mapID = 114, x = 0.275, y = 0.266, step = 1, label = "Eye of Eternity - highest Nexus portal" } },
        tips = "No old Eye of Eternity key is needed. Do not leave the instance while the platform and drake transitions run.",
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=622",
        sourceURL = "https://www.wowhead.com/achievement=622#comments",
        difficultyReason = "Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.",
        difficulty = "easy",
    },
    [623] = {
        achievementId = 623,
        name = "The Spellweaver's Downfall (25 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "The Spellweaver's Downfall (25 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Set Legacy Raid Size to 25 players outside the instance. Fly to Coldarra in Borean Tundra and enter the EYE OF ETERNITY on the highest ring of the Nexus tower. The Nexus and Oculus portals are different instances.\n\n2. Use the central focusing device to start Malygos. Damage him to trigger phase 2. He can remain at 1 health until the scripted transitions finish; this is not a reason to reset.\n\n3. In phase 2, kill every Nexus Lord and Scion of Eternity. Ranged attacks can reach the flying enemies; otherwise kill a descending Nexus Lord and mount its dropped disc to fly to them. Stay inside the anti-magic bubbles if damage matters.\n\n4. When the platform breaks, wait for your red drake and its vehicle bar. Target Malygos and use Flame Spike (1), Flame Spike (1), Engulf in Flames (2); repeat, adding Revivify (3) to heal if needed and moving out of Static Fields. Finish the dragon and wait for credit.",
        stepCount = 4,
        waypoints = { { mapID = 114, x = 0.275, y = 0.266, step = 1, label = "Eye of Eternity - highest Nexus portal" } },
        tips = "No old Eye of Eternity key is needed. Do not leave the instance while the platform and drake transitions run.",
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=623",
        sourceURL = "https://www.wowhead.com/achievement=623#comments",
        difficultyReason = "Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.",
