    },
    [624] = {
        achievementId = 624,
        name = "Less Is More (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Less Is More (10 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Set Legacy Raid Size to 10 players outside. Enter the chamber beneath Wyrmrest Temple in Dragonblight (59.8, 54.6) and choose OBSIDIAN SANCTUM, not Ruby Sanctum.\n\n2. Keep at most 8 players inside throughout the run. Kill Tenebron, Shadron and Vesperon SEPARATELY on their ledges before attacking Sartharion. Each named drake is a checklist criterion.\n\n3. Then kill Sartharion on the central island. Killing Sartharion first causes unengaged drakes to disappear and can leave Less Is More incomplete, even though it is a good route for the three-drake mount.",
        stepCount = 3,
        waypoints = { { mapID = 115, x = 0.598, y = 0.546, step = 1, label = "Obsidian Sanctum - below Wyrmrest Temple" } },
        sources = { "https://www.wowhead.com/achievement=624#comments:id=2075942" },
        wowheadUrl = "https://www.wowhead.com/achievement=624",
        sourceURL = "https://www.wowhead.com/achievement=624#comments",
        difficultyReason = "Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.",
        difficulty = "easy",
    },
    [625] = {
        achievementId = 625,
        name = "Besting the Black Dragonflight (25 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Besting the Black Dragonflight (25 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Set Legacy Raid Size to 25 players outside. Enter the chamber beneath Wyrmrest Temple in Dragonblight (59.8, 54.6) and choose OBSIDIAN SANCTUM, not Ruby Sanctum.\n\n2. Clear a safe route to Sartharion on the central island. Killing the three side drakes first is optional for this simple clear.\n\n3. At high level, go straight to Sartharion and kill him before Shadron lands and grants immunity. A fast kill with the drakes alive at the pull is valid; you do not have to wait for all three to land. Loot the boss before leaving.",
        stepCount = 3,
        waypoints = { { mapID = 115, x = 0.598, y = 0.546, step = 1, label = "Obsidian Sanctum - below Wyrmrest Temple" } },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=625",
