    [734] = {
        achievementId = 734,
        name = "Professional Northrend Master",
        category = "Professions",
        sourceType = "Achievement",
        source = "Professional Northrend Master",
        acquisition = "Difficulty: Medium - Raise the required Northrend profession categories to 75 using expansion-specific recipes or gathering.\n\n1. Open your primary professions and choose one Northrend categories to raise. Cooking and Fishing are secondary professions and do not count. Use professions you already want to keep; changing professions can discard learned recipes.\n\n2. Visit the matching trainers in Dalaran's Magus Commerce Exchange and learn their Northrend training. For a gathering profession, gather Northrend nodes/beasts with its Northrend skill learned. For a crafting profession, use its Northrend recipes and materials, replacing recipes as they stop granting skill.\n\n3. Reach 75 base skill in that Northrend primary-profession category. Check the expansion bars directly; training a title or reaching 75 in another expansion is insufficient.\n\n4. Confirm achievement credit. A second completed Northrend primary profession also advances Working In the Cold.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 125,
                x = 0.39,
                y = 0.29,
                step = 2,
                label = "Magus Commerce Exchange - choose the matching profession trainer",
            },
        },
        tips = "Retail replaced the old 350/450 total-skill and Grand Master rank descriptions with 75 skill in the Northrend category.",
        sources = {
            "https://www.wowhead.com/achievement=734#comments:id=372530",
            "https://www.wowhead.com/achievement=734#comments:id=1375916",
            "https://www.wowhead.com/achievement=734#comments:id=1589517",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=734",
        sourceURL = "https://www.wowhead.com/achievement=734#comments",
        difficultyReason = "Raise the required Northrend profession categories to 75 using expansion-specific recipes or gathering.",
        difficulty = "medium",
    },
    [735] = {
        achievementId = 735,
        name = "Working In the Cold",
        category = "Professions",
        sourceType = "Achievement",
        source = "Working In the Cold",
        acquisition = "Difficulty: Medium - Raise the required Northrend profession categories to 75 using expansion-specific recipes or gathering.\n\n1. Open your primary professions and choose two Northrend categories to raise. Cooking and Fishing are secondary professions and do not count. Use professions you already want to keep; changing professions can discard learned recipes.\n\n2. Visit the matching trainers in Dalaran's Magus Commerce Exchange and learn their Northrend training. For a gathering profession, gather Northrend nodes/beasts with its Northrend skill learned. For a crafting profession, use its Northrend recipes and materials, replacing recipes as they stop granting skill.\n\n3. Reach 75 base skill in each of two Northrend primary-profession categories. Check the expansion bars directly; training a title or reaching 75 in another expansion is insufficient.\n\n4. Check both criteria in Working In the Cold. Its current progress is account-wide, but one character with both chosen professions provides a straightforward route without relying on the old Grand Master training rules.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 125,
                x = 0.39,
                y = 0.29,
                step = 2,
                label = "Magus Commerce Exchange - choose the matching profession trainer",
