        tips = "Retail replaced the old 350/450 total-skill and Grand Master rank descriptions with 75 skill in the Northrend category.",
        sources = {
            "https://www.wowhead.com/achievement=735#comments:id=338804",
            "https://www.wowhead.com/achievement=735#comments:id=784251",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=735",
        sourceURL = "https://www.wowhead.com/achievement=735#comments",
        difficultyReason = "Raise the required Northrend profession categories to 75 using expansion-specific recipes or gathering.",
        difficulty = "medium",
    },
    [938] = {
        achievementId = 938,
        name = "The Snows of Northrend",
        category = "Quests",
        sourceType = "Achievement",
        source = "The Snows of Northrend",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. At Nesingwary Base Camp in Sholazar Basin (27, 58), finish Weslex Quickwrench's Need an Engine, Take an Engine and Have a Part, Give a Part. Complete Debaar's Venture Co. Misadventure and Wipe That Grin Off His Face to unlock the hunting branches.\n\n2. Finish ALL three mastery chains: Hemet's Rhino Mastery: The Test / The Chase, An Offering for Soo-rahm, The Bones of Nozronn and Rhino Mastery: The Kill; Buck Cantwell's Dreadsaber Mastery through Ready to Pounce; and Debaar's Crocolisk Mastery through The Ambush. Soo-rahm is near 25, 66 if that follow-up is missing.\n\n3. Take Hemet's In Search of Bigger Game and report to Dorian Drakestalker near the Savage Thicket (42.3, 28.7). Complete Securing the Bait and Sharpening Your Talons.\n\n4. At Dorian's camp complete Zootfizzle's A Mammoth Undertaking. Use its quest interaction to bring back a mammoth. Replies establish that My Pet Roc and Reagent Agent are optional for the achievement's final hunt.\n\n5. Accept Dorian's Post-partum Aggression, carry out the quest's mammoth/dragon attack and return for the final turn-in. Killing random basin wildlife or only finishing the three early mastery chains is insufficient.",
        stepCount = 5,
        waypoints = {
            {
                mapID = 119,
                x = 0.27,
                y = 0.585,
                step = 1,
                label = "Nesingwary Base Camp - engine and Venture Co. prerequisites",
            },
            { mapID = 119, x = 0.25, y = 0.66, step = 2, label = "Soo-rahm - rhino mastery follow-up" },
            { mapID = 119, x = 0.423, y = 0.287, step = 3, label = "Dorian's camp - bigger game" },
            { mapID = 119, x = 0.423, y = 0.287, step = 4, label = "Zootfizzle - A Mammoth Undertaking" },
            { mapID = 119, x = 0.423, y = 0.287, step = 5, label = "Dorian - Post-partum Aggression" },
        },
        sources = { "https://www.wowhead.com/achievement=938#comments:id=548389" },
        wowheadUrl = "https://www.wowhead.com/achievement=938",
        sourceURL = "https://www.wowhead.com/achievement=938#comments",
        difficultyReason = "Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.",
        difficulty = "medium",
    },
    [947] = {
        achievementId = 947,
        name = "The Argent Crusade",
        category = "Reputation",
        sourceType = "Achievement",
        source = "The Argent Crusade Exalted",
        acquisition = "Difficulty: Medium - Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.\n\nDifficulty: Medium - Complete the faction introduction to Friendly and buy its guaranteed reputation tabard.\n\n1. Check Argent Crusade reputation. At Friendly or higher, skip to step 4. Argent Dawn is separate and does not satisfy this purchase.\n\n2. At the Argent Vanguard in southeastern Icecrown (around 87.0, 76.0), enable Trivial Quests. Start Honor Above All Else if offered and report to Crusade Commander Entari. Take Scourge Tactics, Defending the Vanguard and Curing the Incurable as available.\n\n3. Outside the camp, free the webbed crusaders, kill the requested nerubians and loot venom sacs for the cure. Turn in and follow the rescue/defense chain until Friendly. Existing Plaguelands or Zul'Drak quest progress can already have supplied the reputation.\n\n4. Find Veteran Crusader Aliocha Segard at the upper camp (87.6, 75.6), by the tents near Tirion. Buy Tabard of the Argent Crusade for up to 1 gold, then equip it to learn the appearance.\n\n5. For optional further reputation, keep the physical tabard equipped and clear Heroic Halls of Lightning in the Storm Peaks (45.4, 21.4). Check your reputation bar after the first kills. Other original Wrath heroics also work; transmog alone does not champion the faction.\n\n6. Keep the PHYSICAL reputation tabard equipped, not just its transmog appearance. Enter an eligible original Wrath Heroic dungeon such as Utgarde Keep or Gundrak and kill trash/bosses while checking that reputation is awarded to The Argent Crusade. Current-expansion dungeons and Wrath raids are not the tabard farm.\n\n7. For repeat visits, rotate through different unsaved original Wrath Heroics after boss kills. For a repeatable Normal route, enter Halls of Lightning at 45.3, 21.6 in Storm Peaks, clear its enemies and bosses, leave, reset outside and repeat. Check reputation after the first kills and respect the instance-entry limit. Ordinary Normal Utgarde Keep is not equivalent to Normal Halls of Lightning for Northrend championing.\n\n8. Continue to EXALTED and confirm the achievement. Friendly only unlocks the tabard; owning it or learning the appearance is not the achievement. Supplement with the faction's Northrend story/daily quests if desired. Old Justice Point commendation purchases are no longer a Retail route.",
        stepCount = 8,
        waypoints = {
            {
                mapID = 118,
                x = 0.87,
                y = 0.76,
                step = 2,
                label = "Argent Vanguard - introductory quest hub",
                mapName = "Icecrown",
            },
            {
                mapID = 118,
                x = 0.8759999999999999,
                y = 0.7559999999999999,
                step = 4,
                label = "Aliocha Segard - Friendly reputation tabard",
                mapName = "Icecrown",
            },
            {
                mapID = 120,
                x = 0.45399999999999996,
                y = 0.214,
                step = 5,
                label = "Halls of Lightning - optional Heroic reputation",
                mapName = "The Storm Peaks",
            },
            {
                mapID = 117,
                x = 0.5820000000000001,
                y = 0.489,
                step = 6,
                label = "Utgarde Keep - original Heroic reputation run",
            },
            { mapID = 121, x = 0.763, y = 0.21100000000000002, step = 6, label = "Gundrak - original Heroic reputation run" },
            {
                mapID = 120,
                x = 0.45299999999999996,
                y = 0.21600000000000003,
                step = 7,
                label = "Normal Halls of Lightning - repeatable tabard reputation",
            },
        },
        tips = "This is the Friendly reputation tabard, not Argent Crusader's Tabard with its tournament teleport. Shadowlands pre-event vendor moves and Honor-to-Justice conversions are not the normal Retail purchase route. Follow the reputation bar after the first kills so an unequipped tabard or ineligible instance does not waste a run.",
        wowheadUrl = "https://www.wowhead.com/achievement=947",
        sourceURL = "https://www.wowhead.com/achievement=947#comments",
        sources = {
            "https://www.wowhead.com/achievement=947#comments",
            "https://www.wowhead.com/item=43154#comments",
            "https://www.wowhead.com/item=43156#comments:id=1337598",
            "https://www.wowhead.com/achievement=1010#comments:id=2514794",
            "https://www.wowhead.com/achievement=1010#comments:id=5162710",
        },
        difficultyReason = "Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.",
        difficulty = "medium",
    },
    [949] = {
        achievementId = 949,
        name = "Tuskarrmageddon",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Tuskarrmageddon",
        acquisition = "Difficulty: Medium - Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.\n\n1. Complete the Kalu'ak story quests in Borean Tundra (Kaskala/Unu'pe and Karuk), Dragonblight (Moa'ki Harbor), and Howling Fjord (Kamagua/Ancient Lift). These unlock three different dailies and provide initial reputation. This is The Kalu'ak, not Dragonflight's Iskaara Tuskarr.\n\n2. In Borean Tundra, take Preparing for the Worst from Utaik at 63.8, 45.8. Collect eight Kaskala Supplies from the nearby attacked village and turn them in.\n\n3. In Dragonblight, take Planning for the Future from Trapper Mau'i at Moa'ki Harbor (48.2, 74.2). Collect twelve Snowfall Glade Pups from the nearby wolvar settlement and return them.\n\n4. In Howling Fjord, take The Way to His Heart... from Anuniaq at Kamagua (24.6, 58.8). Obtain Tasty Reef Fish using the quest's fish interaction, then toss them at a Reef Bull repeatedly, moving it toward a Reef Cow until the objective credits. Bring enough fish to maintain the lure across the water.\n\n5. If Anuniaq has no daily, complete the Ancient Lift/Kamagua introduction and the pirate follow-ups at Scalawag Point, including the bull-seal blubber quest. The coastal pirate branch can be a prerequisite despite appearing unrelated.\n\n6. Repeat all three available dailies after resets until Exalted. Each gives 500 base reputation (1,500 per full day before bonuses). Reaching the daily stage does not guarantee that the earlier story left you at a particular reputation value.",
        stepCount = 6,
        waypoints = {
            { mapID = 114, x = 0.638, y = 0.45799999999999996, step = 2, label = "Utaik - Preparing for the Worst" },
            { mapID = 115, x = 0.48200000000000004, y = 0.742, step = 3, label = "Trapper Mau'i - Planning for the Future" },
            { mapID = 117, x = 0.24600000000000002, y = 0.588, step = 4, label = "Anuniaq - The Way to His Heart..." },
            { mapID = 117, x = 0.36, y = 0.8, step = 5, label = "Scalawag Point - missing Kamagua daily prerequisites" },
        },
        tips = "There is no Kalu'ak tabard that converts dungeon kills to this reputation. Old guild-reputation perks and fixed completion-time promises are omitted.",
        sources = {
            "https://www.wowhead.com/achievement=949#comments:id=560842",
            "https://www.wowhead.com/achievement=949#comments:id=1151435",
            "https://www.wowhead.com/achievement=949#comments:id=1845905",
            "https://www.wowhead.com/achievement=949#comments:id=5307034",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=949",
        sourceURL = "https://www.wowhead.com/achievement=949#comments",
        difficultyReason = "Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.",
        difficulty = "medium",
    },
    [950] = {
        achievementId = 950,
        name = "Frenzyheart Tribe",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Frenzyheart Tribe",
        acquisition = "Difficulty: Medium - Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.\n\n1. If the faction story is unfinished, kill Pitch near 50.6, 76.8 in Sholazar Basin and accept Playing Along from Tracker Gekgek. Follow the Frenzyheart jobs through Just Following Orders, help the injured Oracle, and finish the Oracle story through A Hero's Burden. Nesingwary's hunting chain is not required to start this faction chain.\n\n2. Enter Artruis's cave at 70.8, 58.7 and reach the lich near 72.2, 57.5. Damage him carefully, then STOP until he releases Jaloot and Zepik. Kill JALOOT, keep ZEPIK alive, then finish Artruis without area damage that kills your survivor.\n\n3. Speak to Zepik immediately. Complete Frenzyheart Champion, then Return of the Lich Hunter and report to Frenzyheart Hill (55.0, 69.2).\n\n4. At Frenzyheart Hill, take all THREE dailies: Elder Harkek's Chicken Party!, Rejek's rotating task and Vekgar's rotating combat task. Follow the combat task to Shaman Jakjek near Kartak's Hold where instructed.\n\n5. Complete the current three quests, including each task's supplied item/companion, and return after daily resets until Exalted. The base full-day total is 1,700 reputation. Enable Trivial Quests if markers are missing and stay with this faction while finishing its eight-daily achievement.\n\n6. If pursuing Mercenary of Sholazar, reach Exalted and finish Honorary Frenzyheart BEFORE switching. Many collectors do Frenzyheart first, then keep Oracles for its repeatable mount/pet eggs.",
        stepCount = 6,
        waypoints = {
            { mapID = 119, x = 0.506, y = 0.768, step = 1, label = "Pitch / Tracker Gekgek - Playing Along" },
            { mapID = 119, x = 0.708, y = 0.5870000000000001, step = 2, label = "Artruis cave entrance" },
            { mapID = 119, x = 0.722, y = 0.575, step = 2, label = "Artruis - save Zepik, kill Jaloot" },
            { mapID = 119, x = 0.55, y = 0.6920000000000001, step = 3, label = "Frenzyheart Hill - return follow-up" },
            { mapID = 119, x = 0.55, y = 0.6920000000000001, step = 4, label = "Pick up ALL three dailies" },
        },
        tips = "At high level, remove damage/proc gear and control damage so Artruis releases BOTH prisoners. Kill only the unwanted faction's prisoner. Complete the survivor's faction quest AND return-to-camp follow-up; merely killing the lich does not unlock the dailies. Switching can reset standing and is limited by the daily reset.",
        sources = {
            "https://www.wowhead.com/achievement=950#comments:id=1112248",
            "https://www.wowhead.com/achievement=950#comments:id=3177091",
            "https://www.wowhead.com/achievement=961#comments:id=3306010",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=950",
        sourceURL = "https://www.wowhead.com/achievement=950#comments",
        difficultyReason = "Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.",
        difficulty = "medium",
    },
    [951] = {
        achievementId = 951,
        name = "The Oracles",
        category = "Reputation",
        sourceType = "Achievement",
        source = "The Oracles",
        acquisition = "Difficulty: Medium - Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.\n\n1. If the faction story is unfinished, kill Pitch near 50.6, 76.8 in Sholazar Basin and accept Playing Along from Tracker Gekgek. Follow the Frenzyheart jobs through Just Following Orders, help the injured Oracle, and finish the Oracle story through A Hero's Burden. Nesingwary's hunting chain is not required to start this faction chain.\n\n2. Enter Artruis's cave at 70.8, 58.7 and reach the lich near 72.2, 57.5. Damage him carefully, then STOP until he releases Jaloot and Zepik. Kill ZEPIK, keep JALOOT alive, then finish Artruis without area damage that kills your survivor.\n\n3. Speak to Jaloot immediately. Complete Hand of the Oracles, then Return of the Friendly Dryskin and report to High-Oracle Soo-say at Rainspeaker Canopy (54.6, 56.3).\n\n4. At Rainspeaker Canopy, take all THREE dailies: High-Oracle Soo-say's treasure task, Soo-nee's rotating song task, and Soo-dow's rotating combat task. Soo-dow can be hidden inside the tree on the north side. Follow the combat task to Lightningcaller Soo-met near Sparktouched Haven.\n\n5. Complete the current three quests, including each task's supplied item/companion, and return after daily resets until Exalted. The base full-day total is 1,700 reputation. Enable Trivial Quests if markers are missing and stay with this faction while finishing its eight-daily achievement.\n\n6. At Revered, Geen's Mysterious Eggs offer an optional mount/pet project, but buying or hatching an egg is not required for the Exalted achievement. Stay with the Oracles afterward if you want continued egg access.",
        stepCount = 6,
        waypoints = {
            { mapID = 119, x = 0.506, y = 0.768, step = 1, label = "Pitch / Tracker Gekgek - Playing Along" },
            { mapID = 119, x = 0.708, y = 0.5870000000000001, step = 2, label = "Artruis cave entrance" },
            { mapID = 119, x = 0.722, y = 0.575, step = 2, label = "Artruis - save Jaloot, kill Zepik" },
            { mapID = 119, x = 0.546, y = 0.563, step = 3, label = "Rainspeaker Canopy - return follow-up" },
            { mapID = 119, x = 0.546, y = 0.563, step = 4, label = "Pick up ALL three dailies" },
        },
        tips = "At high level, remove damage/proc gear and control damage so Artruis releases BOTH prisoners. Kill only the unwanted faction's prisoner. Complete the survivor's faction quest AND return-to-camp follow-up; merely killing the lich does not unlock the dailies. Switching can reset standing and is limited by the daily reset.",
        sources = {
            "https://www.wowhead.com/achievement=951#comments:id=873846",
            "https://www.wowhead.com/achievement=951#comments:id=3177094",
            "https://www.wowhead.com/achievement=962#comments:id=2097761",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=951",
        sourceURL = "https://www.wowhead.com/achievement=951#comments",
        difficultyReason = "Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.",
        difficulty = "medium",
    },
    [952] = {
        achievementId = 952,
        name = "Mercenary of Sholazar",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Mercenary of Sholazar",
        acquisition = "Difficulty: Hard - Reach Exalted with both opposing Sholazar factions, recording each side before switching or using separate characters.\n\n1. If the faction story is unfinished, kill Pitch near 50.6, 76.8 in Sholazar Basin and accept Playing Along from Tracker Gekgek. Follow the Frenzyheart jobs through Just Following Orders, help the injured Oracle, and finish the Oracle story through A Hero's Burden. Nesingwary's hunting chain is not required to start this faction chain.\n\n2. Choose Frenzyheart first if you want to end with Oracles egg access: at Artruis, let both prisoners release, kill Jaloot and save Zepik, then finish the lich. Complete Frenzyheart Champion and Return of the Lich Hunter to unlock Frenzyheart Hill's dailies.\n\n3. Do all three Frenzyheart dailies after resets until EXALTED and verify its achievement tick. Finish Honorary Frenzyheart and any purchases you want before switching. Returning to this allegiance later does not restore the old Exalted standing automatically.\n\n4. Return to Artruis's cave, repeat the controlled encounter, this time kill Zepik and save Jaloot. Finish Hand of the Oracles and Return of the Friendly Dryskin to unlock Rainspeaker Canopy's three dailies.\n\n5. Do the Oracles dailies until Exalted and check both recorded criteria. You do not need both factions Exalted simultaneously; the achievement remembers the completed sides. Its current progress is account-wide, so separate characters can also work on opposite allegiances without resetting one character's standing.",
        stepCount = 5,
        waypoints = {
            { mapID = 119, x = 0.506, y = 0.768, step = 1, label = "Pitch - unlock the faction storyline" },
            { mapID = 119, x = 0.708, y = 0.5870000000000001, step = 2, label = "Artruis cave - first choice" },
            {
                mapID = 119,
                x = 0.55,
                y = 0.6920000000000001,
                step = 3,
                label = "Frenzyheart Hill - reach Exalted before switching",
            },
            { mapID = 119, x = 0.708, y = 0.5870000000000001, step = 4, label = "Artruis cave - switch to save Jaloot" },
            { mapID = 119, x = 0.546, y = 0.563, step = 5, label = "Rainspeaker Canopy - second Exalted" },
        },
        tips = "At high level, remove damage/proc gear and control damage so Artruis releases BOTH prisoners. Kill only the unwanted faction's prisoner. Complete the survivor's faction quest AND return-to-camp follow-up; merely killing the lich does not unlock the dailies. Switching can reset standing and is limited by the daily reset.",
        sources = {
            "https://www.wowhead.com/achievement=952#comments:id=518572",
            "https://www.wowhead.com/achievement=952#comments:id=540500",
            "https://www.wowhead.com/achievement=952#comments:id=668866",
            "https://www.wowhead.com/achievement=952#comments:id=1318466",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=952",
        sourceURL = "https://www.wowhead.com/achievement=952#comments",
        difficultyReason = "Reach Exalted with both opposing Sholazar factions, recording each side before switching or using separate characters.",
        difficulty = "hard",
    },
    [961] = {
        achievementId = 961,
        name = "Honorary Frenzyheart",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Honorary Frenzyheart",
        acquisition = "Difficulty: Medium - Unlock the chosen Sholazar allegiance and finish all eight distinct rotating daily quests.\n\n1. Unlock Frenzyheart dailies through the full Pitch/Artruis route in Frenzyheart Tribe's guide. Save Zepik, complete Frenzyheart Champion and Return of the Lich Hunter, then visit Frenzyheart Hill (55, 69.2). You need EIGHT different quests over resets, not eight repetitions of Chicken Party!.\n\n2. Chicken Party!: use the supplied Chicken Net or catch the escapees around the hill until twelve are captured. This daily is offered every day; the other two slots rotate.\n\n3. Tools of War: go to Shaman Jakjek at Kartak's Hold (about 24, 83), take Zepik's traps from the stash and kill fifty Sparktouched Gorlocs using the tools as needed. Kartak's Rampage instead needs an Oracle Blood drop brought to Kartak's altar, then fifty gorloc kills with the supplied power.\n\n4. Secret Strength of the Frenzyheart: obtain the ale from Grimbooze at Nesingwary Base Camp (27, 60), combine it with the quest berries and use the resulting drink for thirty Sparktouched Gorloc kills near Kartak's Hold.\n\n5. The Heartblood's Strength: fill the supplied vial at the Suntouched Pillar (32, 52), kill the Goretalon Matriarch near 59, 23 and combine the required heartblood. Rejek: First Blood instead needs his blade used on the corpses of a Sapphire Hive Wasp, a Hardknuckle Charger and THREE Mistwhisper tribe members; killing without blooding the blade is insufficient.\n\n6. Strength of the Tempest: at Stormwright's Shelf, collect three Essences of the Monsoon and three Essences of the Storm, then take them to the Shrine of the Tempest (about 22, 44) for True Power of the Tempest.\n\n7. A Hero's Headgear: get Venture Co. Explosives at Swindlegrin's Dig (35, 44). Kill a Stormwatcher on the high western shelf, use the explosives and loot its head. Return each completed Rejek task to Frenzyheart Hill.\n\n8. Check all eight quest names and keep returning after resets for missing rotations. Check character-level eligibility and Trivial Quest tracking if fewer than three tasks appear. Old realm-hop guarantees are omitted; do not switch factions until your desired ticks are complete.",
        stepCount = 8,
        waypoints = {
            {
                mapID = 119,
                x = 0.55,
                y = 0.6920000000000001,
                step = 1,
                label = "Frenzyheart Hill - all three daily quest givers",
            },
            { mapID = 119, x = 0.55, y = 0.6920000000000001, step = 2, label = "Chicken Party! - escapees around the hill" },
            { mapID = 119, x = 0.24, y = 0.83, step = 3, label = "Kartak's Hold - combat daily / tools / altar" },
            { mapID = 119, x = 0.27, y = 0.6, step = 4, label = "Grimbooze - ale for Secret Strength" },
            { mapID = 119, x = 0.24, y = 0.83, step = 4, label = "Kartak's Hold - thirty gorlocs" },
