    [962] = {
        achievementId = 962,
        name = "Savior of the Oracles",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Savior of the Oracles",
        acquisition = "Difficulty: Medium - Unlock the chosen Sholazar allegiance and finish all eight distinct rotating daily quests.\n\n1. Unlock the Oracles dailies through Pitch's storyline, save Jaloot at Artruis, and finish Hand of the Oracles AND Return of the Friendly Dryskin. At Rainspeaker Canopy (54.6, 56.3), take three dailies; the combat quest giver Soo-dow is inside the tree on the north side.\n\n2. Appeasing the Great Rain Stone: speak to Soo-say for an Oracle companion/summoning item. Follow the companion's dig interactions and loot six Shiny Treasures. Keep the companion summoned instead of searching for ordinary lootable ground treasure alone.\n\n3. Mastery of the Crystals: collect the three crystal defenses at Sparktouched Haven, then kill fifty Frenzyheart Attackers. Will of the Titans instead needs a Tainted Crystal from the wolvar brought to the Great Lightning Stone to call Soo-holu, followed by fifty kills. Turn the combat task in to Lightningcaller Soo-met near the front.\n\n4. Power of the Great Ones: charge the Dormant Polished Crystal at the exposed Lifeblood Pillar, return to Sparktouched Haven, use its power and kill thirty Frenzyheart Attackers before reporting to Soo-met.\n\n5. Song of Reflection: use the Didgeridoo of Contemplation on TOP of all four named pillars: Glimmering, Suntouched, Mosslight and Skyreach. Land on each top rather than playing the instrument at its base.\n\n6. A Cleansing Song: use the Cleansing Chime at Bittertide Lake, Wintergrasp River and River's Heart; kill each summoned spirit. The three water destinations are in Sholazar Basin, including the river on its eastern side.\n\n7. Song of Wind and Water: use the Tempest Drums at Stormwright's Shelf and use Haiphoon's vehicle actions to devour three Storm Revenants and three Aqueous Spirits, switching forms as required. Song of Fecundity instead needs the Horn of Fecundity played near eight Soaked Fertile Dirt piles on the same shelf.\n\n8. Repeat after daily resets until all EIGHT named quests credit. One treasure quest is fixed; the combat and song slots rotate. A missing rotation is not evidence that the achievement was removed. Stay with the Oracles while finishing these criteria.",
        stepCount = 8,
        waypoints = {
            { mapID = 119, x = 0.546, y = 0.563, step = 1, label = "Rainspeaker Canopy - ALL three daily givers" },
            { mapID = 119, x = 0.546, y = 0.563, step = 2, label = "Soo-say - obtain the digging companion" },
            { mapID = 119, x = 0.335, y = 0.75, step = 3, label = "Sparktouched Haven - crystal / Titan combat task" },
