        tips = "At high level, remove damage/proc gear and control damage so Artruis releases BOTH prisoners. Kill only the unwanted faction's prisoner. Complete the survivor's faction quest AND return-to-camp follow-up; merely killing the lich does not unlock the dailies. Switching can reset standing and is limited by the daily reset.",
