    [1007] = {
        achievementId = 1007,
        name = "The Wyrmrest Accord",
        category = "Reputation",
        sourceType = "Achievement",
        source = "The Wyrmrest Accord Exalted",
        acquisition = "Difficulty: Medium - Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.\n\nDifficulty: Medium - Complete the faction introduction to Friendly and buy its guaranteed reputation tabard.\n\n1. Check The Wyrmrest Accord reputation. At Friendly or higher, skip to step 3. Kirin Tor or another dragonflight's reputation does not substitute.\n\n2. For initial reputation, visit Raelorasz at the Transitus Shield in Coldarra, Borean Tundra (33.2, 34.4). Start Basic Training: kill 10 Coldarra Spellweavers. Continue Hatching a Plan: loot Frozen Axes from Coldarra Wyrmkin and use them to break 5 blue dragon eggs around the base of the Nexus. Continue the Drake Hunt and Cracking the Code chain, checking the Wyrmrest bar after turn-ins. Finish further red-dragon quests until Friendly; already-started Wyrmrest story quests in Dragonblight can supply the remaining reputation too.\n\n3. Travel to Wyrmrest Temple in Dragonblight. Fly to the top terrace, or speak to Tariolstrasz at the western ground entrance (57.8, 54.2) for a drake ride to the top. Do not stop at the middle-floor defenders.\n\n4. Find Cielstrasza on the upper terrace (59.8, 53.0). Buy Tabard of the Wyrmrest Accord for up to 1 gold and equip it. Browse the remaining vendor pages if needed.\n\n5. For optional reputation toward her Red Drake, wear the actual tabard and clear Heroic Halls of Lightning in the Storm Peaks (45.4, 21.4). Confirm Wyrmrest reputation increases. The old level-80 wording does not mean any dungeon at your present character level works.\n\n6. Keep the PHYSICAL reputation tabard equipped, not just its transmog appearance. Enter an eligible original Wrath Heroic dungeon such as Utgarde Keep or Gundrak and kill trash/bosses while checking that reputation is awarded to The Wyrmrest Accord. Current-expansion dungeons and Wrath raids are not the tabard farm.\n\n7. For repeat visits, rotate through different unsaved original Wrath Heroics after boss kills. For a repeatable Normal route, enter Halls of Lightning at 45.3, 21.6 in Storm Peaks, clear its enemies and bosses, leave, reset outside and repeat. Check reputation after the first kills and respect the instance-entry limit. Ordinary Normal Utgarde Keep is not equivalent to Normal Halls of Lightning for Northrend championing.\n\n8. Continue to EXALTED and confirm the achievement. Friendly only unlocks the tabard; owning it or learning the appearance is not the achievement. Supplement with the faction's Northrend story/daily quests if desired. Old Justice Point commendation purchases are no longer a Retail route.",
        stepCount = 8,
        waypoints = {
            {
                mapID = 114,
                x = 0.332,
                y = 0.344,
                step = 2,
                label = "Raelorasz - initial Wyrmrest reputation quests",
                mapName = "Borean Tundra",
            },
            {
