        },
        tips = "Cielstrasza is on the TOP terrace, not the ground entrance or middle-floor daily. Her Red Drake requires Exalted; this tabard only needs Friendly. Follow the reputation bar after the first kills so an unequipped tabard or ineligible instance does not waste a run.",
        wowheadUrl = "https://www.wowhead.com/achievement=1007",
