    [1008] = {
        achievementId = 1008,
        name = "The Kirin Tor",
        category = "Reputation",
        sourceType = "Achievement",
        source = "The Kirin Tor Exalted",
        acquisition = "Difficulty: Medium - Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.\n\nDifficulty: Medium - Complete the faction introduction to Friendly and buy its guaranteed reputation tabard.\n\n1. Check Kirin Tor reputation. If Friendly or higher, skip to step 3. Mages commonly start Friendly and can buy directly; other classes can obtain the tabard too.\n\n2. For Friendly, visit Librarian Donathan at Amber Ledge in Borean Tundra (45.2, 33.4). Start Prison Break: kill Beryl Mage Hunters in the camp just south of the ledge, loot a Beryl Prison Key and open an arcane prison to rescue a mage. Return to Donathan, then follow Abduction and the Amber Ledge investigation chain. For Abduction, weaken the target before using the provided capture item; high-level characters can use Soft Foam Sword on an eligible target to avoid killing it. Keep completing the Kirin Tor follow-ups until Friendly. Many Coldarra red-dragon quests award Wyrmrest instead, so check the reward faction.\n\n3. Go to the original Dalaran above Crystalsong Forest. Enter the Violet Citadel on the west side and climb the interior stairs. Archmage Alvareaux stands upstairs around 25.4, 47.8.\n\n4. At Friendly, buy Tabard of the Kirin Tor for up to 1 gold and equip it. If the shop says you already own a unique item, check bags and bank before trying another copy.\n\n5. For optional reputation, wear the actual tabard and clear Heroic Halls of Lightning in the Storm Peaks (45.4, 21.4). Other original Wrath heroics work too. Normal Halls of Lightning is a repeatable alternative: leave, reset outside and respect the instance limit. Check the reputation bar before repeating runs.\n\n6. Keep the PHYSICAL reputation tabard equipped, not just its transmog appearance. Enter an eligible original Wrath Heroic dungeon such as Utgarde Keep or Gundrak and kill trash/bosses while checking that reputation is awarded to The Kirin Tor. Current-expansion dungeons and Wrath raids are not the tabard farm.\n\n7. For repeat visits, rotate through different unsaved original Wrath Heroics after boss kills. For a repeatable Normal route, enter Halls of Lightning at 45.3, 21.6 in Storm Peaks, clear its enemies and bosses, leave, reset outside and repeat. Check reputation after the first kills and respect the instance-entry limit. Ordinary Normal Utgarde Keep is not equivalent to Normal Halls of Lightning for Northrend championing.\n\n8. Continue to EXALTED and confirm the achievement. Friendly only unlocks the tabard; owning it or learning the appearance is not the achievement. Supplement with the faction's Northrend story/daily quests if desired. Old Justice Point commendation purchases are no longer a Retail route.",
