        tips = "Use Northrend Dalaran, not the Broken Isles city or Dalaran Hearthstone destination. Mages can already be Friendly. Replies warn that many Coldarra quests award Wyrmrest Accord instead of Kirin Tor. Follow the reputation bar after the first kills so an unequipped tabard or ineligible instance does not waste a run.",
