    [1009] = {
        achievementId = 1009,
        name = "Knights of the Ebon Blade",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Knights of the Ebon Blade Exalted",
        acquisition = "Difficulty: Medium - Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.\n\nDifficulty: Medium - Complete the faction introduction to Friendly and buy its guaranteed reputation tabard.\n\n1. If the Shadow Vault is already friendly and Duchess Mynx is visible, skip to step 7. Otherwise enable Trivial Quests and find your faction's flying gunship: The Skybreaker for Alliance or Orgrim's Hammer for Horde.\n\n2. Speak to Thassarian on The Skybreaker or Koltira Deathweaver on Orgrim's Hammer. Accept It's All Fun and Games (12887 Alliance / 12892 Horde). Search the patrol area above Icecrown instead of standing on the ground at one coordinate.\n\n3. Fly to the Ocular above the Shadow Vault (44.3, 21.5). Use the quest item repeatedly on the floating eye until destroyed. Turn in to Baron Sliver outside the vault (44.0, 24.6).\n\n4. Accept I Have an Idea, But First... (12891). Kill and loot nearby Scourge for a Cultist Rod, Abomination Hook, Geist Rope and 5 Scourge Essences. Return these to Sliver for the Sovereign Rod.\n\n5. For Free Your Mind (12893), kill Vile on the ledge near 44.4, 27.0 and Lady Nightswood near 41.8, 24.5. Find The Leaper patrolling the ring above Sliver, starting around 44.3, 23.6. Use the Sovereign Rod on EACH corpse promptly before it despawns. Killing them alone does not complete the conversions.\n\n6. Take If He Cannot Be Turned (12896 / 12897). Enter the vault, activate the weapon rack near the statue and kill General Lightsbane. Return to Thassarian/Koltira on the gunship, then take The Shadow Vault (12898 / 12899) back to the friendly base.\n\n7. Find Duchess Mynx inside, left near the forge (43.4, 20.6). At Friendly with Knights of the Ebon Blade, buy the tabard for up to 1 gold. If still short of Friendly, finish available Ebon Blade follow-ups in the newly opened base.\n\n8. Equip the tabard to learn its appearance. For optional reputation, wear the physical item and clear Heroic Halls of Lightning in the Storm Peaks (45.4, 21.4). Check that Ebon Blade reputation increases; raids and unrelated modern dungeons are not substitutes.\n\n9. Keep the PHYSICAL reputation tabard equipped, not just its transmog appearance. Enter an eligible original Wrath Heroic dungeon such as Utgarde Keep or Gundrak and kill trash/bosses while checking that reputation is awarded to Knights of the Ebon Blade. Current-expansion dungeons and Wrath raids are not the tabard farm.\n\n10. For repeat visits, rotate through different unsaved original Wrath Heroics after boss kills. For a repeatable Normal route, enter Halls of Lightning at 45.3, 21.6 in Storm Peaks, clear its enemies and bosses, leave, reset outside and repeat. Check reputation after the first kills and respect the instance-entry limit. Ordinary Normal Utgarde Keep is not equivalent to Normal Halls of Lightning for Northrend championing.\n\n11. Continue to EXALTED and confirm the achievement. Friendly only unlocks the tabard; owning it or learning the appearance is not the achievement. Supplement with the faction's Northrend story/daily quests if desired. Old Justice Point commendation purchases are no longer a Retail route.",
