        },
        tips = "Death Knight starting reputation does not unlock Mynx. Gunships move: pins mark search areas in the sky, not fixed landing spots. Cold Weather Flying purchases and the old level-77 requirement are obsolete. Follow the reputation bar after the first kills so an unequipped tabard or ineligible instance does not waste a run.",
