    [1010] = {
        achievementId = 1010,
        name = "Northrend Vanguard",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Northrend Vanguard",
        acquisition = "Difficulty: Hard - Complete four separate Northrend Exalted reputation grinds for the meta.\n\n1. Earn Exalted with ALL FOUR factions: Argent Crusade, The Wyrmrest Accord, Kirin Tor and Knights of the Ebon Blade. Check their individual guides for the Friendly unlock, exact vendor and any Shadow Vault phasing prerequisites.\n\n2. At Friendly, buy and equip the first missing faction's actual championing tabard. Clear eligible original Wrath Heroic dungeons, checking that faction in the combat/reputation log. Transmogging its appearance does not redirect reputation.\n\n3. When that faction reaches Exalted, replace its tabard with the next missing faction's tabard and repeat. Heroic Utgarde Keep/Gundrak are simple starting points; rotate unsaved original Heroics or use the Normal Halls of Lightning reset route described in the individual guides.\n\n4. Check all four Exalted criteria. Horde Expedition/Alliance Vanguard, Kalu'ak and the Sholazar factions are separate achievements and do not replace any of these four.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 118,
                x = 0.8759999999999999,
                y = 0.7559999999999999,
                step = 1,
                label = "Argent Crusade - Aliocha Segard",
            },
            { mapID = 115, x = 0.598, y = 0.53, step = 1, label = "Wyrmrest TOP terrace - Cielstrasza" },
            { mapID = 125, x = 0.254, y = 0.478, step = 1, label = "Violet Citadel UPSTAIRS - Archmage Alvareaux" },
            { mapID = 118, x = 0.434, y = 0.20600000000000002, step = 1, label = "Unlocked Shadow Vault - Duchess Mynx" },
            { mapID = 117, x = 0.5820000000000001, y = 0.489, step = 2, label = "Utgarde Keep - equip the correct tabard" },
            { mapID = 121, x = 0.763, y = 0.21100000000000002, step = 2, label = "Gundrak - eligible original Heroic" },
        },
        sources = {
            "https://www.wowhead.com/achievement=1010#comments:id=431007",
            "https://www.wowhead.com/achievement=1010#comments:id=2514794",
