    [1011] = {
        achievementId = 1011,
        name = "The Winds of the North",
        category = "Reputation",
        sourceType = "Achievement",
        source = "The Winds of the North",
        acquisition = "Difficulty: Medium - Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.\n\n1. Open Northrend reputations and track the PARENT reputation, Horde Expedition. This achievement requires that bar at Exalted, rather than all its component factions individually at Exalted.\n\n2. Complete your faction's Borean Tundra, Howling Fjord and Icecrown military quests for initial reputation/spillover. Warsong Hold and Vengeance Landing are useful campaign starting hubs.\n\n3. REMOVE reputation-championing tabards, including city and Northrend faction tabards. Clear eligible original Wrath Heroic dungeons such as Utgarde Keep and Gundrak to receive the default expedition/vanguard reputation instead of redirecting it elsewhere.\n\n4. Check Horde Expedition after the first kills and rotate unsaved Heroics as needed. Reach Exalted on that specific bar and confirm the achievement. An Exalted subfaction alone is not the current requirement.",
        stepCount = 4,
        waypoints = {
            { mapID = 114, x = 0.41600000000000004, y = 0.542, step = 2, label = "Warsong Hold - military reputation" },
            { mapID = 117, x = 0.785, y = 0.309, step = 2, label = "Vengeance Landing - military reputation" },
            { mapID = 117, x = 0.5820000000000001, y = 0.489, step = 3, label = "Utgarde Keep - NO reputation tabard" },
            { mapID = 121, x = 0.763, y = 0.21100000000000002, step = 3, label = "Gundrak - NO reputation tabard" },
        },
        tips = "The original pre-3.0.8 list of three required subfactions was replaced. Use the current parent-faction criterion.",
        sources = {
            "https://www.wowhead.com/achievement=1011#comments:id=504020",
            "https://www.wowhead.com/achievement=1011#comments:id=552564",
            "https://www.wowhead.com/achievement=1011#comments:id=928869",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1011",
        sourceURL = "https://www.wowhead.com/achievement=1011#comments",
        difficultyReason = "Unlock the faction and farm its guaranteed Exalted reputation through quests, tabard runs or dailies.",
        difficulty = "medium",
    },
