    [1254] = {
        achievementId = 1254,
        name = "Friend or Fowl?",
        category = "Quests",
        sourceType = "Achievement",
        source = "Friend or Fowl?",
        acquisition = "Difficulty: Easy - Complete the short turkey-kill or critter-emote checklist; attempts can be repeated without a lockout.\n\n1. Travel to the turkey field west of Explorers' League Outpost in Howling Fjord, around 69.2, 64.6. Find a fresh group of Fjord Turkeys and put a fast, appropriate damage ability on an easy key.\n\n2. Kill one turkey to start the three-minute window, then move immediately between the nearby packs. Kill FIFTEEN Fjord Turkeys before time expires; do not spend the window travelling between distant areas.\n\n3. Use a targeting button such as /targetexact Fjord Turkey to find nearby survivors, then attack them yourself. In Chromie Time their scaled health may require a real attack rather than a tiny low-level hit.\n\n4. Check the kill count and achievement. If another player recently cleared the field, wait for enough respawns before restarting. Do Critter Gitter first if you also want to feed the living turkeys.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 117,
                x = 0.6920000000000001,
                y = 0.6459999999999999,
                step = 1,
                label = "Fjord Turkey field - west of Explorers' League Outpost",
            },
            {
                mapID = 117,
                x = 0.6920000000000001,
                y = 0.6459999999999999,
                step = 2,
                label = "Kill 15 Fjord Turkeys within three minutes",
            },
        },
        sources = {
            "https://www.wowhead.com/achievement=1254#comments:id=462280",
            "https://www.wowhead.com/achievement=1254#comments:id=6018883",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1254",
        sourceURL = "https://www.wowhead.com/achievement=1254#comments",
        difficultyReason = "Complete the short turkey-kill or critter-emote checklist; attempts can be repeated without a lockout.",
        difficulty = "easy",
    },
    [1263] = {
        achievementId = 1263,
        name = "Explore Howling Fjord",
        sourceType = "Achievement",
        source = "Explore Howling Fjord",
        category = "Exploration",
        acquisition = "Difficulty: Easy - Fly through each named subzone and confirm its discovery; combat and random drops are unnecessary.\n\n1. Track Explore Howling Fjord and travel to the named locations below. Flying makes the circuit easier. Move into each discovery area until its criterion ticks; a revealed map image or nearby place label alone does not prove credit.\n\n2. Visit Kamagua (25, 57). Check that this named criterion credits before continuing.\n\n3. Visit Scalawag Point (34, 78). This is the southern pirate island below the Ancient Lift, not the lift platform.\n\n4. Visit Westguard Keep (30, 43). Check that this named criterion credits before continuing.\n\n5. Visit Ember Clutch (39, 50). Check that this named criterion credits before continuing.\n\n6. Visit New Agamand (52, 67). Check that this named criterion credits before continuing.\n\n7. Visit Halgrind (50, 53). Check that this named criterion credits before continuing.\n\n8. Visit Utgarde Keep (58, 46). Check that this named criterion credits before continuing.\n\n9. Visit Nifflevar (68, 54). Check that this named criterion credits before continuing.\n\n10. Visit Baelgun's Excavation Site (72, 71). Check that this named criterion credits before continuing.\n\n11. Visit Ivald's Ruin (78, 46). Check that this named criterion credits before continuing.\n\n12. Visit Baleheim (66, 39). Check north of Nifflevar by the small bridge. Revealing Utgarde Keep can make this look explored before it credits.\n\n13. Visit Cauldros Isle (57, 36). Visit the small island immediately north of Utgarde Keep. Its fog is easy to overlook; it is not an offshore island.\n\n14. Visit Skorn (45, 35). Check that this named criterion credits before continuing.\n\n15. Visit Steel Gate (30, 26). Check that this named criterion credits before continuing.\n\n16. Visit Apothecary Camp (27, 24). Check that this named criterion credits before continuing.\n\n17. Visit Gjalerbron (36, 10). Check that this named criterion credits before continuing.\n\n18. Visit Camp Winterhoof (48, 10). Check that this named criterion credits before continuing.\n\n19. Visit The Twisted Glade (53.77, 16.53). Use this northern glade, rather than relying only on the similarly named Vibrant Glade at 51, 27.\n\n20. Visit Fort Wildervar (60, 15). Check that this named criterion credits before continuing.\n\n21. Visit Giant's Run (68, 27). Check that this named criterion credits before continuing.\n\n22. Visit Vengeance Landing (78, 30). Check that this named criterion credits before continuing.\n\n23. Review every criterion in the achievement. Revisit an unticked location and move around its immediate area if the first approach did not trigger discovery. Cauldros Isle and Baleheim are common missing ticks. Explorers' League Outpost can reveal extra fog, but it is not an extra required criterion.",
        stepCount = 23,
        waypoints = {
            { mapID = 117, x = 0.25, y = 0.57, step = 2, label = "Kamagua" },
            { mapID = 117, x = 0.34, y = 0.78, step = 3, label = "Scalawag Point" },
