            { mapID = 117, x = 0.68, y = 0.54, step = 9, label = "Nifflevar" },
            { mapID = 117, x = 0.72, y = 0.71, step = 10, label = "Baelgun's Excavation Site" },
            { mapID = 117, x = 0.78, y = 0.46, step = 11, label = "Ivald's Ruin" },
            { mapID = 117, x = 0.66, y = 0.39, step = 12, label = "Baleheim" },
            { mapID = 117, x = 0.57, y = 0.36, step = 13, label = "Cauldros Isle" },
            { mapID = 117, x = 0.45, y = 0.35, step = 14, label = "Skorn" },
