            { mapID = 117, x = 0.5377000000000001, y = 0.1653, step = 19, label = "The Twisted Glade" },
            { mapID = 117, x = 0.6, y = 0.15, step = 20, label = "Fort Wildervar" },
            { mapID = 117, x = 0.68, y = 0.27, step = 21, label = "Giant's Run" },
            { mapID = 117, x = 0.78, y = 0.3, step = 22, label = "Vengeance Landing" },
        },
        tips = "Cauldros Isle and Baleheim are common missing ticks. Explorers' League Outpost can reveal extra fog, but it is not an extra required criterion.",
        sources = {
            "https://www.wowhead.com/achievement=1263#comments:id=441139",
