        name = "Explore Borean Tundra",
        sourceType = "Achievement",
        source = "Explore Borean Tundra",
        category = "Exploration",
        acquisition = "Difficulty: Easy - Fly through each named subzone and confirm its discovery; combat and random drops are unnecessary.\n\n1. Track Explore Borean Tundra and travel to the named locations below. Flying makes the circuit easier. Move into each discovery area until its criterion ticks; a revealed map image or nearby place label alone does not prove credit.\n\n2. Visit Valiance Keep (58.78, 68.55). Check that this named criterion credits before continuing.\n\n3. Visit Riplash Strand (46.05, 78.79). Check that this named criterion credits before continuing.\n\n4. Visit Warsong Hold (41.42, 53.62). Check that this named criterion credits before continuing.\n\n5. Visit Garrosh's Landing (31.92, 52.74). Approach the actual landing area even if its label already appears on the map.\n\n6. Visit Coldarra (32.66, 28.26). Fly to the western dragon island; a ground traveller can use Amber Ledge's flight connection.\n\n7. Visit Amber Ledge (45.26, 34.25). Check that this named criterion credits before continuing.\n\n8. Visit Steeljaw's Caravan (49.15, 25.16). This small discovery is north of Amber Ledge and easy to miss.\n\n9. Visit Bor'gorok Outpost (49.7, 10.1). Check that this named criterion credits before continuing.\n\n10. Visit The Geyser Fields (67.08, 32.19). Check that this named criterion credits before continuing.\n\n11. Visit The Dens of the Dying (75.58, 17.05). Search the northern Talramas/necropolis region if the tick does not trigger on the first pass.\n\n12. Visit Temple City of En'kilah (85.42, 25.24). Check that this named criterion credits before continuing.\n\n13. Visit Death's Stand (82.37, 46.69). The discovery toast can use a neighboring subzone name; check the achievement tick.\n\n14. Visit Kaskala (65.8, 46.87). Check that this named criterion credits before continuing.\n\n15. Review every criterion in the achievement. Revisit an unticked location and move around its immediate area if the first approach did not trigger discovery. Do not confuse additional exploration-experience areas with this thirteen-location checklist.",
