aid is not required.\n\n18. Visit Light's Trust (84, 26.1). Check that this named criterion credits before continuing.\n\n19. Visit Scarlet Point (72.5, 26). Check that this named criterion credits before continuing.\n\n20. Review every criterion in the achievement. Revisit an unticked location and move around its immediate area if the first approach did not trigger discovery. This is outdoor exploration. Opposing-faction settlements can be discovered from above without speaking to their NPCs.",
