        acquisition = "Difficulty: Easy - Fly through each named subzone and confirm its discovery; combat and random drops are unnecessary.\n\n1. Track Explore Grizzly Hills and travel to the named locations below. Flying makes the circuit easier. Move into each discovery area until its criterion ticks; a revealed map image or nearby place label alone does not prove credit.\n\n2. Visit Granite Springs (16.2, 47.7). Check that this named criterion credits before continuing.\n\n3. Visit Conquest Hold (21.4, 65.4). Check that this named criterion credits before continuing.\n\n4. Visit Venture Bay (14.6, 86.1). Check that this named criterion credits before continuing.\n\n5. Visit Voldrune (28.9, 74.9). Check that this named criterion credits before continuing.\n\n6. Visit Amberpine Lodge (31.7, 59.4). Check that this named criterion credits before continuing.\n\n7. Visit Rage Fang Shrine (50.3, 57.8). Approach the cave south of Grizzlemaw using the path from about 53, 56. Its name may not be printed on the map.\n\n8. Visit Dun Argol (77.8, 59.4). Check that this named criterion credits before continuing.\n\n9. Visit Camp Oneqwah (65.1, 47.2). Check that this named criterion credits before continuing.\n\n10. Visit Drakil'jin Ruins (71.6, 26). Check that this named criterion credits before continuing.\n\n11. Visit Thor Modan (66.5, 17). Check that this named criterion credits before continuing.\n\n12. Visit Westfall Brigade Encampment (57.2, 30). Check that this named criterion credits before continuing.\n\n13. Visit Grizzlemaw (49.2, 43.9). Check that this named criterion credits before continuing.\n\n14. Visit Blue Sky Logging Grounds (37.3, 36.5). Check that this named criterion credits before continuing.\n\n15. Visit Drak'Tharon Keep (17.6, 28.4). Explore outside the keep; entering the dungeon is unnecessary for this tick.\n\n16. Review every criterion in the achievement. Revisit an unticked location and move around its immediate area if the first approach did not t