    [1268] = {
        achievementId = 1268,
        name = "Explore Sholazar Basin",
        sourceType = "Achievement",
        source = "Explore Sholazar Basin",
        category = "Exploration",
        acquisition = "Difficulty: Easy - Fly through each named subzone and confirm its discovery; combat and random drops are unnecessary.\n\n1. Track Explore Sholazar Basin and travel to the named locations below. Flying makes the circuit easier. Move into each discovery area until its criterion ticks; a revealed map image or nearby place label alone does not prove credit.\n\n2. Visit River's Heart (48, 63). Check that this named criterion credits before continuing.\n\n3. Visit The Mosslight Pillar (36, 75). Check that this named criterion credits before continuing.\n\n4. Visit Kartak's Hold (25, 81). Check that this named criterion credits before continuing.\n\n5. Visit The Suntouched Pillar (33, 52). Check that this named criterion credits before continuing.\n\n6. Visit Makers' Perch (29, 38). Check that this named criterion credits before continuing.\n\n7. Visit The Stormwright's Shelf (26, 35). Fly above and behind Makers' Perch to the western cliff-top shelf; it is not on the basin floor.\n\n8. Visit The Savage Thicket (46, 25). Check that this named criterion credits before continuing.\n\n9. Visit The Glimmering Pillar (49, 38). Check that this named criterion credits before continuing.\n\n10. Visit Rainspeaker Canopy (53, 55). Check that this named criterion credits before continuing.\n\n11. Visit The Lifeblood Pillar (65, 59). Check that this named criterion credits before continuing.\n\n12. Visit Makers' Overlook (80.7, 54.42). Fly to the eastern cliff ledge. The old 81, 12 coordinate is incorrect.\n\n13. Visit The Avalanche (73, 36). Check that this named criterion credits before continuing.\n\n14. Review every criterion in the achievement. Revisit an unticked location and move around its immediate area if the first approach did not trigger discovery. Use flying for the high western shelf and eastern overlook. Old death/resurrection routes and obsolete loan-mount requirements are unnecessary for a flying Retail character.",
