        acquisition = "Difficulty: Easy - Fly through each named subzone and confirm its discovery; combat and random drops are unnecessary.\n\n1. Track Explore Storm Peaks and travel to the named locations below. Flying makes the circuit easier. Move into each discovery area until its criterion ticks; a revealed map image or nearby place label alone does not prove credit.\n\n2. Visit Sparksocket Minefield (36, 81). Check that this named criterion credits before continuing.\n\n3. Visit Garm's Bane (43, 82). Check that this named criterion credits before continuing.\n\n4. Visit Brunnhildar Village (48, 69). Check that this named criterion credits before continuing.\n\n5. Visit Dun Niffelem (62, 60). Check that this named criterion credits before continuing.\n\n6. Visit Temple of Life (66, 50). Check that this named criterion credits before continuing.\n\n7. Visit Thunderfall (70, 49). Check that this named criterion credits before continuing.\n\n8. Visit Terrace of the Makers (58, 44). Check that this named criterion credits before continuing.\n\n9. Visit Ulduar (40, 24). Explore the outdoor Titan complex. You do not need to enter its dungeons or raid.\n\n10. Visit Narvir's Cradle (29, 44). Check that this named criterion credits before continuing.\n\n11. Visit Snowdrift Plains (27, 45). Check that this named criterion credits before continuing.\n\n12. Visit Nidavelir (25, 51). Check that this named criterion credits before continuing.\n\n13. Visit Valkyrion (25, 57). Check that this named criterion credits before continuing.\n\n14. Visit Temple of Storms (34, 56). Use flying to approach Thorim's high temple and move around its immediate discovery area.\n\n15. Visit Engine of the Makers (41, 56). Check that this named criterion credits before continuing.\n\n16. Visit Bor's Breath (24, 70). Check that this named criterion credits before continuing.\n\n17. Visit Frosthold (28, 72). Check that this named criterion credits before continuing.\n\n18. Review every criterion in the achievement. Revisit an unticked location and move around its immediate area if the first approach did not trigger discovery. The old ghost-mount/remote-spirit-healer tricks are unreliable and omitted. Flying provides direct access to the high temples and faction settlements.",
