        sourceType = "Achievement",
        source = "Explore Icecrown",
        category = "Exploration",
        acquisition = "Difficulty: Easy - Fly through each named subzone and confirm its discovery; combat and random drops are unnecessary.\n\n1. Track Explore Icecrown and travel to the named locations below. Flying makes the circuit easier. Move into each discovery area until its criterion ticks; a revealed map image or nearby place label alone does not prove credit.\n\n2. Visit Valley of Echoes (83, 73). Check that this named criterion credits before continuing.\n\n3. Visit Scourgeholme (78, 59). Check that this named criterion credits before continuing.\n\n4. Visit The Broken Front (68, 65). Check that this named criterion credits before continuing.\n\n5. Visit Icecrown Citadel (53, 89). Check that this named criterion credits before continuing.\n\n6. Visit Corp'rethar: The Horror Gate (41, 68). Check that this named criterion credits before continuing.\n\n7. Visit The Conflagration (44, 64). Check that this named criterion credits before continuing.\n\n8. Visit The Fleshwerks (30, 63). Check that this named criterion credits before continuing.\n\n9. Visit Onslaught Harbor (11, 50). Fly to the far western coastal harbor; it is easy to overlook on an inland route.\n\n10. Visit Jotunheim (35, 36). Check that this named criterion credits before continuing.\n\n11. Visit Valhalas (33, 29). Check that this named criterion credits before continuing.\n\n12. Visit The Shadow Vault (45, 16). Check that this named criterion credits before continuing.\n\n13. Visit Sindragosa's Fall (73, 29). Check that this named criterion credits before continuing.\n\n14. Visit The Bombardment (62, 40). Check that this named criterion credits before continuing.\n\n15. Visit Aldur'thar: The Desolation Gate (52, 47). Check that this named criterion credits before continuing.\n\n16. Visit Ymirheim (51, 59). Check that this named criterion credits before continuing.\n\n17. Review every criterion in the achievement. Revisit an unticked location and move around its immediate area if the first approach did not trigger discovery. Move within the named subzone if its broad discovery trigger is not reached at the first pin. Argent Tournament Grounds reveals additional fog but is not an extra criterion for this achievement.",
