    [1277] = {
        achievementId = 1277,
        name = "Rapid Defense",
        category = "Quests",
        sourceType = "Achievement",
        source = "Rapid Defense",
        acquisition = "Difficulty: Medium - Unlock the dragon vehicle daily and finish its objectives and turn-in within three minutes.\n\n1. Unlock Defending Wyrmrest Temple through the Dragonblight dragonshrine chain. If the Shimmering Shard does not drop, first finish Rifle the Bodies (Horde, 11999; Alliance, 12000), then follow its shard investigation and Wyrmrest introductions.\n\n2. Find the daily on Wyrmrest Temple's MIDDLE/SECOND floor, accessible from the west around 58, 54. This is above the ground transport NPCs and below the Dragon Queen, not the basement raid entrance. Track Rapid Defense before accepting the daily: its THREE-minute timer starts at acceptance.\n\n3. Immediately board a nearby Wyrmrest Defender. Fly toward the Azure Dragonshrine southwest of the temple and use Destabilize the Azure Dragonshrine (vehicle action 5) over the quest target. Wait for objective credit rather than assuming the button cooldown means success.\n\n4. While moving, kill three Azure Dragons and five Azure Drakes. Use Immolate (2) followed by Fireball (1), prioritizing wounded enemies fighting friendly NPCs; current high-level vehicle damage can make this much quicker than the old comments describe. Renew (3) heals your vehicle and the speed action (4) helps with travel.\n\n5. Once all objectives credit, speed back to the SAME middle-floor quest giver. EXIT the vehicle and finish the turn-in before three minutes. Completing the kills within the timer but handing in late is not enough; abandon/reaccept before completion if an attempt clearly fails.",
        stepCount = 5,
        waypoints = {
            { mapID = 115, x = 0.38, y = 0.46, step = 1, label = "Agmar's Hammer - Horde dragonshrine introduction" },
            { mapID = 115, x = 0.29, y = 0.55, step = 1, label = "Stars' Rest - Alliance dragonshrine introduction" },
            { mapID = 115, x = 0.58, y = 0.54, step = 2, label = "Wyrmrest Temple MIDDLE floor - accept timed daily" },
            { mapID = 115, x = 0.555, y = 0.662, step = 3, label = "Azure Dragonshrine - vehicle destabilization target" },
            { mapID = 115, x = 0.58, y = 0.54, step = 5, label = "Return, exit drake and turn in before three minutes" },
        },
        tips = "Do the timed daily outside a raid group. Old two-minute instructions, old camera commands and obsolete quest-completion macros are omitted.",
        sources = {
            "https://www.wowhead.com/achievement=1277#comments:id=446096",
            "https://www.wowhead.com/achievement=1277#comments:id=1385789",
            "https://www.wowhead.com/achievement=1277#comments:id=1810446",
            "https://www.wowhead.com/achievement=1277#comments:id=6285532",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1277",
        sourceURL = "https://www.wowhead.com/achievement=1277#comments",
        difficultyReason = "Unlock the dragon vehicle daily and finish its objectives and turn-in within three minutes.",
        difficulty = "medium",
    },
    [1288] = {
        achievementId = 1288,
        name = "Northrend Dungeonmaster",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Northrend Dungeonmaster",
        acquisition = "Difficulty: Medium - Clear all twelve launch dungeons; the Heroic and title variants add their stated mode or raid requirements.\n\n1. Complete all twelve original Northrend dungeon clear achievements. Normal is sufficient; Heroic clears also award their Normal counterparts. Track the twelve child achievements so a skipped boss is visible.\n\n2. In Howling Fjord, clear Utgarde Keep through both Ingvar phases, then Utgarde Pinnacle through Ymiron. Use the lower and upper portals respectively.\n\n3. On Coldarra in Borean Tundra, clear the Nexus through Keristrasza and the Oculus through Eregos. Use the lowest and upper portals respectively.\n\n4. In Dragonblight's western pit, clear Azjol-Nerub via the right branch and Ahn'kahet via the left. On Heroic, include Amanitar's mushroom cavern.\n\n5. Clear Drak'Tharon Keep in southwestern Zul'Drak, then Gundrak in the northeast. Activate Gundrak's three altars; on Heroic, also kill Eck in the side cavern.\n\n6. At Ulduar in The Storm Peaks, clear Halls of Stone, including Krystallus, Maiden, Brann's event and Sjonnir, and Halls of Lightning through Loken.\n\n7. Clear the original Violet Hold in Northrend Dalaran through wave 18. Travel to Tanaris's Caverns of Time for the Culling of Stratholme and escort Arthas through Mal'Ganis. Trial of the Champion and the three Frozen Halls dungeons are not required.",
        stepCount = 7,
        waypoints = {
            { mapID = 117, x = 0.5820000000000001, y = 0.489, step = 2, label = "Utgarde Keep - lower entrance" },
            { mapID = 117, x = 0.573, y = 0.467, step = 2, label = "Utgarde Pinnacle - upper entrance" },
            { mapID = 114, x = 0.275, y = 0.267, step = 3, label = "The Nexus - lowest portal" },
            { mapID = 114, x = 0.28600000000000003, y = 0.275, step = 3, label = "The Oculus - upper portal" },
            { mapID = 115, x = 0.26, y = 0.508, step = 4, label = "Azjol-Nerub - right branch" },
            { mapID = 115, x = 0.284, y = 0.517, step = 4, label = "Ahn'kahet - left branch" },
            { mapID = 121, x = 0.28600000000000003, y = 0.8690000000000001, step = 5, label = "Drak'Tharon Keep" },
            { mapID = 121, x = 0.764, y = 0.213, step = 5, label = "Gundrak" },
            { mapID = 120, x = 0.401, y = 0.26899999999999996, step = 6, label = "Halls of Stone" },
            { mapID = 120, x = 0.45299999999999996, y = 0.21600000000000003, step = 6, label = "Halls of Lightning" },
            { mapID = 125, x = 0.665, y = 0.6779999999999999, step = 7, label = "The Violet Hold - Northrend Dalaran" },
            { mapID = 75, x = 0.569, y = 0.8240000000000001, step = 7, label = "Culling of Stratholme - Caverns of Time" },
        },
        tips = "Use the individual dungeon guides for room-by-room progression. A mount-drake challenge, timed run or special boss mechanic is not required by these two clear metas.",
        sources = { "https://www.wowhead.com/achievement=1288#comments:id=903550" },
        wowheadUrl = "https://www.wowhead.com/achievement=1288",
        sourceURL = "https://www.wowhead.com/achievement=1288#comments",
        difficultyReason = "Clear all twelve launch dungeons; the Heroic and title variants add their stated mode or raid requirements.",
        difficulty = "medium",
    },
    [1289] = {
        achievementId = 1289,
        name = "Northrend Dungeon Hero",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Northrend Dungeon Hero",
        acquisition = "Difficulty: Medium - Clear all twelve launch dungeons; the Heroic and title variants add their stated mode or raid requirements.\n\n1. Set Dungeon Difficulty to HEROIC outside each instance. Complete all twelve original Northrend Heroic clear achievements; no reputation key is required. This is not the encounter-challenge meta Glory of the Hero.\n\n2. In Howling Fjord, clear Utgarde Keep through both Ingvar phases, then Utgarde Pinnacle through Ymiron. Use the lower and upper portals respectively.\n\n3. On Coldarra in Borean Tundra, clear the Nexus through Keristrasza and the Oculus through Eregos. Use the lowest and upper portals respectively.\n\n4. In Dragonblight's western pit, clear Azjol-Nerub via the right branch and Ahn'kahet via the left. On Heroic, include Amanitar's mushroom cavern.\n\n5. Clear Drak'Tharon Keep in southwestern Zul'Drak, then Gundrak in the northeast. Activate Gundrak's three altars; on Heroic, also kill Eck in the side cavern.\n\n6. At Ulduar in The Storm Peaks, clear Halls of Stone, including Krystallus, Maiden, Brann's event and Sjonnir, and Halls of Lightning through Loken.\n\n7. Clear the original Violet Hold in Northrend Dalaran through wave 18. Travel to Tanaris's Caverns of Time for the Culling of Stratholme and escort Arthas through Mal'Ganis. Trial of the Champion and the three Frozen Halls dungeons are not required.",
        stepCount = 7,
        waypoints = {
            { mapID = 117, x = 0.5820000000000001, y = 0.489, step = 2, label = "Utgarde Keep - lower entrance" },
            { mapID = 117, x = 0.573, y = 0.467, step = 2, label = "Utgarde Pinnacle - upper entrance" },
            { mapID = 114, x = 0.275, y = 0.267, step = 3, label = "The Nexus - lowest portal" },
