    [1296] = {
        achievementId = 1296,
        name = "Watch Him Die",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Watch Him Die",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Dungeon Difficulty to HEROIC outside Azjol-Nerub. In western Dragonblight, enter the Nerubian pit and take the RIGHT branch by the meeting stone; the left branch is Ahn'kahet.\n\n2. Reach the first boss chamber, The Gilded Gate. Identify Krik'thir the Gatewatcher behind the three Watchers: Gashra, Narjil and Silthik. Leave ALL THREE Watchers alive; do not clear their packs with area damage as you normally might.\n\n3. At high level, run into range and kill KRIK'THIR with a direct single-target attack before touching the Watchers. Dismiss uncontrolled pets and avoid cleaves or damage procs that could kill a Watcher first. The Watchers do not have to be pulled or killed to make this achievement count.\n\n4. Check for Watch Him Die after Krik'thir's death, then clean up any remaining attackers. You may kill the Watchers after the achievement has credited. Old ledge-climbing, sacrificial kiting, raid-gear requirements and level-80 damage targets are unnecessary for this Retail route.",
        stepCount = 4,
        waypoints = {
            { mapID = 115, x = 0.26, y = 0.508, step = 1, label = "Azjol-Nerub - right branch entrance" },
            {
                mapID = 159,
                x = 0.501,
                y = 0.45,
                step = 2,
                label = "Krik'thir - three Watchers must remain alive",
                mapName = "Azjol-Nerub - The Gilded Gate",
            },
            {
                mapID = 159,
                x = 0.501,
                y = 0.45,
                step = 3,
                label = "Single-target Krik'thir BEFORE the Watchers",
                mapName = "Azjol-Nerub - The Gilded Gate",
            },
        },
        tips = "This is the FIRST boss of Azjol-Nerub. Killing the three named Watchers before him fails the attempt even if his own kill is instantaneous.",
        sources = {
            "https://www.wowhead.com/achievement=1296#comments:id=450967",
            "https://www.wowhead.com/achievement=1296#comments:id=1939480",
            "https://www.wowhead.com/achievement=1296#comments:id=3216035",
            "https://www.wowhead.com/achievement=1296#comments:id=3225057",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1296",
        sourceURL = "https://www.wowhead.com/achievement=1296#comments",
        difficultyReason = "A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.",
        difficulty = "easy",
    },
    [1297] = {
        achievementId = 1297,
        name = "Hadronox Denied",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Hadronox Denied",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Enter Azjol-Nerub on HEROIC and defeat Krik'thir. Stop on the web bridge overlooking the next chamber; the three large Crusher groups below are the event trash, not the achievement target.\n\n2. At high level, head down the webbed route toward Hadronox's LOWER chamber before the spider climbs up and seals the top doors. You can bypass the Crusher groups for this approach; killing through the full waiting event gives Hadronox time to move into the normal doorway-closing sequence.\n\n3. Engage Hadronox at the lower end and kill it immediately with single-target damage. Later Retail comments, including The War Within, confirm that an ordinary fast kill works. You do not need a Crashin' Thrashin' Racer, Feign Death, a sacrificed player or an event reset.\n\n4. Confirm Hadronox Denied before clearing the surviving enemies and dropping down the hole toward Anub'arak. If damage is slow, keep Hadronox away from dying poisoned adds, which can heal it; the objective is to kill BEFORE the top doors are webbed, not merely to survive the normal encounter.",
        stepCount = 4,
        waypoints = {
            { mapID = 115, x = 0.26, y = 0.508, step = 1, label = "Azjol-Nerub - entrance" },
            {
                mapID = 159,
                x = 0.501,
                y = 0.45,
                step = 1,
                label = "Krik'thir - clear before Hadronox approach",
                mapName = "Azjol-Nerub - The Gilded Gate",
            },
            {
                mapID = 158,
                x = 0.431,
                y = 0.594,
                step = 2,
                label = "Hadronox - reach the lower chamber early",
                mapName = "Azjol-Nerub - Hadronox's Lair",
            },
            {
                mapID = 158,
                x = 0.431,
                y = 0.594,
                step = 3,
                label = "Kill Hadronox before the top doors are sealed",
                mapName = "Azjol-Nerub - Hadronox's Lair",
            },
        },
        tips = "Do not wait upstairs for the normal event to finish, and do not jump into Anub'arak's one-way drop before finishing Hadronox.",
        sources = {
            "https://www.wowhead.com/achievement=1297#comments:id=511332",
            "https://www.wowhead.com/achievement=1297#comments:id=1676946",
            "https://www.wowhead.com/achievement=1297#comments:id=1841261",
            "https://www.wowhead.com/achievement=1297#comments:id=5968445",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1297",
        sourceURL = "https://www.wowhead.com/achievement=1297#comments",
        difficultyReason = "A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.",
        difficulty = "easy",
    },
    [1356] = {
        achievementId = 1356,
        name = "I've Toured the Fjord",
        category = "Quests",
        sourceType = "Achievement",
        source = "I've Toured the Fjord",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Begin at Vengeance Landing and follow its Visitors from the Keep and Volatile Viscera branches. Continue the New Agamand and Apothecary Camp chains for A New Plague and the Scourge/Vrykul chapters.\n\n2. Follow the Skorn campaign and the Bjorn Halgurdsson assassination chain. Complete the Iron Dwarf and Doom Approaches chapters from the northern camps rather than counting unrelated side quests.\n\n3. Complete the northern Fort Wildervar/Camp Winterhoof branches through Alpha Worg. Check the Sisters of the Fjord chain and the nearby forest quest givers if those chapters remain unfinished.\n\n4. Visit Kamagua and Ancient Lift, then follow the pirate story to Scalawag Point. Finish The Debt Collector and The End of Jonah Sterling. Board Captain Ellis's moving ghost ship, The Sister Mercy, for its required quests; he is easy to miss when no land quest marker is visible.\n\n5. Finish the remaining faction-specific chapter shown in your checklist, then check all twelve ticks. On Horde, The Book of Runes chain and Captain Ellis's ship are frequent missing links; on Alliance, verify To Westguard Keep! and the complete Iron Rune Construct sequence.",
        stepCount = 5,
        waypoints = {
            { mapID = 117, x = 0.785, y = 0.309, step = 1, label = "Vengeance Landing - Horde introduction" },
            { mapID = 117, x = 0.53, y = 0.6679999999999999, step = 2, label = "New Agamand - plague storyline" },
            { mapID = 117, x = 0.49, y = 0.12, step = 3, label = "Camp Winterhoof - northern chains" },
            { mapID = 117, x = 0.25, y = 0.58, step = 4, label = "Kamagua - follow the pirate introductions" },
            { mapID = 117, x = 0.36, y = 0.8, step = 4, label = "Scalawag Point - pirate and ghost-ship chains" },
        },
        tips = "Enable Trivial Quests in tracking and follow the full named chapter to its final turn-in. A missing quest marker can mean a prerequisite, a quest-starting item in your bags, or a summons item with its own quest giver. Old 100/130/150-quest counters no longer describe this Retail achievement.",
        sources = {
            "https://www.wowhead.com/achievement=34#comments:id=2551702",
            "https://www.wowhead.com/achievement=1356#comments:id=2551073",
            "https://www.wowhead.com/achievement=1356#comments:id=6270059",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1356",
        sourceURL = "https://www.wowhead.com/achievement=1356#comments",
        difficultyReason = "Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.",
        difficulty = "medium",
    },
    [1357] = {
        achievementId = 1357,
        name = "Fo' Grizzle My Shizzle",
        category = "Quests",
        sourceType = "Achievement",
        source = "Fo' Grizzle My Shizzle",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Begin at Conquest Hold and Camp Oneqwah. Follow their military and eastern Iron Dwarf branches through The Final Showdown, Loken's Orders and The Iron Thane. Complete the vehicle/event quests rather than stopping at the first Dun Argol objective.\n\n2. Complete the Ursoc, the Bear God chain in the northern Grizzlemaw/Ursoc's Den area. Follow the quests through Ursoc's own encounter and final turn-in; simply killing the bear without the quest does not complete the chapter.\n\n3. Work through the Silverbrook, trapper and Sasha chains in western Grizzly Hills to Hour of the Worg. Loot and inspect Mikhail's Journal where your branch requires its quest-starting drop.\n\n4. At Granite Springs, start Truce? with Drakuru and finish Vial of Visions, Subject to Interpretation, Sacrifices Must Be Made and the remaining spirit tasks. Keep the summoning items; use the Elixir of Visions when entering Drak'Tharon for the Revelation! conclusion.\n\n5. Complete the remaining Eons of Misery storyline and check all faction chapters. If a Drakuru task appears to have vanished, look for the vial/summons quest in your log and bags. Do not substitute unrelated PvP dailies or assume Harrison Jones is mandatory for the present chapter checklist.",
        stepCount = 5,
        waypoints = {
