    [1359] = {
        achievementId = 1359,
        name = "Might of Dragonblight",
        category = "Quests",
        sourceType = "Achievement",
        source = "Might of Dragonblight",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. Start at Agmar's Hammer and Venomspite. Finish The Taunka, The Scarlet Onslaught, Traitors to the Horde and Containing the Rot, returning to each hub after its field quests. Some Venomspite quests are upstairs inside the inn.\n\n2. Complete the ley-line chain from your faction's west-side camp through Redirecting the Ley Lines. Follow its summons and dragon introductions to Wyrmrest Temple; finish Informing the Queen and the Dragonflights branches there.\n\n3. At Moa'ki Harbor, complete the coastal Tuskarr chain through Oacha'noa. At the Crystal Vice, check Nozzlerust Post and Zort's cave-side quests for Strategic Alliance. These neutral hubs are not replaced by completing your faction's military chain.\n\n4. Finish the Dragonblight campaign to Alexstrasza and Return to Angrathar for the Wrathgate chapter. The cinematic and achievement remain available; the old follow-up Battle for Undercity was removed and is not required.\n\n5. Check all ten Horde chapter ticks, including Strategic Alliance and Oacha'noa. If a quest needs a weakened creature, use controlled low damage or a valid outdoor weakening tool rather than one-shotting it.",
        stepCount = 5,
        waypoints = {
            { mapID = 115, x = 0.38, y = 0.46, step = 1, label = "Agmar's Hammer - western Horde chains" },
            { mapID = 115, x = 0.765, y = 0.625, step = 1, label = "Venomspite - Scarlet Onslaught and rot" },
