            { mapID = 115, x = 0.385, y = 0.195, step = 4, label = "Angrathar - Wrathgate conclusion" },
        },
        tips = "Enable Trivial Quests in tracking and follow the full named chapter to its final turn-in. A missing quest marker can mean a prerequisite, a quest-starting item in your bags, or a summons item with its own quest giver. Old 100/130/150-quest counters no longer describe this Retail achievement.",
