    [1428] = {
        achievementId = 1428,
        name = "Mine Sweeper",
        category = "Quests",
        sourceType = "Achievement",
        source = "Mine Sweeper",
        acquisition = "Difficulty: Medium - Chain ten mine launches without landing; positioning and movement can require repeated attempts.\n\n1. Go to the Sparksocket Minefield just west of K3 in Storm Peaks (about 36, 86). Track Mine Sweeper and use the safe path toward the center, the same approach used for Just Around the Corner.\n\n2. Pick two nearby clusters on opposite sides of the center and step/jump onto a mine to begin. As you rise, identify the next mine and turn your camera/character so you can move straight toward it when control returns.\n\n3. On descent, aim to land near another mine. If you touch the ground, immediately run into the next one: there is a short grace period, so brief contact need not ruin the chain. Avoid running out of the minefield or waiting between explosions.\n\n4. Keep criss-crossing between clusters, approaching mines from an angle that tends to send you back into the field. Your facing alone does not guarantee the blast direction; adjust to the actual launch and choose your next mine while airborne.\n\n5. Chain TEN detonations before the counter resets. If a gap resets progress, return to a dense cluster and restart. Between launches, touch the ground briefly near the next mine and adjust your approach angle to keep the chain going.",
        stepCount = 5,
        waypoints = {
            { mapID = 120, x = 0.36, y = 0.86, step = 1, label = "Sparksocket Minefield - center approach" },
            { mapID = 120, x = 0.36, y = 0.86, step = 2, label = "Begin a mine chain in the dense central field" },
            { mapID = 120, x = 0.36, y = 0.86, step = 5, label = "Chain ten detonations with minimal gaps" },
        },
        tips = "Recent mount/flight-method reports conflict between patches. The route uses the ground/air control method; no Engineering item, specific mount or flight exploit is required.",
        sources = {
            "https://www.wowhead.com/achievement=1428#comments:id=532255",
            "https://www.wowhead.com/achievement=1428#comments:id=6058426",
            "https://www.wowhead.com/achievement=1428#comments:id=6314030",
            "https://www.wowhead.com/achievement=1428#comments:id=6440358",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1428",
        sourceURL = "https://www.wowhead.com/achievement=1428#comments",
        difficultyReason = "Chain ten mine launches without landing; positioning and movement can require repeated attempts.",
        difficulty = "medium",
    },
    [1457] = {
        achievementId = 1457,
        name = "Explore Crystalsong Forest",
        sourceType = "Achievement",
        source = "Explore Crystalsong Forest",
        category = "Exploration",
        acquisition = "Difficulty: Easy - Fly through each named subzone and confirm its discovery; combat and random drops are unnecessary.\n\n1. Track Explore Crystalsong Forest and travel to the named locations below. Flying makes the circuit easier. Move into each discovery area until its criterion ticks; a revealed map image or nearby place label alone does not prove credit.\n\n2. Visit Violet Stand (15.7, 42.4). Check that this named criterion credits before continuing.\n\n3. Visit The Azure Front (23.5, 57.6). Check that this named criterion credits before continuing.\n\n4. Visit Forlorn Woods (47.1, 44.6). Check that this named criterion credits before continuing.\n\n5. Visit The Unbound Thicket (60.8, 61.8). Check that this named criterion credits before continuing.\n\n6. Visit Windrunner's Overlook (74.7, 80.4). This is an Alliance outpost; an opposing-faction flyer can discover it from above.\n\n7. Visit Sunreaver's Command (76.9, 48.3). This is the Horde outpost north of Windrunner's Overlook. Move toward its flags if the tick is still missing.\n\n8. Visit The Decrepit Flow (18.2, 15.6). Check that this named criterion credits before continuing.\n\n9. Visit The Great Tree (15.38, 29.95). Use the corrected tree approach north of Violet Stand.\n\n10. Review every criterion in the achievement. Revisit an unticked location and move around its immediate area if the first approach did not trigger discovery. Explore the FOREST below Dalaran, not the floating city's streets. Check the achievement rather than relying only on fog on the zone map.",
        stepCount = 10,
        waypoints = {
            { mapID = 127, x = 0.157, y = 0.424, step = 2, label = "Violet Stand" },
            { mapID = 127, x = 0.235, y = 0.5760000000000001, step = 3, label = "The Azure Front" },
            { mapID = 127, x = 0.47100000000000003, y = 0.446, step = 4, label = "Forlorn Woods" },
            { mapID = 127, x = 0.608, y = 0.618, step = 5, label = "The Unbound Thicket" },
            { mapID = 127, x = 0.747, y = 0.804, step = 6, label = "Windrunner's Overlook" },
            { mapID = 127, x = 0.769, y = 0.483, step = 7, label = "Sunreaver's Command" },
            { mapID = 127, x = 0.182, y = 0.156, step = 8, label = "The Decrepit Flow" },
            { mapID = 127, x = 0.15380000000000002, y = 0.2995, step = 9, label = "The Great Tree" },
        },
        tips = "Explore the FOREST below Dalaran, not the floating city's streets. Check the achievement rather than relying only on fog on the zone map.",
        sources = {
            "https://www.wowhead.com/achievement=1457#comments:id=478317",
            "https://www.wowhead.com/achievement=1457#comments:id=1396860",
            "https://www.wowhead.com/achievement=1457#comments:id=5204781",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1457",
        sourceURL = "https://www.wowhead.com/achievement=1457#comments",
        difficultyReason = "Fly through each named subzone and confirm its discovery; combat and random drops are unnecessary.",
        difficulty = "easy",
    },
    [1517] = {
        achievementId = 1517,
        name = "Northrend Angler",
        category = "Professions",
        sourceType = "Achievement",
        source = "Northrend Angler",
        acquisition = "Difficulty: Medium - Find and successfully fish each of the ten named Northrend schools across the continent.\n\n1. Learn Fishing and enable Find Fish if you have it. You need a successful catch from each of TEN different named schools. Cast INTO a visible pool; open-water fishing beside it does not satisfy that school.\n\n2. In Borean Tundra, fish Borean Man O' War schools along the eastern coast (84.5, 48.3) and Musselback Sculpin schools around the inland water (73.0, 45.8). Check both names on the pool tooltip.\n\n3. Fly to the icebergs offshore southeast of Unu'pe/Death's Stand (about 89.1, 53.7, still on the Borean map). Fish both Deep Sea Monsterbelly and Moonglow Cuttlefish schools. Search around the ice, fishing other schools out if the missing type is absent; do not continue into fatigue water.\n\n4. In Dragonblight, fish Dragonfin Angelfish at Lake Indu'le (39.5, 65.6). Continue to Grizzly Hills and fish a Glacial Salmon school along the southwestern river (23.9, 79.6).\n\n5. In Howling Fjord, find Imperial Manta Ray schools along the northwest coast (21.2, 15.3), then Fangtooth Herring schools in inland water near 33.5, 26.2. Manta schools also occur on other Northrend coasts.\n\n6. In Sholazar Basin, fish a Nettlefish school along the waterways, for example near 73.8, 64.2. In Crystalsong Forest, fish a Glassfin Minnow school near 32.9, 44.8. Check all ten criteria before leaving.",
        stepCount = 6,
        waypoints = {
            { mapID = 114, x = 0.845, y = 0.483, step = 2, label = "Borean Man O' War school search" },
            { mapID = 114, x = 0.73, y = 0.45799999999999996, step = 2, label = "Musselback Sculpin school search" },
            {
                mapID = 114,
                x = 0.8909999999999999,
                y = 0.537,
                step = 3,
                label = "Offshore icebergs - Monsterbelly AND Cuttlefish schools",
            },
            { mapID = 115, x = 0.395, y = 0.6559999999999999, step = 4, label = "Lake Indu'le - Dragonfin Angelfish" },
            { mapID = 116, x = 0.239, y = 0.7959999999999999, step = 4, label = "Southwestern river - Glacial Salmon" },
            { mapID = 117, x = 0.212, y = 0.153, step = 5, label = "Northwest coast - Imperial Manta Ray" },
            { mapID = 117, x = 0.335, y = 0.262, step = 5, label = "Inland water - Fangtooth Herring" },
            { mapID = 119, x = 0.738, y = 0.642, step = 6, label = "Waterways - Nettlefish" },
            {
                mapID = 127,
                x = 0.32899999999999996,
                y = 0.44799999999999995,
                step = 6,
                label = "Glassfin Minnow school search",
            },
        },
        tips = "Pins mark pool search areas, not permanent spawns. Loot a successful non-junk catch from the pool and verify its tick. Original 480 Fishing requirements and coordinates on the zoomed-out continent map are omitted.",
        sources = {
            "https://www.wowhead.com/achievement=1517#comments:id=454536",
            "https://www.wowhead.com/achievement=1517#comments:id=681625",
            "https://www.wowhead.com/achievement=1517#comments:id=1610340",
            "https://www.wowhead.com/achievement=1517#comments:id=5744312",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1517",
        sourceURL = "https://www.wowhead.com/achievement=1517#comments",
        difficultyReason = "Find and successfully fish each of the ten named Northrend schools across the continent.",
        difficulty = "medium",
    },
    [1596] = {
        achievementId = 1596,
        name = "Guru of Drakuru",
        category = "Quests",
        sourceType = "Achievement",
        source = "Guru of Drakuru",
        acquisition = "Difficulty: Medium - Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.\n\n1. In Grizzly Hills visit Drakuru in the cage at Granite Springs (16.2, 47.5) and start Truce?. Continue Vial of Visions, Subject to Interpretation, Sacrifices Must Be Made, Heart of the Ancients, My Old Enemy and Voices From the Dust. Keep the vial/summoning items and use them at the quest's named braziers.\n\n2. Accept Cleansing Drak'Tharon, enter Drak'Tharon Keep and clear to the last boss, The Prophet Tharon'ja. Use the Elixir of Visions at Drakuru's brazier in the final area, finish his scene and turn in the quest. Merely killing Tharon'ja does not finish this half.\n\n3. For the Zul'Drak half, visit Ebon Watch (14, 73). Complete Stefan Vadu's introduction, obtain the Unliving Choker quest-starting drop and follow An Invitation of Sorts into the Scourge disguise/Voltarus chain.\n\n4. Alternate Drakuru's orders in Voltarus with Stefan's sabotage quests. Use Stefan's horn where required and keep the quest disguise/item. Continue through the scouting, Blight and Servant of Drakuru tasks until Betrayal is offered.\n\n5. Complete Betrayal's encounter and turn-in, including its quest interactions and Drakuru's skull. Check BOTH Cleansing Drak'Tharon and Betrayal criteria. If the former completed without credit, leave the dungeon and log out/back in; recent Retail comments still report delayed credit after relogging.",
        stepCount = 5,
        waypoints = {
            { mapID = 116, x = 0.162, y = 0.475, step = 1, label = "Granite Springs - Truce? and Drakuru's vial" },
            {
                mapID = 121,
                x = 0.28600000000000003,
                y = 0.8690000000000001,
                step = 2,
                label = "Drak'Tharon Keep - Cleansing Drak'Tharon",
            },
            { mapID = 121, x = 0.14, y = 0.73, step = 3, label = "Ebon Watch - Stefan / Unliving Choker" },
            { mapID = 121, x = 0.28, y = 0.45, step = 4, label = "Voltarus - Drakuru and sabotage chain" },
            { mapID = 121, x = 0.28, y = 0.45, step = 5, label = "Voltarus - Betrayal conclusion" },
        },
        tips = "The two halves can be completed in either order. Do not discard a summons item just because there is no visible fixed-NPC quest marker.",
        sources = {
            "https://www.wowhead.com/achievement=1596#comments:id=450885",
            "https://www.wowhead.com/achievement=1596#comments:id=1407617",
            "https://www.wowhead.com/achievement=1596#comments:id=1753093",
            "https://www.wowhead.com/achievement=1596#comments:id=5786605",
            "https://www.wowhead.com/achievement=1596#comments:id=6182017",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1596",
        sourceURL = "https://www.wowhead.com/achievement=1596#comments",
        difficultyReason = "Complete the substantial zone quest checklist, including its prerequisite branches and scripted events.",
        difficulty = "medium",
    },
    [1658] = {
        achievementId = 1658,
        name = "Champion of the Frozen Wastes",
        category = "Raids",
        sourceType = "Achievement",
        source = "Champion of the Frozen Wastes",
        acquisition = "Difficulty: Medium - Clear all twelve launch dungeons; the Heroic and title variants add their stated mode or raid requirements.\n\n1. Track this title achievement's boss checklist. Set Dungeon Difficulty to HEROIC and clear the original twelve Northrend launch dungeons; their required final bosses include Mal'Ganis, not the optional Infinite Corruptor.\n\n2. Use the Northrend Dungeon Hero guide for the entrances and scripted dungeon events. If any final-boss criterion remains missing, revisit that specific Heroic; a Normal clear does not replace the title's Heroic requirement.\n\n3. Defeat Kel'Thuzad in Northrend Naxxramas, Sartharion in Obsidian Sanctum and Malygos in Eye of Eternity. Either original raid size is suitable for this title. The three raids are separate instances with different entrances.\n\n4. Check every listed boss, then select Champion of the Frozen Wastes from your title list. No removed realm-first, original-season or level-80-only restriction applies to this surviving title.",
        stepCount = 4,
        waypoints = {
            { mapID = 117, x = 0.5820000000000001, y = 0.489, step = 1, label = "Utgarde Keep - begin Heroic dungeon circuit" },
            { mapID = 125, x = 0.665, y = 0.6779999999999999, step = 2, label = "Violet Hold - original Northrend Dalaran" },
            { mapID = 75, x = 0.569, y = 0.8240000000000001, step = 2, label = "Culling of Stratholme - Heroic Mal'Ganis" },
            { mapID = 115, x = 0.8740000000000001, y = 0.51, step = 3, label = "Naxxramas - Kel'Thuzad" },
            { mapID = 115, x = 0.598, y = 0.546, step = 3, label = "Obsidian Sanctum - Sartharion" },
            { mapID = 114, x = 0.275, y = 0.266, step = 3, label = "Eye of Eternity - Malygos" },
        },
        tips = "The individual dungeon guides include all boss requirements and event dialogue. Getting the Bronze Drake alone does not establish Mal'Ganis credit.",
        sources = {
            "https://www.wowhead.com/achievement=1658#comments:id=749911",
            "https://www.wowhead.com/achievement=1658#comments:id=1301767",
