        wowheadUrl = "https://www.wowhead.com/achievement=1658",
        sourceURL = "https://www.wowhead.com/achievement=1658#comments",
        difficultyReason = "Clear all twelve launch dungeons; the Heroic and title variants add their stated mode or raid requirements.",
        difficulty = "medium",
    },
    [1717] = {
        achievementId = 1717,
        name = "Wintergrasp Victory",
        category = "PvP",
        sourceType = "Achievement",
        source = "Wintergrasp Victory",
        acquisition = "Difficulty: Medium - Win one Wintergrasp or Isle of Conquest match against the opposing team.\n\n1. For populated PvP, queue for Wintergrasp through the PvP Epic Battleground interface (or its specific battleground selection when available). This loads an INSTANCE. Outdoor Wintergrasp in Northrend is a separate copy that still has its own battle/control state; use the map dropdown to distinguish them.\n\n2. Participate from the start when possible. Help kill eligible enemy players/NPCs to gain battle rank, capture/defend workshops and protect your team's vehicles. Watch the rank buff rather than an old fixed kill count before trying to build an advanced vehicle.\n\n3. On ATTACK, capture a workshop, use its builder for siege vehicles, breach a route through the fortress walls and final door, then interact with the Titan Relic to win. Protect the vehicles from defenders; attacking ordinary players alone cannot open the fortress.\n\n4. On DEFENSE, destroy attacking vehicles and protect the relic until time expires. A team can also destroy the three southern towers to reduce the attackers' available time. Stay until the match result records the victory.\n\n5. Check Wintergrasp Victory after your team's successful match. One win is sufficient; the separate Veteran tier needs 100. Walking into the outdoor zone while a different instanced match ends is not a dependable credit method.",
        stepCount = 5,
        waypoints = {
