    [1721] = {
        achievementId = 1721,
        name = "Archavon the Stone Watcher (25 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Archavon the Stone Watcher (25 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Set Legacy Raid Size to 25 players outside, fly to Wintergrasp Fortress and enter the Vault of Archavon portal at 50.0, 11.0. This is the outdoor Northrend zone, not the queued Epic Battleground. If access is closed, use the faction-control state shown in that zone.\n\n2. Follow the main passage north to Archavon's large final chamber. Kill Archavon; his grabs and ground clouds are unnecessary to wait for at high level.\n\n3. Check the named Watcher's achievement for this size before leaving. A 25-player kill does not substitute for the separate 10-player criterion.",
