    [1727] = {
        achievementId = 1727,
        name = "Leaning Tower",
        category = "PvP",
        sourceType = "Achievement",
        source = "Leaning Tower",
        acquisition = "Difficulty: Medium - Build a siege vehicle and fully destroy a hostile Wintergrasp tower during an active battle.\n\n1. Enter an active Wintergrasp battle. A clear target on DEFENSE is one of the three southern towers: Shadowsight, Winter's Edge or Flamewatch. The instanced Epic Battleground has players to help; outdoor battles offer an alternate route.\n\n2. Earn enough rank from enemy NPC/player kills to build a Demolisher or Siege Engine. The central bridge NPC groups around 48.3, 43.8 and 49.1, 50.9 are a reported outdoor rank-building route. Check your rank buff rather than expecting each individual kill to advance it.\n\n3. Capture a workshop, wait for its friendly builder to appear, then create your vehicle. If one outdoor workshop's builder fails to spawn, check another controlled workshop instead of waiting indefinitely at the flag.\n\n4. Drive to a hostile southern tower and use the vehicle's siege attacks until it actually COLLAPSES. A 'tower damaged' alert is not completion. Stay involved through the destruction and check the achievement.",
