    [1751] = {
        achievementId = 1751,
        name = "Didn't Stand a Chance",
        category = "PvP",
        sourceType = "Achievement",
        source = "Didn't Stand a Chance",
        acquisition = "Difficulty: Hard - Earn twenty kills on still-mounted enemy players from a Wintergrasp cannon; suitable targets are uncommon.\n\n1. Join a Wintergrasp DEFENSE and get into a friendly TOWER CANNON. The required victims are players still on their own mounts when they die. Enemy siege engines, passengers and dismounted players are not interchangeable with that condition.\n\n2. Prefer the inner fortress cannons overlooking the gate/courtyard approaches, which generally survive longer than exposed outer cannons. Aim at mounted enemies moving with the attack and keep contributing cannon fire while nearby teammates fight.\n\n3. Check the mounted-player counter after engagements. Replies report that nearby honorable kills can credit while you are in the cannon, but the player must die mounted. Accumulate twenty credited kills; this does not have to happen in a single defense.\n\n4. If arranging an outdoor attempt with an opposite-faction friend, use the ACTUAL outdoor battle while your side controls the fortress, get into its cannon and have the friend remain mounted at impact. Re-mount on the ground if the zone's flight warning dismounts them. Repeat only while the battle/credit conditions are active and verify the counter after the first kill.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 1334,
                x = 0.493,
