    [1752] = {
        achievementId = 1752,
        name = "Master of Wintergrasp",
        category = "PvP",
        sourceType = "Achievement",
        source = "Master of Wintergrasp",
        acquisition = "Difficulty: Hard - Complete every Wintergrasp meta criterion, including long win, vehicle and area-kill counters.\n\n1. Track the live meta and complete Wintergrasp Veteran (100 wins), Wintergrasp Ranger, Vehicular Gnomeslaughter, Didn't Stand a Chance, Destruction Derby, Leaning Tower and Within Our Grasp using their separate numbered guides.\n\n2. Buy and learn the ordinary Black War Mammoth from the friendly OUTDOOR fortress quartermaster for fifteen Marks of Honor. Grand Black War Mammoth is a rare raid drop and is NOT required by this meta.\n\n3. While your faction controls outdoor Wintergrasp, enter Vault of Archavon at the back of the fortress (50, 11.9). Defeat Archavon in BOTH legacy raid sizes, 10 and 25. The meta may still call the second tick 'Heroic: Archavon'; this means the original 25-player version, not an extra modern Heroic difficulty.\n\n4. Check every component and the faction-appropriate Destruction Derby tick. Raid access and the mammoth vendor use outdoor control; an Epic Battleground victory does not necessarily change control in your separate outdoor copy.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 1334,
                x = 0.493,
                y = 0.21100000000000002,
                step = 1,
                label = "Instanced Wintergrasp - battle achievements",
