        wowheadUrl = "https://www.wowhead.com/achievement=1752",
        sourceURL = "https://www.wowhead.com/achievement=1752#comments",
        difficultyReason = "Complete every Wintergrasp meta criterion, including long win, vehicle and area-kill counters.",
        difficulty = "hard",
    },
    [1755] = {
        achievementId = 1755,
        name = "Within Our Grasp",
        category = "PvP",
        sourceType = "Achievement",
        source = "Within Our Grasp",
        acquisition = "Difficulty: Hard - Coordinate an attacking Wintergrasp victory within ten minutes, including rank, siege and relic progress.\n\n1. Queue for Wintergrasp and make the attempt when your team is ATTACKING. The current requirement is a successful attack in TEN MINUTES or less. Defending until the timer ends is not the intended route.\n\n2. Work with the initial team push: earn vehicle rank quickly while teammates secure a workshop. Build advanced siege vehicles as soon as available and escort them to a shared fortress-wall target rather than splitting damage among several gates.\n\n3. Breach the outer wall, then progress to the final fortress door. A Demolisher can sometimes arc its shot over an inner wall toward the final door when positioned with line of sight; use the visible damage feedback and move if shots do not land. Keep enemy players from destroying your siege.\n\n4. After the final door falls, enter and claim the Titan Relic BEFORE ten minutes have elapsed from the battle start. Check achievement credit at victory. Contemporary comments recommend the populated instanced battleground over a slow solo outdoor rank grind.",
        stepCount = 4,
        waypoints = {
