    [1777] = {
        achievementId = 1777,
        name = "The Northrend Gourmet",
        category = "Professions",
        sourceType = "Achievement",
        source = "The Northrend Gourmet",
        acquisition = "Difficulty: Medium - Learn and personally cook the required number of different Northrend recipes; repeated batches do not add distinct ticks.\n\n1. Learn Northrend Cooking, track this achievement, and plan to personally cook 15 DIFFERENT listed recipes. Buying or eating a finished dish does not grant this crafting criterion, and repeated batches of one dish only fill one tick.\n\n2. Learn the trainer dishes in Northrend Dalaran: Baked Manta Ray, Dalaran Clam Chowder, Grilled Bonescale, Grilled Sculpin, Mammoth Meal, Pickled Fangtooth, Poached Nettlefish, Rhino Dogs, Roasted Worg, Sauteed Goby, Shoveltusk Steak, Smoked Rockfin, Smoked Salmon, Worm Delight and Great Feast. Obtain Northern Stew through the faction's Northern Cooking quest at its Borean Tundra starting hub if missing.\n\n3. Do Dalaran cooking dailies for Epicurean's Awards, then buy the missing recipes from Derek Odds (Alliance) or Misensi (Horde). Purchase Northern Spices as needed. Cook one of each uncredited recipe instead of spending all awards on redundant recipes or the Chef's Hat first.\n\n4. For the four unusual dishes, obtain the dropped/tradeable recipes for Bad Clams, Haunted Herring, Last Week's Mammoth and Tasty Cupcake. Check the Auction House before farming Northrend humanoids. Learn each recipe and cook the dish; these are not all taught by the trainer.\n\n5. For Kungaloosh, complete Grimbooze Thunderbrew's drinking quests at Nesingwary Base Camp in Sholazar Basin through The Taste Test. Find the Washed-Up Mage behind a sewer grate at Underbelly 43.2, 24.4, complete Fletcher's Lost and Found to learn Kungaloosh, then obtain its fruit ingredients and make it.\n\n6. Work down the live checklist, including feast recipes when needed. Fish Feast is a further cooking-award recipe unlock; check the vendor's current requirement if it is locked. Stop at 15 unique cooked entries for this tier; the 45-recipe tier needs every listed dish, including Kungaloosh and all four dropped recipes.",
        stepCount = 6,
        waypoints = {
            {
                mapID = 125,
                x = 0.40299999999999997,
                y = 0.6609999999999999,
                step = 2,
                label = "Katherine Lee - Alliance trainer dishes",
            },
            { mapID = 125, x = 0.7, y = 0.389, step = 2, label = "Awilo Lon'gomba - Horde trainer dishes" },
            {
                mapID = 114,
                x = 0.5820000000000001,
                y = 0.621,
                step = 2,
                label = "Valiance Keep - Alliance Northern Cooking quest",
            },
            { mapID = 114, x = 0.42, y = 0.541, step = 2, label = "Warsong Hold - Horde Northern Cooking quest" },
            {
                mapID = 125,
                x = 0.406,
                y = 0.6579999999999999,
                step = 3,
                label = "Derek Odds - award recipes / Northern Spices",
            },
            { mapID = 125, x = 0.7020000000000001, y = 0.39, step = 3, label = "Misensi - award recipes / Northern Spices" },
            { mapID = 119, x = 0.27, y = 0.585, step = 5, label = "Nesingwary Base Camp - Grimbooze's Taste Test" },
            {
                mapID = 126,
                x = 0.43200000000000005,
                y = 0.244,
                step = 5,
                label = "Washed-Up Mage - behind grate; Kungaloosh after The Taste Test",
            },
        },
        tips = "Keep useful previously collected recipes. Use the current 45-dish achievement checklist to decide what is missing; the original total Cooking skill numbers are obsolete.",
