        difficulty = "hard",
    },
    [1780] = {
        achievementId = 1780,
        name = "Second That Emotion",
        category = "Professions",
        sourceType = "Achievement",
        source = "Second That Emotion",
        acquisition = "Difficulty: Easy - Buy or cook the required food and perform the short eating or critter-feeding checklist.\n\n1. Obtain one each of Bad Clams, Last Week's Mammoth, Haunted Herring and Tasty Cupcake. Buying the FINISHED foods from the Auction House or another cook is sufficient; you do not have to craft them yourself.\n\n2. Eat Bad Clams and let its associated emotion effect register, then do the same with Last Week's Mammoth. Stay seated long enough to receive each food's effect rather than cancelling immediately.\n\n3. Eat Haunted Herring, then Tasty Cupcake, checking the four achievement criteria. You need all four foods, not any four servings of the same food.\n\n4. If cooking them yourself, learn their four dropped Northrend recipes first. They are separate from the normal trainer dishes. Keep the crafting ticks for The Northrend Gourmet and the eating ticks for this achievement distinct.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 125,
                x = 0.40299999999999997,
                y = 0.6609999999999999,
                step = 4,
                label = "Alliance cooking area - prepare the four foods",
            },
            { mapID = 125, x = 0.7, y = 0.389, step = 4, label = "Horde cooking area - prepare the four foods" },
        },
        sources = { "https://www.wowhead.com/achievement=1780#comments:id=5169406" },
        wowheadUrl = "https://www.wowhead.com/achievement=1780",
        sourceURL = "https://www.wowhead.com/achievement=1780#comments",
        difficultyReason = "Buy or cook the required food and perform the short eating or critter-feeding checklist.",
        difficulty = "easy",
    },
    [1781] = {
        achievementId = 1781,
        name = "Critter Gitter",
        category = "Professions",
        sourceType = "Achievement",
        source = "Critter Gitter",
        acquisition = "Difficulty: Easy - Buy or cook the required food and perform the short eating or critter-feeding checklist.\n\n1. Buy or cook at least ten Critter Bites and place them on an action button. Find a dense group of living critters before using any; the achievement needs ten following you within three minutes.\n\n2. A useful Northrend spot is the Fjord Turkey field just west of Explorers' League Outpost in Howling Fjord, around 69.2, 64.6. Do this before killing the turkeys for Friend or Fowl?.\n\n3. Target one living turkey, use a Critter Bite, then target a DIFFERENT nearby turkey and repeat. Keep the followers alive and close; do not use damaging area attacks or repeatedly feed the same critter.\n\n4. Continue until ten are following simultaneously before the first follower expires. If the field was cleared by another player, wait for respawns or find another dense critter group before starting the timer again.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 117,
                x = 0.6920000000000001,
                y = 0.6459999999999999,
                step = 2,
                label = "Fjord Turkey field - ten living critter followers",
            },
            {
                mapID = 117,
                x = 0.6920000000000001,
                y = 0.6459999999999999,
                step = 3,
                label = "Feed a different turkey for each Critter Bite",
            },
        },
        sources = {
            "https://www.wowhead.com/achievement=1781#comments:id=6202649",
            "https://www.wowhead.com/achievement=1781#comments:id=6463200",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1781",
        sourceURL = "https://www.wowhead.com/achievement=1781#comments",
        difficultyReason = "Buy or cook the required food and perform the short eating or critter-feeding checklist.",
        difficulty = "easy",
    },
    [1782] = {
        achievementId = 1782,
        name = "Our Daily Bread",
        category = "Professions",
        sourceType = "Achievement",
        source = "Our Daily Bread",
        acquisition = "Difficulty: Medium - Complete each randomly offered Dalaran cooking or fishing daily over multiple resets.\n\n1. Learn Northrend Cooking and take today's daily from Katherine Lee in the kitchen at A Hero's Welcome (40.3, 66.1) in Northrend Dalaran. One random daily is offered per day; repeat after resets until all five named quests credit.\n\n2. Convention at the Legerdemain: cook four Northern Stew (Chilled Meat), pick up a Jug of Wine at the cheese shop One More Glass, and deliver both to Arille Azuregaze in the Legerdemain Lounge. This branch turns in there, not at your cooking trainer.\n\n3. Cheese for Glowergold: collect Aged Dalaran Limburger at One More Glass and six Half Full Dalaran Wine Glasses from inn/tavern tables. Use the supplied Empty Cheese Platter to combine them, then deliver it to Ranid Glowergold in the leatherworking shop.\n\n4. Infused Mushroom Meatloaf: collect four Infused Mushrooms in the Northrend Underbelly. Combine them with two Chilled Meat using the supplied Meatloaf Pan, then deliver the result to Orton Bennet in Curiosities & Moore.\n\n5. Mustard Dogs!: cook four Rhino Dogs from Rhino Meat and collect four Wild Mustard plants in Dalaran's grassy areas. Use the supplied basket, then deliver it to Archmage Pentarus at Krasus' Landing.\n\n6. Sewer Stew: descend to Crystalsong Forest and collect four Crystalsong Carrots. Combine them with four Chilled Meat using the quest Cookpot, then deliver the stew to Ajay Green in the Cantrips & Crows sewer inn.\n\n7. Use only the branch matching today's quest. Keep Chilled Meat and Rhino Meat for future resets, and learn Northern Stew if missing. Repeated daily selections are normal; abandoning a duplicate does not reroll the rotation.",
        stepCount = 7,
        waypoints = {
            { mapID = 125, x = 0.40299999999999997, y = 0.6609999999999999, step = 1, label = "Katherine Lee - accept daily" },
            { mapID = 125, x = 0.535, y = 0.348, step = 2, label = "One More Glass - cheese / Jug of Wine" },
            { mapID = 125, x = 0.485, y = 0.381, step = 2, label = "Legerdemain Lounge - Arille" },
            { mapID = 125, x = 0.364, y = 0.28600000000000003, step = 3, label = "Ranid Glowergold - leatherworking shop" },
            { mapID = 126, x = 0.44, y = 0.65, step = 4, label = "Underbelly - search for Infused Mushrooms" },
            { mapID = 125, x = 0.52, y = 0.552, step = 4, label = "Curiosities & Moore - Orton Bennet" },
            { mapID = 125, x = 0.6859999999999999, y = 0.42, step = 5, label = "Krasus' Landing - Archmage Pentarus" },
            { mapID = 127, x = 0.27, y = 0.43, step = 6, label = "Crystalsong Forest - carrot search area below Dalaran" },
            { mapID = 126, x = 0.354, y = 0.574, step = 6, label = "Cantrips & Crows - Ajay Green" },
        },
        tips = "All quest destinations are in the original Northrend city and its surroundings. The modern requirement is learned Northrend Cooking, not the old 350/375 combined Cooking skill.",
        sources = {
            "https://www.wowhead.com/achievement=1782#comments:id=1172616",
            "https://www.wowhead.com/achievement=1782#comments:id=1172617",
