    [1785] = {
        achievementId = 1785,
        name = "Dinner Impossible",
        category = "Professions",
        sourceType = "Achievement",
        source = "Dinner Impossible",
        acquisition = "Difficulty: Medium - Place the correct Great Feast in all four required battlegrounds; queuing and travel take several matches.\n\n1. Obtain at least four Great Feast (item 34753), either cooked or bought. Fish Feast, Small Feast and Gigantic Feast are different items and do not satisfy this achievement.\n\n2. Queue for Alterac Valley through Epic Battlegrounds. Once in the match, place a Great Feast on the ground where placement is allowed and check that Alterac Valley credits.\n\n3. Queue for Warsong Gulch and Arathi Basin through the PvP battleground interface. In each actual match, place another Great Feast and check its separate tick. No victory or personal eating step is required.\n\n4. Do the same in Eye of the Storm. If preparation-area placement does not credit, place it after the match starts. Review all FOUR current criteria; the removed Strand of the Ancients is no longer needed.",
        stepCount = 4,
        waypoints = {},
        tips = "These destinations are instanced battlegrounds reached through the PvP queue, not outdoor travel pins. Cooking skill is unnecessary when using purchased Great Feasts.",
        sources = {
            "https://www.wowhead.com/achievement=1785#comments:id=1258874",
            "https://www.wowhead.com/achievement=1785#comments:id=1686673",
            "https://www.wowhead.com/achievement=1785#comments:id=2835472",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1785",
        sourceURL = "https://www.wowhead.com/achievement=1785#comments",
        areaMaps = { 91, 1339, 1366, 112 },
        difficultyReason = "Place the correct Great Feast in all four required battlegrounds; queuing and travel take several matches.",
        difficulty = "medium",
    },
    [1816] = {
        achievementId = 1816,
        name = "Defenseless",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Defenseless",
        acquisition = "Difficulty: Easy - Preserve the Violet Hold seal at full health and finish all waves without using a defense crystal.\n\n1. Enter the ORIGINAL Violet Hold in Northrend Dalaran on Heroic. Tell Sinclari you are ready. Leave all Defense Control Crystals on the prison walls untouched for the ENTIRE run.\n\n2. Intercept each portal's attackers before they damage the prison seal. Watch the seal-integrity display and keep it at 100%. For split groups, kill or tag every enemy rather than assuming the portal's main guardian is the only threat.\n\n3. Defeat the prisoners at waves 6 and 12, then Cyanigosa at wave 18, with the seal still at 100% and no crystal used. If Ichoron appears, do not use a crystal for his globules during this attempt; handle them yourself or do Dehydration separately.",
        stepCount = 3,
        waypoints = {
