    [1817] = {
        achievementId = 1817,
        name = "The Culling of Time",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "The Culling of Time",
        acquisition = "Difficulty: Easy - Follow Arthas promptly and kill the Infinite Corruptor before the generous Heroic timer expires.\n\n1. Set Heroic and enter the Culling of Stratholme through the Caverns of Time in Tanaris. Complete Chromie's crate introduction or use the available skip dialogue, then speak to Arthas to begin the timed street event.\n\n2. Clear the ten marked street waves, including Meathook and Salramm. Keep following the minimap's next wave marker. Speak to Arthas when he arrives at the town hall; clear its Infinite enemies and defeat Chrono-Lord Epoch.\n\n3. Speak to Arthas again and follow him through the passage and burning-street gauntlet. Kill enemies that stop the escort. The Infinite Corruptor must DIE before the 25-minute countdown expires; merely pulling him just before expiry is insufficient.\n\n4. At the final clean street before Mal'Ganis's square, take the LEFT side alley toward Market Row. Kill the Infinite Corruptor beside the captive bronze drake, then check the achievement. Do this before starting Mal'Ganis to avoid wasting the remaining timer.",
