        name = "Lightning Struck",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Lightning Struck",
        acquisition = "Difficulty: Easy - Wait for Bjarngrim's electrical charge before engaging, then defeat him while charged.\n\n1. Set Heroic and enter Halls of Lightning. Stop before General Bjarngrim's patrol and clear nearby trash without hitting him.\n\n2. Target Bjarngrim and wait until his patrol stops on a charging platform. Watch his buffs: engage only AFTER Temporary Electrical Charge is actually present, not while he is merely walking toward the platform.\n\n3. Kill the charged Bjarngrim. At high level, a direct fast kill is sufficient. If credit has previously failed, let him enter combat and land a hit while charged before finishing; do not assume standing near a platform applied the buff.",
