    [1858] = {
        achievementId = 1858,
        name = "Arachnophobia (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Arachnophobia (10 player)",
        acquisition = "Difficulty: Easy - A high-level fast kill or solo small-group clear satisfies the surviving Naxxramas encounter condition.\n\n1. Outside Naxxramas, set Legacy Raid Size to 10 players. Fly to the floating necropolis over eastern Dragonblight and enter the portal underneath it (87.4, 51.0). This is the Northrend raid, not the removed Eastern Plaguelands version.\n\n2. Take the Arachnid Quarter. Clear Anub'Rekhan's room and be ready to continue before killing him: his death starts the TWENTY-minute timer.\n\n3. Move straight through the wing, kill Grand Widow Faerlina, clear the web corridor and defeat Maexxna before that same timer expires. Loot and optional detours can wait until after Maexxna.",
        stepCount = 3,
        waypoints = {
            {
                mapID = 115,
                x = 0.8740000000000001,
