    [1860] = {
        achievementId = 1860,
        name = "Gotta Go!",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Gotta Go!",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Enter Azjol-Nerub on HEROIC, defeat Krik'thir and Hadronox, then drop into the final Brood Pit. This is dungeon Anub'arak, not the Trial of the Crusader raid boss.\n\n2. Engage Anub'arak and attack immediately. The current limit is FOUR minutes from the pull. Ignore old two-minute strategies involving stolen buffs, stacked casting slows or specially selected level-80 groups.\n\n3. If he stops at 1 health and burrows, stay in the arena and immediately kill each wave of summoned enemies. Later Retail reports describe this health floor: more damage cannot finish an untargetable submerged boss. Avoid the spikes while waiting for the next wave.\n\n4. Attack as soon as he resurfaces, clear another add wave if required, and finish him before the countdown expires. The timer covers the whole encounter, including the underground phases; it does not restart when he reappears.",
        stepCount = 4,
        waypoints = {
            { mapID = 115, x = 0.26, y = 0.508, step = 1, label = "Azjol-Nerub - entrance" },
