    [1862] = {
        achievementId = 1862,
        name = "Volazj's Quick Demise",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Volazj's Quick Demise",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Heroic and enter Ahn'kahet in Dragonblight. Follow the dungeon route to Herald Volazj's final chamber and clear nearby trash before starting the timer.\n\n2. Engage Volazj and kill him within TWO minutes. At high level, begin with a low-damage tag, allow combat to register, then finish him; several later comments report missing boss credit after an instantaneous first-hit kill.\n\n3. If Insanity begins, kill the hostile party copies in your phase, prioritizing a healing copy if present. When the normal room returns, resume damage immediately. A solo character may have no other party copies to fight. Do not follow the old Divine Intervention or repeated zoning-out strategy; it is unnecessary and relies on obsolete abilities or behavior.",
        stepCount = 3,
