    [1864] = {
        achievementId = 1864,
        name = "What the Eck?",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "What the Eck?",
        acquisition = "Difficulty: Medium - Wait for Eck Residue to apply, preserve the debuff and then defeat Gal'darah.\n\n1. Set Heroic and enter Gundrak. Defeat Slad'ran, the Colossus and Moorabi and click each boss's altar to open the bridge to Gal'darah. Leave Gal'darah alive. Behind Moorabi, take the side passage into Eck's cavern and kill the three inhabitants that trigger his arrival.\n\n2. Do NOT kill Eck yet. Control pets and damage procs, engage without dealing damage and stand in front of him so Eck Spit can hit you. At high level, turn your character's back toward him, try /sit, and remove gear if needed; it can take repeated casts, including after his enrage.\n\n3. Wait until your debuff bar actually shows ECK RESIDUE, lasting one hour. The cast animation or a resisted/missed spit is insufficient. Once the lasting debuff is present, kill Eck.\n\n4. Return through Moorabi's room and cross the opened central bridge. Defeat Gal'darah while YOU still have Eck Residue. Avoid dying or using immunity/debuff-clearing abilities such as Ice Block or Cloak of Shadows along the way.",
        stepCount = 4,
        waypoints = {
