    [1865] = {
        achievementId = 1865,
        name = "Lockdown!",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Lockdown!",
        acquisition = "Difficulty: Medium - Collect all six randomly selected Violet Hold prisoners across eligible rerolls or daily clears.\n\n1. Enter the ORIGINAL Violet Hold in Northrend Dalaran on Heroic, not Legion's Assault on Violet Hold. Open the achievement and note which of Xevozz, Lavanthor, Ichoron, Zuramat, Erekem and Moragg are still missing.\n\n2. Tell Sinclari to begin and clear through the sixth portal. Watch the saboteur run to a prison cell; only the selected prisoner becomes the real boss. You cannot choose a prisoner by attacking its cage.\n\n3. If the first selection is missing, kill that boss and continue to wave 12 for a second chance. Control pets so your character participates in the kill. Once saved by a boss kill, you cannot freely reroll that Heroic instance.\n\n4. If the first selection is already complete, leave BEFORE killing it, reset from outside and try again. A hearth, class teleport or leaving a temporary premade group can get you out. Reset the actual instance as well as the event; restarting Sinclari in the same instance can repeat the same prisoner.\n\n5. Repeat with eligible alts or later resets until all six checks are present. Later Retail comments confirm Warband progress combines characters, so the old minimum-three-days claim is obsolete. The random selection can still repeat; respect the hourly entry limit.",
