    [1866] = {
        achievementId = 1866,
        name = "Good Grief",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Good Grief",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Heroic and enter Halls of Stone. Take the side branch to the Maiden of Grief; groups running only Brann and Sjonnir can skip this boss, so visit her deliberately.\n\n2. Engage the Maiden and defeat her within ONE minute. At high level, direct burst damage is normally sufficient. If a very fast kill fails to start or finish the timer, retry after the Heroic reset with a low-damage tag, allow combat to register, then finish within the minute.\n\n3. If the fight lasts until Shock of Sorrow, be beside a fresh dark ground pool. Briefly step into it as the incapacitate lands so its damage breaks the effect, then step back out and keep attacking. Check achievement credit before leaving.",
