        achievementId = 1867,
        name = "Timely Death",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Timely Death",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Heroic and enter Halls of Lightning. Defeat Bjarngrim, Volkhan and Ionar, then clear the approach to Loken's final chamber.\n\n2. Prepare your damage cooldowns before pulling and defeat Loken within TWO minutes of engaging. At high level, kill him directly; no Lightning Nova cast is required for credit.\n\n3. If he survives, remain reasonably close between casts because Pulsing Shockwave hurts more at range. When Lightning Nova is cast, move beyond its immediate blast radius and return promptly, or use an appropriate defensive if you can safely survive it. Keep attacking whenever possible and check the timer.",
