    [1868] = {
        achievementId = 1868,
        name = "Make It Count",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Make It Count",
        acquisition = "Difficulty: Medium - Complete the Oculus vehicle route within twenty minutes, including every construct and platform stage.\n\n1. Set Heroic and enter the Oculus. Before killing Drakos, decide which essence to take and prepare the route; the TWENTY-minute timer starts at DRAKOS'S DEATH, not when you enter the dungeon.\n\n2. Kill Drakos, immediately take an essence from the freed drakes and mount. At high level a Ruby drake is a straightforward choice. Fly to the construct level without spending time on unnecessary wandering drakes.\n\n3. Kill all TEN Centrifuge Constructs, including the groups on both outer platforms and the inner horseshoe. Remount between separated platforms. When the shield is gone, land on Varos's platform, dismount and defeat him.\n\n4. Fly to Urom's platforms, clear each summoned pack and follow his teleports. Finish him on the inner ring, remount and reach Eregos on the highest ring promptly.\n\n5. Kill Eregos before the twenty-minute timer expires. Use your drake's attacks, kill threatening whelps and move away from the planar-shift orbs. The normal-to-Heroic trick for carrying an essence into a pre-cleared instance was removed long ago; start and finish a real Heroic run.",
        stepCount = 5,
        waypoints = {
            { mapID = 114, x = 0.28600000000000003, y = 0.275, step = 1, label = "The Oculus - upper portal" },
            {
                mapID = 143,
