    [1869] = {
        achievementId = 1869,
        name = "A Poke in the Eye (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "A Poke in the Eye (10 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Set Legacy Raid Size to 10 players outside the instance. Fly to Coldarra in Borean Tundra and enter the EYE OF ETERNITY on the highest ring of the Nexus tower. The Nexus and Oculus portals are different instances.\n\n2. Keep at most 8 players inside for the entire encounter. Soloing satisfies the limit. Start the encounter at the central focusing device.\n\n3. In phase 2, kill every Nexus Lord and Scion of Eternity. Ranged attacks can reach the flying enemies; otherwise kill a descending Nexus Lord and mount its dropped disc to fly to them. Stay inside the anti-magic bubbles if damage matters.\n\n4. When the platform breaks, wait for your red drake and its vehicle bar. Target Malygos and use Flame Spike (1), Flame Spike (1), Engulf in Flames (2); repeat, adding Revivify (3) to heal if needed and moving out of Static Fields. Finish the dragon and wait for credit.",
        stepCount = 4,
        waypoints = { { mapID = 114, x = 0.275, y = 0.266, step = 1, label = "Eye of Eternity - highest Nexus portal" } },
        tips = "No old Eye of Eternity key is needed. Do not leave the instance while the platform and drake transitions run.",
        sources = { "https://www.wowhead.com/achievement=1869#comments:id=1784746" },
        wowheadUrl = "https://www.wowhead.com/achievement=1869",
        sourceURL = "https://www.wowhead.com/achievement=1869#comments",
        difficultyReason = "Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.",
        difficulty = "easy",
    },
    [1870] = {
