    [1871] = {
        achievementId = 1871,
        name = "Experienced Drake Rider",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Experienced Drake Rider",
        acquisition = "Difficulty: Medium - Defeat Eregos using each of the three drake colors on separate eligible clears.\n\n1. Set Heroic and enter the Oculus through the upper Coldarra portal. Plan three Eregos victories, one while mounted on EACH of the Amber, Emerald and Ruby drakes. Track the three color criteria individually.\n\n2. Defeat Drakos and take the essence for a missing color from its freed drake. Ride it between platforms, disable the Centrifuge Constructs, defeat Varos and follow Urom's platform sequence until he is dead.\n\n3. Mount the selected drake and fly to Eregos. Remain mounted until he DIES: a personal ranged kill while dismounted does not satisfy the color criterion. At high level, use the drake's own abilities rather than the old pre-mount projectile trick.\n\n4. On Ruby, use Searing Wrath and kill whelps if needed. On Amber, use Shock Lance; when Eregos becomes immune, wait out the shift before resuming. On Emerald, maintain Leeching Poison on Eregos and apply it to whelps for healing. Do not dismount to shorten the fight.\n\n5. Repeat for the other two colors on later Heroic resets, or use eligible alts on separate Heroic lockouts. The account-wide criteria can combine their victories. Confirm all three color checks after the final kill.",
        stepCount = 5,
        waypoints = {
            { mapID = 114, x = 0.28600000000000003, y = 0.275, step = 1, label = "The Oculus - upper portal" },
            {
