    [1872] = {
        achievementId = 1872,
        name = "Zombiefest!",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Zombiefest!",
        acquisition = "Difficulty: Medium - Gather one hundred zombies, control damage and kill them within the same one-minute window.\n\n1. Set HEROIC and enter the Culling of Stratholme through the Caverns of Time. Complete Chromie's introduction or use her available skip, then start Arthas's event. Track Zombiefest! so you can see its kill count and one-minute timer.\n\n2. Clear the ten street waves, Meathook and Salramm normally. Speak to Arthas at the town hall, defeat the Infinite enemies and Chrono-Lord Epoch, then speak to Arthas to open the secret bookcase passage.\n\n3. Follow the passage to the burning alley. Leave Arthas WAITING at the bottom: do not choose the dialogue that starts his next escort. Dismiss pets and remove retaliation damage or other effects that could kill a Risen Zombie early.\n\n4. Walk the entire alley toward Mal'Ganis's empty square, gathering EVERY Risen Zombie without killing any. Check both sides, carts and corners. Slow down for the trailing zombies so they do not reset; wait for them to join the final pack.\n\n5. Kill the gathered zombies with area damage. The final alley contains the required 100, and the minute starts at the FIRST zombie death. If the count stops at 99, immediately look back for a straggler. A later reply also reports finding replacement spawns near the alley entrance.\n\n6. If the minute expires, keep Mal'Ganis alive and Arthas waiting, allow the alley to repopulate and try again. Resume the escort only after checking achievement credit. You do not need to kite Salramm into the town hall for this route.",
        stepCount = 6,
        waypoints = {
            {
                mapID = 75,
                x = 0.569,
                y = 0.8240000000000001,
                step = 1,
                label = "Culling of Stratholme - Caverns of Time portal",
