    [1873] = {
        achievementId = 1873,
        name = "Lodi Dodi We Loves the Skadi",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Lodi Dodi We Loves the Skadi",
        acquisition = "Difficulty: Medium - Collect the harpoons and execute Skadi's required gauntlet timing or single-pass objective.\n\n1. Set Heroic and reach Skadi's gauntlet in Utgarde Pinnacle. Track this achievement before approaching Skadi: the THREE-minute timer begins when he mounts Grauf and starts the gauntlet, not when he lands.\n\n2. Advance to the launcher end, kill the Ymirjar Harpooners and loot THREE Harpoons promptly. Save all three shots until Grauf is in range so you can bring him down during one pass.\n\n3. Click the harpoon launchers three times in quick succession while Grauf passes. Kill Skadi immediately after he lands, before the original gauntlet timer expires. Do not stop the timer mentally after shooting the drake; Skadi's death is the finishing condition.\n\n4. If you need another setup attempt BEFORE killing Skadi, collect harpoons and run back into Gortok's room until the event fully resets. Keep the collected harpoons, verify the achievement timer has reset too, then restart and rush the launchers. Old five-harpoon preparations are unnecessary.",
        stepCount = 4,
        waypoints = {
            { mapID = 117, x = 0.573, y = 0.467, step = 1, label = "Utgarde Pinnacle - upper portal" },
