        name = "You Don't Have an Eternity (25 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "You Don't Have an Eternity (25 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Set Legacy Raid Size to 25 players outside the instance. Fly to Coldarra in Borean Tundra and enter the EYE OF ETERNITY on the highest ring of the Nexus tower. The Nexus and Oculus portals are different instances.\n\n2. Use the central focusing device to start Malygos. Damage him to trigger phase 2. He can remain at 1 health until the scripted transitions finish; this is not a reason to reset.\n\n3. In phase 2, kill every Nexus Lord and Scion of Eternity. Ranged attacks can reach the flying enemies; otherwise kill a descending Nexus Lord and mount its dropped disc to fly to them. Stay inside the anti-magic bubbles if damage matters.\n\n4. When the platform breaks, wait for your red drake and its vehicle bar. Target Malygos and use Flame Spike (1), Flame Spike (1), Engulf in Flames (2); repeat, adding Revivify (3) to heal if needed and moving out of Static Fields. Finish the dragon and wait for credit.\n\n5. The whole encounter must finish within SIX minutes of the pull, including the scripted transitions. Attack each available target promptly; the old five-minute and spark-stacking strategies are obsolete for a high-level run.",
        stepCount = 5,
        waypoints = { { mapID = 114, x = 0.275, y = 0.266, step = 1, label = "Eye of Eternity - highest Nexus portal" } },
