    [1876] = {
        achievementId = 1876,
        name = "Besting the Black Dragonflight (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Besting the Black Dragonflight (10 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Set Legacy Raid Size to 10 players outside. Enter the chamber beneath Wyrmrest Temple in Dragonblight (59.8, 54.6) and choose OBSIDIAN SANCTUM, not Ruby Sanctum.\n\n2. Clear a safe route to Sartharion on the central island. Killing the three side drakes first is optional for this simple clear.\n\n3. At high level, go straight to Sartharion and kill him before Shadron lands and grants immunity. A fast kill with the drakes alive at the pull is valid; you do not have to wait for all three to land. Loot the boss before leaving.",
        stepCount = 3,
        waypoints = { { mapID = 115, x = 0.598, y = 0.546, step = 1, label = "Obsidian Sanctum - below Wyrmrest Temple" } },
        sources = {},
