    [1877] = {
        achievementId = 1877,
        name = "Less Is More (25 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Less Is More (25 player)",
        acquisition = "Difficulty: Easy - Defeat the required legacy raid bosses in the correct size and mode, allowing scripted events to finish.\n\n1. Set Legacy Raid Size to 25 players outside. Enter the chamber beneath Wyrmrest Temple in Dragonblight (59.8, 54.6) and choose OBSIDIAN SANCTUM, not Ruby Sanctum.\n\n2. Keep at most 20 players inside throughout the run. Kill Tenebron, Shadron and Vesperon SEPARATELY on their ledges before attacking Sartharion. Each named drake is a checklist criterion.\n\n3. Then kill Sartharion on the central island. Killing Sartharion first causes unengaged drakes to disappear and can leave Less Is More incomplete, even though it is a good route for the three-drake mount.",
        stepCount = 3,
        waypoints = { { mapID = 115, x = 0.598, y = 0.546, step = 1, label = "Obsidian Sanctum - below Wyrmrest Temple" } },
        sources = { "https://www.wowhead.com/achievement=624#comments:id=2075942" },
