    [1919] = {
        achievementId = 1919,
        name = "On The Rocks",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "On The Rocks",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Heroic and enter the LOWER Utgarde Keep portal in Howling Fjord. Follow the opening route to Prince Keleseth.\n\n2. At high level, kill Keleseth immediately with a single-target attack. He does not have to cast a Frost Tomb first; later Retail comments confirm the fast kill satisfies the achievement.\n\n3. If anyone is entombed, leave the Frost Tomb completely alone and keep that player alive until it expires naturally. Avoid cleaves, ground effects and uncontrolled pets near the tomb. Do not use old Blink/PvP-trinket escape advice: later corrections report those escapes or a death inside the tomb can invalidate the attempt.\n\n4. Finish Keleseth without shattering any tomb and check the achievement. This is Prince Keleseth in Utgarde Keep, not the similarly named Blood Prince Council encounter in Icecrown Citadel.",
        stepCount = 4,
        waypoints = {
            { mapID = 117, x = 0.5820000000000001, y = 0.489, step = 1, label = "Utgarde Keep - lower portal" },
            {
                mapID = 133,
                x = 0.289,
