    [1956] = {
        achievementId = 1956,
        name = "Higher Learning",
        category = "Exploration",
        sourceType = "Achievement",
        source = "Higher Learning",
        acquisition = "Difficulty: Hard - Find all eight correct Dalaran books among decoys and multi-hour respawn timers.\n\n1. In ORIGINAL Northrend Dalaran, track Higher Learning and visit all eight book spawns below. Read the full title: an unrelated book in the same spot is a placeholder. Read placeholders too to clear them, then repeat the circuit after respawns.\n\n2. Introduction: enter the Violet Gate portal room (56.7, 46.1) and inspect the floor beside its northern/right bookcase.\n\n3. Conjuration: inside the Violet Citadel (30.9, 46.3), inspect the bottom of the bookcase on your right on the entrance floor.\n\n4. Divination: go UPSTAIRS in the Violet Citadel (26.5, 51.7), near the Caverns of Time portal area, and check the floor by the shelves.\n\n5. Enchantment: enter Threads of Fate (43.6, 47.1), climb upstairs and go onto its balcony. Check the crate outside.\n\n6. Transmutation: inspect the ground-floor western bookcase near the entrance/stove in the Legerdemain Lounge (46.9, 39.8).\n\n7. Necromancy: go UPSTAIRS in the same lounge (46.9, 39.1), into the western bedroom, and inspect the empty bookcase. This is a separate spawn from Transmutation.\n\n8. Abjuration: in the Dalaran Visitor Center (52.2, 55.5), inspect the floor to the right of the entrance beside the small table/books.\n\n9. Illusion: near the Violet Hold entrance (64.5, 52.8), inspect the crate against the wall beside Archmage Timear. Do not enter the dungeon.\n\n10. Repeat only missing titles until all eight credit. Check your Toy Box for The Schools of Arcane Magic - Mastery: current comments report it can be learned directly rather than arriving by mail. Using that toy IN NORTHREND DALARAN and speaking to Vargoth gives the separate Familiar reward.",
        stepCount = 10,
        waypoints = {
            { mapID = 125, x = 0.5670000000000001, y = 0.461, step = 2, label = "Introduction - Violet Gate floor" },
            { mapID = 125, x = 0.309, y = 0.46299999999999997, step = 3, label = "Conjuration - Citadel entrance floor" },
            { mapID = 125, x = 0.265, y = 0.517, step = 4, label = "Divination - Citadel UPSTAIRS" },
            { mapID = 125, x = 0.436, y = 0.47100000000000003, step = 5, label = "Enchantment - Threads of Fate BALCONY" },
            { mapID = 125, x = 0.469, y = 0.39799999999999996, step = 6, label = "Transmutation - Legerdemain DOWNSTAIRS" },
            { mapID = 125, x = 0.469, y = 0.391, step = 7, label = "Necromancy - Legerdemain UPSTAIRS bedroom" },
            { mapID = 125, x = 0.522, y = 0.555, step = 8, label = "Abjuration - Visitor Center floor" },
            { mapID = 125, x = 0.645, y = 0.528, step = 9, label = "Illusion - Violet Hold crate" },
        },
        tips = "Spawns can take hours and can produce decoys. A missing book today does not make the achievement retired; February 2026 replies confirm completion in 12.0.",
        sources = {
            "https://www.wowhead.com/achievement=1956#comments:id=595175",
            "https://www.wowhead.com/achievement=1956#comments:id=1758359",
            "https://www.wowhead.com/achievement=1956#comments:id=1964160",
            "https://www.wowhead.com/achievement=1956#comments:id=6102467",
            "https://www.wowhead.com/achievement=1956#comments:id=6270986",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1956",
        sourceURL = "https://www.wowhead.com/achievement=1956#comments",
        difficultyReason = "Find all eight correct Dalaran books among decoys and multi-hour respawn timers.",
        difficulty = "hard",
    },
    [1957] = {
        achievementId = 1957,
        name = "There's Gold In That There Fountain",
        category = "Professions",
        sourceType = "Achievement",
        source = "There's Gold In That There Fountain",
        acquisition = "Difficulty: Medium - Fish the required fountain coin checklist; duplicate catches extend the collection effort.\n\n1. Travel to the ORIGINAL Dalaran above Crystalsong Forest in Northrend. Find the small Eventide fountain beside Marcia Chase at 52.5, 66.2. Legion Dalaran's lookalike fountain has different junk coins and does not complete these lists.\n\n2. Learn Fishing, stand at the fountain and cast into its water. Loot every catch. Track the 15 gold named coins in the achievement checklist; repeated catches of a coin you already have do not fill missing names.\n\n3. When you catch a gold coin, right-click it to throw it back for the two-minute Lucky buff. Its achievement credit was already recorded when caught. Refresh near expiry rather than throwing several at once: the buff does not stack.\n\n4. Continue fishing and maintaining Lucky while any required coin is missing. You do not need to store all coins at once. There is no fixed cast total or time guarantee for the last coin.\n\n5. Check every named criterion in this coin tier. Keep fishing the same fountain for the other two metal lists if you also want The Coin Master and its reward.",
        stepCount = 5,
        waypoints = {
            { mapID = 125, x = 0.525, y = 0.662, step = 1, label = "Eventide fountain - Northrend coin achievements" },
            { mapID = 125, x = 0.525, y = 0.662, step = 3, label = "Throw back a gold coin for Lucky" },
        },
        tips = "This uses Northrend Dalaran (map 125). A particular old combined Fishing level is not required to cast. Lucky improves coin fishing; it cannot target a specific missing name.",
        sources = {
            "https://www.wowhead.com/achievement=1957#comments:id=444463",
            "https://www.wowhead.com/achievement=1957#comments:id=1618113",
            "https://www.wowhead.com/achievement=2095#comments:id=1410600",
            "https://www.wowhead.com/achievement=2096#comments:id=6053400",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1957",
        sourceURL = "https://www.wowhead.com/achievement=1957#comments",
        difficultyReason = "Fish the required fountain coin checklist; duplicate catches extend the collection effort.",
        difficulty = "medium",
    },
    [1958] = {
        achievementId = 1958,
        name = "I Smell A Giant Rat",
        category = "Professions",
        sourceType = "Achievement",
        source = "I Smell A Giant Rat",
        acquisition = "Difficulty: Hard - Personally fish and loot the rare sewer rat; buying a caged pet does not satisfy this catch achievement.\n\n1. Travel to Northrend Dalaran and descend into the Underbelly. Learn Fishing and make bag space. The dock at Cantrips & Crows (44.0, 65.0 on the sewer map) is a convenient confirmed fishing spot.\n\n2. Fish the sewer's open water repeatedly. You do not need a school, a particular daily quest or a special lure for the rat to be eligible. A Drowned Rat is junk and is not the required Giant Sewer Rat (43698).\n\n3. When the Giant Sewer Rat appears, LOOT the original item and accept any binding confirmation before moving or recasting. Check achievement credit, then learn the pet if desired.\n\n4. An alternative is the ORIGINAL Giant Sewer Rat item on the Black Market Auction House when it rotates in. Current Retail replies confirm that acquisition also awards this achievement. A normal Auction House CAGED pet only learns the pet and does not award it.",
        stepCount = 4,
        waypoints = {
