    [2016] = {
        achievementId = 2016,
        name = "Grizzled Veteran",
        category = "PvP",
        sourceType = "Achievement",
        source = "Grizzled Veteran",
        acquisition = "Difficulty: Medium - Complete the faction's Grizzly Hills daily checklist, including vehicle and controlled-objective quests.\n\n1. In Grizzly Hills, enable Trivial Quests and use your faction's quest givers below. All NINE different PvP dailies can be completed in one day; you do not need nine resets or every unrelated zone quest. Accepting tasks can flag you for PvP.\n\n2. At the Alliance side of Blue Sky Logging Grounds (39.4-40.5, 42.6-43.9), take Kick 'Em While They're Down (defeat fifteen Horde units/players), Life or Death (bandage ten Wounded Westfall Infantry), Pieces Parts (four Grooved Cogs, three Notched Sprockets, two High Tension Springs), and Shredder Repair (deliver three Broken-down Shredders). Use the supplied bandage/repair/vehicle interactions rather than killing the rescue targets.\n\n3. At Blackriver Logging Camp, take Blackriver Skirmish from Scout Captain Carter (29.9, 59.8). Defeat ten Horde units or players INSIDE that logging area and return the quest.\n\n4. At the Alliance Venture Bay camp (22.0-22.2, 80.7-81.2), finish Smoke 'Em Out (use Smoke Bombs to drive twenty Venture Company Stragglers out of buildings), Down With Captain Zorna! (kill the captain), and Keep Them at Bay! (ten Horde units/players in Venture Bay).\n\n5. For Riding the Red Rocket, reach the lighthouse island (14.8, 86.6), become PvP-flagged and stay by its control flag until your faction has FULL control. The quest giver appears only then. Other Venture Bay tasks do not require owning the lighthouse.\n\n6. Accept the rocket quest, obtain Element 115 BEFORE boarding a red rocket, and ride/steer it into the OPPOSING faction's lumber boat to destroy the shipment. Return for the turn-in; merely mounting a rocket is not the objective.\n\n7. Check all nine named criteria. The kill tasks accept the listed hostile NPC units, so an empty outdoor area does not prevent those from completing. Shredder deliveries, healing and smoke bombs still need their quest items/actions.",
        stepCount = 7,
        waypoints = {
            { mapID = 116, x = 0.396, y = 0.434, step = 2, label = "Alliance Blue Sky camp - four dailies" },
            { mapID = 116, x = 0.299, y = 0.598, step = 3, label = "Blackriver - faction skirmish daily" },
            { mapID = 116, x = 0.221, y = 0.812, step = 4, label = "Venture Bay - faction camp dailies" },
            { mapID = 116, x = 0.14800000000000002, y = 0.866, step = 5, label = "Lighthouse - reach FULL faction control" },
            {
                mapID = 116,
                x = 0.14800000000000002,
                y = 0.866,
                step = 6,
                label = "Red Rocket - obtain Element 115 before boarding",
            },
        },
        tips = "These are outdoor Grizzly Hills quests, not the Wintergrasp battleground. Old Honor reward totals are no longer accurate and are omitted.",
        sources = {
            "https://www.wowhead.com/achievement=2016#comments:id=956248",
            "https://www.wowhead.com/achievement=2016#comments:id=1661838",
            "https://www.wowhead.com/achievement=2016#comments:id=2099555",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2016",
        sourceURL = "https://www.wowhead.com/achievement=2016#comments",
        difficultyReason = "Complete the faction's Grizzly Hills daily checklist, including vehicle and controlled-objective quests.",
        difficulty = "medium",
    },
    [2017] = {
        achievementId = 2017,
        name = "Grizzled Veteran",
        category = "PvP",
        sourceType = "Achievement",
        source = "Grizzled Veteran",
        acquisition = "Difficulty: Medium - Complete the faction's Grizzly Hills daily checklist, including vehicle and controlled-objective quests.\n\n1. In Grizzly Hills, enable Trivial Quests and use your faction's quest givers below. All NINE different PvP dailies can be completed in one day; you do not need nine resets or every unrelated zone quest. Accepting tasks can flag you for PvP.\n\n2. At the Horde side of Blue Sky Logging Grounds (34.4, 32.7), take Keep 'Em on Their Heels (defeat fifteen Alliance units/players), Overwhelmed! (tourniquet ten Wounded Skirmishers), Making Repairs (four Grooved Cogs, three Notched Sprockets, two High Tension Springs), and Shred the Alliance (deliver three shredders). Use the supplied healing/vehicle interactions and return each shredder to the quest giver.\n\n3. Take Blackriver Brawl from Raider Captain Kronn near Blackriver Logging Camp (26.4, 65.7). Defeat ten Alliance units or players INSIDE the logging area and return the quest.\n\n4. At the Horde Venture Bay camp (10.1, 77.3 and 11.4, 76.7), finish Smoke 'Em Out (Smoke Bomb twenty Venture Company Stragglers from buildings), Crush Captain Brightwater! (kill the captain), and Keep Them at Bay (ten Alliance units/players in Venture Bay).\n\n5. For Riding the Red Rocket, reach the lighthouse island (14.8, 86.6), become PvP-flagged and stay by its control flag until your faction has FULL control. The quest giver appears only then. Other Venture Bay tasks do not require owning the lighthouse.\n\n6. Accept the rocket quest, obtain Element 115 BEFORE boarding a red rocket, and ride/steer it into the OPPOSING faction's lumber boat to destroy the shipment. Return for the turn-in; merely mounting a rocket is not the objective.\n\n7. Check all nine named criteria. The kill tasks accept the listed hostile NPC units, so an empty outdoor area does not prevent those from completing. Shredder deliveries, healing and smoke bombs still need their quest items/actions.",
