    [2036] = {
        achievementId = 2036,
        name = "Intense Cold",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Intense Cold",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Enter the Nexus on Heroic. Defeat Telestra, Anomalus and Ormorok and activate their containment spheres so Keristrasza is released.\n\n2. Stand beside Keristrasza and kill her promptly. Keep moving or jumping throughout any surviving fight: YOUR Intense Cold debuff must never reach three stacks. Other players' failures do not automatically invalidate your own attempt.\n\n3. If Crystal Chains roots you, remove the magic root or use an available root-breaking ability immediately, then move. Prepare that ability before freeing her. A fast direct kill is confirmed in later Retail replies; verify Heroic difficulty if no achievement appears.",
        stepCount = 3,
        waypoints = {
            { mapID = 114, x = 0.275, y = 0.267, step = 1, label = "The Nexus - entrance" },
            {
                mapID = 129,
                x = 0.275,
                y = 0.39899999999999997,
                step = 1,
                label = "Telestra / containment sphere",
                mapName = "The Nexus",
