            { mapID = 129, x = 0.62, y = 0.221, step = 1, label = "Anomalus / containment sphere", mapName = "The Nexus" },
            { mapID = 129, x = 0.562, y = 0.727, step = 1, label = "Ormorok / containment sphere", mapName = "The Nexus" },
            {
                mapID = 129,
                x = 0.36200000000000004,
                y = 0.674,
                step = 2,
                label = "Keristrasza - move and prevent three stacks",
                mapName = "The Nexus",
            },
        },
        tips = "Track Intense Cold on your own debuff bar. Retired talents, old potion level limits and old class rotations are unnecessary for a high-level Retail attempt.",
        sources = {
            "https://www.wowhead.com/achievement=2036#comments:id=418176",
            "https://www.wowhead.com/achievement=2036#comments:id=629616",
