    [2037] = {
        achievementId = 2037,
        name = "Chaos Theory",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Chaos Theory",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Enter the Nexus on Heroic and go to Anomalus on the northeastern platforms. Avoid killing Chaotic Rifts along the approach as well as those summoned during the boss fight; use single-target attacks and control pets or damage procs.\n\n2. At high level, kill Anomalus directly without attacking a rift. Later Retail comments and replies confirm a fast kill can award credit without waiting for an immunity phase.\n\n3. If he becomes immune, stop attacking and leave every Chaotic Rift alive. Kill only the smaller summoned enemies, away from rifts. Wait for Rift Shield to expire, then finish Anomalus. Do not follow old advice to destroy a rift to end the immunity.",
        stepCount = 3,
        waypoints = {
            { mapID = 114, x = 0.275, y = 0.267, step = 1, label = "The Nexus - entrance" },
            {
                mapID = 129,
                x = 0.62,
                y = 0.221,
                step = 2,
                label = "Anomalus - leave Chaotic Rifts alive",
                mapName = "The Nexus",
            },
        },
        tips = "Pet cleaves, ground effects and automatic retaliation can kill a rift accidentally. A completed Heroic kill locks another boss attempt until the next daily reset.",
