    [2038] = {
        achievementId = 2038,
        name = "Respect Your Elders",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Respect Your Elders",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Enter Ahn'kahet on Heroic via the left branch of Dragonblight's Nerubian pit. Reach Elder Nadox and control pet cleaves or automatic area damage before pulling.\n\n2. At high level, kill Nadox directly before he summons an Ahn'kahar Guardian. No Guardian has to spawn for the achievement to count; later Retail comments replace the old elaborate kiting setup with this fast kill.\n\n3. If a Guardian appears and grants immunity, leave it ALIVE. Have a second player hold it away from Nadox, or crowd-control it and move Nadox beyond its protective aura, then finish the boss. Distance matters; merely breaking line of sight does not remove the aura. Do not drag Nadox all the way to the instance entrance, which can trigger his enrage.",
