    [2039] = {
        achievementId = 2039,
        name = "Better Off Dred",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Better Off Dred",
        acquisition = "Difficulty: Medium - Keep King Dred alive while killing six qualifying raptors during his encounter.\n\n1. Set Heroic and reach King Dred's fenced raptor courtyard in Drak'Tharon Keep. Leave the small raptors ALIVE while clearing the rest of the approach; you need at least six available during the boss fight.\n\n2. Dismiss pets and remove uncontrolled cleave or retaliation damage. Gather the raptors without killing them, then engage King Dred with proximity or a non-damaging taunt. Make sure Dred is actually in combat before the first counted raptor dies.\n\n3. While Dred remains ALIVE, single-target SIX Drakkari Gutrippers/Drakkari Scytheclaws. Clear your target or stop auto-attacking between kills so Dred does not become your next automatic target. Killing all seven available raptors is a safe way to avoid a miscount.\n\n4. After the six qualifying deaths, kill Dred. Do not wait for an endless supply of newly summoned raptors: Call Raptor brings existing courtyard raptors into combat. Killing several before pulling Dred cannot be fixed by waiting for replacements.",
        stepCount = 4,
        waypoints = {
