    [2040] = {
        achievementId = 2040,
        name = "Less-rabi",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Less-rabi",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Heroic and enter Gundrak through the northwest portal in Zul'Drak (76.4, 21.3). Follow the western branch to Moorabi, near his altar.\n\n2. At high level, use a strong direct single-target attack to kill Moorabi before he can cast Transformation. This is the useful part of the numbered fast-kill guide; its old health and damage figures are not current requirements.\n\n3. If Moorabi survives, interrupt EVERY Transformation cast. Later casts become faster as his health drops. Do not let him finish transforming even once; kill him and confirm Less-rabi before continuing.",
        stepCount = 3,
        waypoints = {
            { mapID = 121, x = 0.764, y = 0.213, step = 1, label = "Gundrak - northwest entrance" },
