    [2041] = {
        achievementId = 2041,
        name = "Dehydration",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Dehydration",
        acquisition = "Difficulty: Medium - Obtain the required randomly selected Violet Hold boss, then preserve its prohibited adds or globule condition.\n\n1. Enter the ORIGINAL Violet Hold in Northrend Dalaran on Heroic. Start Sinclari's event and reach the first prisoner selection at wave 6. You need Ichoron, released from the water pool; if another prisoner is chosen, leave before killing it and reset from outside to reroll an unsaved instance.\n\n2. When Ichoron becomes attackable, kill him with a strong direct attack. Later Retail comments confirm that killing him before any globules spawn awards the achievement; you do not have to play through every old shield phase.\n\n3. If his Protective Bubble survives, attack until it breaks and then kill EVERY Ichor Globule before it reaches his body. A usable red Defense Control Crystal on the prison wall can kill the globules when activated at the split; use a fresh crystal for a later split and watch for any globule already close to him.\n\n4. Finish Ichoron with no globule having merged. If working on Defenseless in the same run, leave the crystals untouched and handle the globules manually, or use the immediate-kill route. After Ichoron has died, his replacement Swirling Water Revenant cannot award another attempt at this achievement.",
        stepCount = 4,
        waypoints = {
            { mapID = 125, x = 0.665, y = 0.6779999999999999, step = 1, label = "Original Violet Hold - entrance" },
            {
                mapID = 168,
                x = 0.556,
                y = 0.40369999999999995,
                step = 2,
                label = "Ichoron's pool - kill before globule merges",
                mapName = "The Violet Hold (Northrend)",
            },
        },
        tips = "The blue saboteur chooses the prisoner randomly. Reset the actual instance from outside for a reroll; restarting the same event alone can retain the same bosses.",
        sources = {
            "https://www.wowhead.com/achievement=2041#comments:id=502972",
            "https://www.wowhead.com/achievement=2041#comments:id=741103",
            "https://www.wowhead.com/achievement=2041#comments:id=831358",
            "https://www.wowhead.com/achievement=2041#comments:id=1604442",
            "https://www.wowhead.com/achievement=2041#comments:id=2372823",
            "https://www.wowhead.com/achievement=2041#comments:id=2534039",
            "https://www.wowhead.com/achievement=2041#comments:id=2878793",
            "https://www.wowhead.com/achievement=2041#comments:id=5626058",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2041",
        sourceURL = "https://www.wowhead.com/achievement=2041#comments",
