    [2042] = {
        achievementId = 2042,
        name = "Shatter Resistant",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Shatter Resistant",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Heroic and enter Halls of Lightning beside Ulduar. Defeat Bjarngrim and continue through the slag room to Volkhan's forge.\n\n2. Kill Volkhan directly at high level. A fast kill before any golems are shattered satisfies the achievement; waiting for the mechanic is unnecessary.\n\n3. If the fight lasts, avoid damaging his Molten Golems into their brittle state. Move away from the slow golems and finish Volkhan before he can shatter five. The limit concerns SHATTERED Brittle Golems, not merely the number he summons.",
        stepCount = 3,
        waypoints = {
            {
                mapID = 120,
                x = 0.45299999999999996,
                y = 0.21600000000000003,
                step = 1,
                label = "Halls of Lightning - entrance",
            },
            {
                mapID = 139,
                x = 0.377,
                y = 0.209,
                step = 2,
                label = "Volkhan - kill before five golem shatters",
                mapName = "Halls of Lightning - Walk of the Makers",
            },
        },
        sources = {
            "https://www.wowhead.com/achievement=2042#comments:id=407708",
            "https://www.wowhead.com/achievement=2042#comments:id=642622",
            "https://www.wowhead.com/achievement=2042#comments:id=3140206",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2042",
        sourceURL = "https://www.wowhead.com/achievement=2042#comments",
        difficultyReason = "A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.",
        difficulty = "easy",
