    [2043] = {
        achievementId = 2043,
        name = "The Incredible Hulk",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "The Incredible Hulk",
        acquisition = "Difficulty: Hard - Use controlled low damage to let a Scourge Hulk kill the ritual enemy with its required sword attack.\n\n1. Enter Utgarde Pinnacle on HEROIC. Clear the approach but leave the Scourge Hulks alive as spare targets. At Svala's room, wait for her Lich King dialogue to finish. Remove damage procs, dismiss pets and prepare attacks weak enough to leave BOTH enemies alive.\n\n2. If needed, remove gear and use Whole-Body Shrinka' BEFORE combat; its damage reduction lasts only three minutes. Naked caster melee attacks or single ticks of a Monk's Crackling Jade Lightning have worked in later Retail reports. Damage varies by class: do not assume one punch is safe. Use an eligible lower-level alt if you cannot control it.\n\n3. Engage Svala FIRST with proximity or a non-damaging taunt, then collect the Hulk at the far end of the room. Carefully lower the Hulk to roughly 10-20% without a damage-over-time effect. Stop auto-attacking immediately after every deliberate hit.\n\n4. Position near the back corner under the stairs or the upper entry doorway so the Hulk must walk back to the altar after your teleport. Reduce Svala below 50% with controlled single-target hits, then STOP attacking. Do not kill her or the three Ritual Channelers.\n\n5. During Ritual of the Sword, wait while stunned. The Hulk must reach the altar and be hit by the descending sword and its damage effect. Let Svala's effect kill the weakened Hulk; this avoids the conflicting reports about player finishing blows. Check for credit at the Hulk's death, then kill Svala.\n\n6. If the Hulk dies early, misses the sword or survives its damage, leave Svala ALIVE and run out to reset the unfinished encounter. Another nearby Hulk can provide a spare attempt. Killing Svala saves the Heroic boss and prevents another attempt on that character until reset.",
        stepCount = 6,
        waypoints = {
            { mapID = 117, x = 0.573, y = 0.467, step = 1, label = "Utgarde Pinnacle - upper entrance" },
            {
                mapID = 136,
                x = 0.363,
                y = 0.706,
                step = 1,
                label = "Svala - leave surrounding Scourge Hulks alive",
                mapName = "Utgarde Pinnacle - Lower Pinnacle",
            },
            {
                mapID = 136,
                x = 0.363,
                y = 0.706,
                step = 3,
                label = "Engage Svala FIRST, then weaken a Hulk",
                mapName = "Utgarde Pinnacle - Lower Pinnacle",
            },
            {
                mapID = 136,
                x = 0.363,
                y = 0.706,
                step = 5,
                label = "Svala's altar - sword must kill the Hulk",
                mapName = "Utgarde Pinnacle - Lower Pinnacle",
            },
        },
        tips = "Midnight replies confirm both caster and Shrinka' approaches, but neither works for every damage setup. One newer comment combines Shrinka' with the one-minute Resurrection Sickness; do not rely on the obsolete long sickness window. Soft Foam Sword is not an instance solution, and Fel-Scarred passive damage can ruin a Demon Hunter attempt.",
        sources = {
            "https://www.wowhead.com/achievement=2043#comments:id=1856997",
            "https://www.wowhead.com/achievement=2043#comments:id=2466247",
            "https://www.wowhead.com/achievement=2043#comments:id=5709367",
            "https://www.wowhead.com/achievement=2043#comments:id=5761147",
            "https://www.wowhead.com/achievement=2043#comments:id=6044990",
            "https://www.wowhead.com/achievement=2043#comments:id=6053930",
            "https://www.wowhead.com/achievement=2043#comments:id=6067343",
            "https://www.wowhead.com/achievement=2043#comments:id=6126733",
            "https://www.wowhead.com/achievement=2043#comments:id=6169675",
            "https://www.wowhead.com/achievement=2043#comments:id=6375532",
            "https://www.wowhead.com/comment/show-replies?id=2466247",
            "https://www.wowhead.com/comment/show-replies?id=6169675",
            "https://www.wowhead.com/comment/show-replies?id=6126733",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2043",
        sourceURL = "https://www.wowhead.com/achievement=2043#comments",
        difficultyReason = "Use controlled low damage to let a Scourge Hulk kill the ritual enemy with its required sword attack.",
        difficulty = "hard",
