    [2044] = {
        achievementId = 2044,
        name = "Ruby Void",
        category = "Raids",
        sourceType = "Achievement",
        source = "Ruby Void",
        acquisition = "Difficulty: Medium - Use the permitted Emerald drake's poison and self-healing mechanics to defeat Eregos without Ruby drakes.\n\n1. Set HEROIC and enter the Oculus through Coldarra's upper dungeon portal. Kill Drakos and choose an EMERALD essence from the freed drakes; nobody may use a Ruby drake for Eregos.\n\n2. Use the drake to reach the construct platforms, dismount and destroy all ten Centrifuge Constructs, then kill Varos. Follow Urom through his platform summons, defeat him and fly to Eregos's highest ring.\n\n3. On the Emerald drake, keep three stacks of Leeching Poison (1) on Eregos. Apply and refresh poison on the summoned whelps as well so they die and provide healing. Use Touch the Nightmare (2) only with enough health to survive its self-damage; maintaining poison and killing whelps takes priority.\n\n4. Move around the upper ring during Planar Shift to avoid the pursuing orbs, then refresh poison and finish Eregos. Do not switch to a Ruby drake mid-fight. This all-Emerald route can also award Amber Void and the Emerald criterion of Experienced Drake Rider.",
        stepCount = 4,
        waypoints = {
            { mapID = 114, x = 0.28600000000000003, y = 0.275, step = 1, label = "The Oculus - upper dungeon portal" },
            {
                mapID = 143,
                x = 0.491,
                y = 0.762,
                step = 1,
                label = "Drakos - choose Emerald after freeing the drakes",
                mapName = "The Oculus - Band of Variance",
            },
            {
                mapID = 144,
                x = 0.461,
                y = 0.192,
                step = 2,
                label = "Varos - destroy constructs first",
                mapName = "The Oculus - Band of Acceleration",
            },
            {
                mapID = 145,
                x = 0.7070000000000001,
                y = 0.27399999999999997,
                step = 2,
                label = "Urom - finish platform sequence",
                mapName = "The Oculus - Band of Transmutation",
            },
            {
                mapID = 146,
                x = 0.469,
                y = 0.209,
                step = 3,
                label = "Eregos - poison boss and whelps; no Ruby drake",
                mapName = "The Oculus - Band of Alignment",
            },
        },
        tips = "If attempting this with friends, everyone must avoid Ruby. The old five-Amber coordinated rotation is an alternative, but is unnecessary for this route. Using a forbidden drake then deleting its essence at low boss health does not repair the attempt.",
        sources = {
            "https://www.wowhead.com/achievement=2044#comments:id=473425",
            "https://www.wowhead.com/achievement=2044#comments:id=1636151",
