        sourceURL = "https://www.wowhead.com/achievement=2044#comments",
        difficultyReason = "Use the permitted Emerald drake's poison and self-healing mechanics to defeat Eregos without Ruby drakes.",
        difficulty = "medium",
    },
    [2045] = {
        achievementId = 2045,
        name = "Emerald Void",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Emerald Void",
        acquisition = "Difficulty: Easy - Use a permitted Ruby drake and its attacks for the Eregos kill; do not use the prohibited color.\n\n1. Set Dungeon Difficulty to HEROIC outside the Oculus. Enter Coldarra's UPPER portal in Borean Tundra, defeat Drakos, then take a RUBY essence from the freed red drake. Nobody in the party may use an Emerald (green) drake for Eregos.\n\n2. Mount the Ruby drake and fly to the construct level. Dismount to destroy all ten Centrifuge Constructs, then defeat Varos after his shield disappears. Follow Urom through his platform packs, defeat him, and remount for the highest ring.\n\n3. Engage Ley-Guardian Eregos on your RUBY drake. Use Searing Wrath against him and the whelps; its chaining attack helps clear the smaller enemies. Use Evasive Maneuvers if needed. During Planar Shift, move around the upper ring away from the pursuing orbs, then resume attacking when Eregos becomes vulnerable.\n\n4. Finish Eregos with no Emerald drake used by any party member. Remaining mounted also gives Ruby credit toward Experienced Drake Rider. An all-Ruby kill can award Amber Void at the same time, because no Amber drake was used either.",
        stepCount = 4,
        waypoints = {
            { mapID = 114, x = 0.28600000000000003, y = 0.275, step = 1, label = "The Oculus - upper portal" },
            {
                mapID = 143,
