            {
                mapID = 145,
                x = 0.7070000000000001,
                y = 0.27399999999999997,
                step = 2,
                label = "Urom - finish the platform sequence",
                mapName = "The Oculus - Band of Transmutation",
            },
            {
                mapID = 146,
                x = 0.469,
                y = 0.209,
                step = 3,
                label = "Eregos - Ruby vehicle attacks / avoid planar orbs",
                mapName = "The Oculus - Band of Alignment",
