        tips = "At high level, later Retail reports confirm solo kills using the drake's attack. The old five-Amber coordination, player healer on a rock and borrowed stamina buffs are unnecessary for this route. Do not confuse Emerald Void (no green drake) with Amber Void (no bronze drake).",
