    [2046] = {
        achievementId = 2046,
        name = "Amber Void",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Amber Void",
        acquisition = "Difficulty: Easy - Use a permitted Ruby drake and its attacks for the Eregos kill; do not use the prohibited color.\n\n1. Set Heroic and enter the Oculus at Coldarra's upper portal. Defeat Drakos and take a RUBY essence from the freed red drake. Have every party member avoid Amber drakes; the restriction applies to the whole party.\n\n2. Disable Varos's shield by killing the Centrifuge Constructs and defeat him. Follow Urom's platform packs and defeat Urom, then mount your permitted drake and fly to Eregos on the highest ring.\n\n3. Defeat Eregos without anyone using an AMBER drake. At high level, a Ruby drake's Searing Wrath can handle the boss and whelps; use Evasive Maneuvers if needed and move away from the orbs during immunity phases. A permitted Emerald drake can heal in a group if necessary.\n\n4. Stay within the upper-ring encounter area and finish Eregos. Check Amber Void after the kill. This is an Oculus drake-color restriction, not a Malygos/Eye of Eternity mechanic, and it does not require the entire party to use five drakes.",
