    [2047] = {
        achievementId = 2047,
        name = "Gonna Go When the Volcano Blows (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Gonna Go When the Volcano Blows (10 player)",
        acquisition = "Difficulty: Easy - Kill Sartharion promptly with the required drakes alive and avoid Lava Strike if the fight lasts.\n\n1. Set Legacy Raid Size to 10 players outside. Enter the chamber beneath Wyrmrest Temple in Dragonblight (59.8, 54.6) and choose OBSIDIAN SANCTUM, not Ruby Sanctum.\n\n2. Clear an approach to the central island and kill Sartharion immediately with a direct attack. This avoids the time spent exposed to Lava Strike. No drake or add count is required.\n\n3. If the encounter lasts, keep moving away from the smoky fireballs falling from above until Sartharion dies. LAVA STRIKE is the failing effect; it is different from the large moving flame walls. Credit is evaluated for your own avoidance.",
        stepCount = 3,
        waypoints = { { mapID = 115, x = 0.598, y = 0.546, step = 1, label = "Obsidian Sanctum - below Wyrmrest Temple" } },
        sources = {
            "https://www.wowhead.com/achievement=2047#comments:id=476388",
            "https://www.wowhead.com/achievement=2047#comments:id=2082243",
