        acquisition = "Difficulty: Easy - Kill Sartharion promptly with the required drakes alive and avoid Lava Strike if the fight lasts.\n\n1. Set Legacy Raid Size to 10 players outside. Enter the chamber beneath Wyrmrest Temple in Dragonblight (59.8, 54.6) and choose OBSIDIAN SANCTUM, not Ruby Sanctum.\n\n2. Leave ALL THREE side drakes alive before pulling Sartharion. This exceeds the one- or two-drake minimum and can award the lower drake-count achievements together with The Twilight Zone. Do not clear the named drakes on their ledges.\n\n3. At high level, go straight to Sartharion and kill him before Shadron lands and grants immunity. A fast kill with the drakes alive at the pull is valid; you do not have to wait for all three to land. Loot the boss before leaving.",
