    [2056] = {
        achievementId = 2056,
        name = "Volunteer Work",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Volunteer Work",
        acquisition = "Difficulty: Medium - Hold damage for the sacrifice or defense event and preserve the exact encounter condition.\n\n1. Set Heroic and enter Ahn'kahet. Reach Jedoga Shadowseeker's platform beyond Prince Taldaram and kill the Twilight INITIATES that start her encounter. These initial enemies are different from the Twilight VOLUNTEERS around the arena.\n\n2. At high level, directly kill Jedoga after she descends. Later Retail comments confirm that skipping the sacrifice with a fast kill awards credit, provided you have not killed a Volunteer.\n\n3. If she rises for the sacrifice, STOP area damage and let the selected Twilight Volunteer walk into the circle and sacrifice itself. Do not kill it. When Jedoga lands empowered, survive with defensives and avoid Cyclone Strike, then finish her. Her own sacrifice of the Volunteer does not count as you killing it.",
        stepCount = 3,
        waypoints = {
            { mapID = 115, x = 0.284, y = 0.517, step = 1, label = "Ahn'kahet - entrance" },
            {
                mapID = 132,
                x = 0.48219999999999996,
                y = 0.7254,
                step = 1,
                label = "Jedoga's platform - Initiates start the encounter",
                mapName = "Ahn'kahet: The Old Kingdom",
            },
            {
                mapID = 132,
                x = 0.48219999999999996,
                y = 0.7254,
                step = 3,
                label = "Let the Volunteer complete its sacrifice",
                mapName = "Ahn'kahet: The Old Kingdom",
            },
        },
        tips = "Keep the fight on her platform. Old waterfall/stair kiting instructions were explicitly corrected because they reset the boss.",
        sources = {
            "https://www.wowhead.com/achievement=2056#comments:id=467804",
            "https://www.wowhead.com/achievement=2056#comments:id=573874",
