            "https://www.wowhead.com/achievement=2056#comments:id=5178580",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2056",
        sourceURL = "https://www.wowhead.com/achievement=2056#comments",
        difficultyReason = "Hold damage for the sacrifice or defense event and preserve the exact encounter condition.",
        difficulty = "medium",
    },
    [2057] = {
        achievementId = 2057,
        name = "Oh Novos!",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Oh Novos!",
        acquisition = "Difficulty: Medium - Hold damage for the sacrifice or defense event and preserve the exact encounter condition.\n\n1. Enter Drak'Tharon Keep on Heroic and reach Novos's room. Move around the LEFT edge and climb the staircase before pulling. Engage Novos from range so you can already intercept the first descending enemies.\n\n2. Stay at the TOP of the stairs and kill every descending undead before it reaches the room floor. Crystal Handlers enter from other directions and run toward you; let them come up to your position and kill all four there. Check behind you between stair waves.\n\n3. Once all four handlers die, Novos's barrier falls and the wave phase ends. Finish Novos. Keep the achievement tracked: if the criterion turns red, something reached the floor and that pull failed. Avoid an early one-shot through the barrier, which older comments report can leave the event running.",
        stepCount = 3,
        waypoints = {
            { mapID = 121, x = 0.28600000000000003, y = 0.8690000000000001, step = 1, label = "Drak'Tharon Keep - entrance" },
            {
                mapID = 160,
                x = 0.7020000000000001,
                y = 0.479,
                step = 1,
                label = "Novos room - take stairs before ranged pull",
                mapName = "Drak'Tharon Keep - The Vestibules",
            },
            {
                mapID = 160,
                x = 0.7020000000000001,
                y = 0.479,
                step = 3,
                label = "Novos - finish after four Crystal Handlers",
                mapName = "Drak'Tharon Keep - The Vestibules",
            },
        },
        sources = {
            "https://www.wowhead.com/achievement=2057#comments:id=407687",
            "https://www.wowhead.com/achievement=2057#comments:id=1956272",
            "https://www.wowhead.com/achievement=2057#comments:id=3242345",
            "https://www.wowhead.com/achievement=2057#comments:id=5889790",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2057",
        sourceURL = "https://www.wowhead.com/achievement=2057#comments",
        difficultyReason = "Hold damage for the sacrifice or defense event and preserve the exact encounter condition.",
        difficulty = "medium",
    },
    [2058] = {
        achievementId = 2058,
        name = "Snakes. Why'd It Have To Be Snakes?",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Snakes. Why'd It Have To Be Snakes?",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Heroic and enter Gundrak. Reach Slad'ran at the first snake chamber and clear nearby trash before engaging.\n\n2. At high level, kill Slad'ran immediately. A quick kill before Snake Wrap occurs satisfies the criterion; you do not need to summon snakes first.\n\n3. If he survives, kill the small constricting snakes promptly before their stacks cause Snake Wrap. Keep them off the player holding healing aggro and use area damage when several arrive together. Do not rely on the old water-evade or no-snakes-in-the-next-room tricks; comments report snakes reaching those positions too.",
        stepCount = 3,
        waypoints = {
            { mapID = 121, x = 0.764, y = 0.213, step = 1, label = "Gundrak - northwest entrance" },
            { mapID = 153, x = 0.539, y = 0.485, step = 2, label = "Slad'ran - prevent Snake Wrap", mapName = "Gundrak" },
        },
        sources = {
            "https://www.wowhead.com/achievement=2058#comments:id=499840",
            "https://www.wowhead.com/achievement=2058#comments:id=500351",
            "https://www.wowhead.com/achievement=2058#comments:id=569966",
            "https://www.wowhead.com/achievement=2058#comments:id=3225072",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2058",
        sourceURL = "https://www.wowhead.com/achievement=2058#comments",
        difficultyReason = "A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.",
        difficulty = "easy",
    },
    [2076] = {
        achievementId = 2076,
        name = "Armored Brown Bear",
        category = "Collections",
        sourceType = "Achievement",
        source = "Armored Brown Bear",
        acquisition = "Difficulty: Easy - Buy and use the named gold-vendor item; no rare drop or reputation rank is required.\n\n1. Travel to the ORIGINAL Dalaran above Crystalsong Forest in Northrend and find Mei Francis outdoors at 57.8, 42.5, near the Horde-quarter entrance. She is the exotic-mount vendor, not Breanni inside the nearby pet shop.\n\n2. Bring 750 gold to cover Armored Brown Bear's base price. No Kirin Tor reputation rank is required to buy it; your current reputation can lower the displayed gold price. An Exalted discount normally reduces it to 600.0 gold.\n\n3. Buy the reins for your faction and USE them from your bags, then check the achievement and Mount Journal. Do not confuse this brown bear with the different Black War Bear from faction-leader kills.\n\n4. If this mount is already learned, check existing account achievement credit before buying another copy. The journal handles eligible faction counterparts; an unrelated same-color bear/mammoth does not substitute.",
        stepCount = 4,
        waypoints = {
            { mapID = 125, x = 0.578, y = 0.425, step = 1, label = "Mei Francis - Northrend Dalaran" },
            { mapID = 125, x = 0.578, y = 0.425, step = 3, label = "Buy and learn Armored Brown Bear" },
        },
        sources = {
            "https://www.wowhead.com/achievement=2076#comments",
