        acquisition = "Difficulty: Easy - Buy and use the named gold-vendor item; no rare drop or reputation rank is required.\n\n1. Travel to the ORIGINAL Dalaran above Crystalsong Forest in Northrend and find Mei Francis outdoors at 57.8, 42.5, near the Horde-quarter entrance. She is the exotic-mount vendor, not Breanni inside the nearby pet shop.\n\n2. Bring 10000 gold to cover Wooly Mammoth's base price. No Kirin Tor reputation rank is required to buy it; your current reputation can lower the displayed gold price. An Exalted discount normally reduces it to 8000.0 gold.\n\n3. Buy the reins for your faction and USE them from your bags, then check the achievement and Mount Journal. Retail Wooly Mammoth is a GOLD purchase; old Emblem of Heroism and Justice Point costs are obsolete.\n\n4. If this mount is already learned, check existing account achievement credit before buying another copy. The journal handles eligible faction counterparts; an unrelated same-color bear/mammoth does not substitute.",
