        name = "Traveler's Tundra Mammoth",
        category = "Collections",
        sourceType = "Achievement",
        source = "Traveler's Tundra Mammoth",
        acquisition = "Difficulty: Easy - Buy and use the named gold-vendor item; no rare drop or reputation rank is required.\n\n1. Travel to the ORIGINAL Dalaran above Crystalsong Forest in Northrend and find Mei Francis outdoors at 57.8, 42.5, near the Horde-quarter entrance. She is the exotic-mount vendor, not Breanni inside the nearby pet shop.\n\n2. Bring 20000 gold to cover Traveler's Tundra Mammoth's base price. No Kirin Tor reputation rank is required to buy it; your current reputation can lower the displayed gold price. An Exalted discount normally reduces it to 16000.0 gold.\n\n3. Buy the reins for your faction and USE them from your bags, then check the achievement and Mount Journal. This is the mammoth with repair/trade NPCs. Grand Ice/Grand Black War Mammoths have passengers but no vendors.\n\n4. If this mount is already learned, check existing account achievement credit before buying another copy. The journal handles eligible faction counterparts; an unrelated same-color bear/mammoth does not substitute.",
