    [2080] = {
        achievementId = 2080,
        name = "Black War Mammoth",
        category = "Collections",
        sourceType = "Achievement",
        source = "Black War Mammoth",
        acquisition = "Difficulty: Medium - Earn fifteen Marks of Honor, then buy and learn the Black War Mammoth from a friendly Wintergrasp quartermaster.\n\n1. Collect FIFTEEN Marks of Honor items from PvP reward sources. Honor points, old Wintergrasp Marks and Stone Keeper's Shards are different resources; the original achievement comments quote superseded prices.\n\n2. Travel to OUTDOOR Wintergrasp in Northrend and check which faction controls the fortress. Visit its courtyard quartermaster near 51.7, 17.2 when friendly: Knight Dameron for Alliance or Stone Guard Mukar for Horde.\n\n3. Buy Reins of the Black War Mammoth for 15 Marks of Honor and use the reins. If the opposing faction controls this outdoor copy, return later or use an eligible character for its faction counterpart.\n\n4. Check the achievement and mount collection. This is the single-rider vendor mount, not the Grand Black War Mammoth raid drop. Killing Vault bosses is unnecessary for this particular mammoth.",
        stepCount = 4,
        waypoints = {
            { mapID = 123, x = 0.517, y = 0.172, step = 2, label = "Outdoor Wintergrasp - friendly fortress quartermaster" },
            { mapID = 123, x = 0.517, y = 0.172, step = 3, label = "Dameron / Mukar - 15 Marks of Honor" },
        },
        sources = {
            "https://www.wowhead.com/achievement=2080#comments:id=1873763",
            "https://www.wowhead.com/item=44077#comments:id=5236050",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2080",
        sourceURL = "https://www.wowhead.com/achievement=2080#comments",
        difficultyReason = "Earn fifteen Marks of Honor, then buy and learn the Black War Mammoth from a friendly Wintergrasp quartermaster.",
        difficulty = "medium",
    },
    [2081] = {
        achievementId = 2081,
        name = "Grand Black War Mammoth",
        category = "Collections",
        sourceType = "Achievement",
        source = "Grand Black War Mammoth",
        acquisition = "Difficulty: Hard - Farm the Grand Black War Mammoth's rare Vault drop across weekly loot opportunities, then learn it.\n\n1. Travel to outdoor Wintergrasp when your faction controls the fortress. Set your legacy raid size outside and enter the Vault of Archavon portal at the back of the fortress (50.0, 11.9). The Epic Battleground queue leads to a separate battle instance.\n\n2. Kill and loot ALL FOUR bosses: Archavon, Emalon, Koralon and Toravon. Any of them can drop the reins, in either legacy raid size. You do not need a Hard Mode, timed achievement or special four-boss kill order.\n\n3. If Reins of the Grand Black War Mammoth drops, loot it and use the faction-appropriate item to learn the mount and check the achievement. The cheaper 15-Mark vendor Black War Mammoth is a separate item.\n\n4. If no reins drop, use another eligible character or return after the relevant weekly lockout. Check your Raid Info before trying another size; an already saved boss does not give another roll from resetting the instance.",
        stepCount = 4,
        waypoints = {
            { mapID = 123, x = 0.5, y = 0.11900000000000001, step = 1, label = "Vault of Archavon - OUTDOOR fortress portal" },
            { mapID = 156, x = 0.493, y = 0.168, step = 2, label = "Archavon - loot for mammoth chance" },
            { mapID = 156, x = 0.627, y = 0.5529999999999999, step = 2, label = "Emalon - loot for mammoth chance" },
            { mapID = 156, x = 0.363, y = 0.551, step = 2, label = "Koralon - loot for mammoth chance" },
            { mapID = 156, x = 0.627, y = 0.363, step = 2, label = "Toravon - loot for mammoth chance" },
        },
        tips = "This obtainable Feat of Strength was removed from Master of Wintergrasp's requirements because the drop is rare. Its old anniversary-event source is not presented as a permanent route.",
        sources = {
            "https://www.wowhead.com/achievement=2081#comments:id=633148",
            "https://www.wowhead.com/achievement=2081#comments:id=693651",
            "https://www.wowhead.com/item=44083#comments:id=626536",
            "https://www.wowhead.com/item=43959#comments:id=589210",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2081",
        sourceURL = "https://www.wowhead.com/achievement=2081#comments",
        difficultyReason = "Farm the Grand Black War Mammoth's rare Vault drop across weekly loot opportunities, then learn it.",
        difficulty = "hard",
    },
    [2082] = {
        achievementId = 2082,
        name = "Ice Mammoth",
        category = "Collections",
        sourceType = "Achievement",
        source = "Ice Mammoth",
        acquisition = "Difficulty: Medium - Unlock the Sons of Hodir and reach the named mammoth's required reputation before purchasing it.\n\n1. If the Sons of Hodir are hostile, start They Took Our Men! with Gretchen Fizzlespark in K3 (41.1, 86.1). Follow the Brunnhildar, bear, drake and Thorim introduction through Sibling Rivalry and Mending Fences. Enable Trivial Quests.\n\n2. During Mending Fences, loot Slag Covered Metal and complete The Refiner's Fire and A Spark of Hope. Follow the Thorim/Hodir yellow quests until Dun Niffelem is friendly and Lillehoff's reputation turn-ins/vendor are available.\n\n3. Raise Sons of Hodir to REVERED through unlocked dailies and batches of Relics of Ulduar turned in to Lillehoff (66.1, 61.4). You can buy relics; check your actual bar before purchasing a large surplus.\n\n4. Buy Reins of the Ice Mammoth from Lillehoff. The base price is 1,000 gold before discounts, and he offers the appropriate faction item. Revered normally makes it 850 gold; you do not need Exalted for the ordinary Ice Mammoth.\n\n5. Use the reins, confirm the achievement and check the mount collection. This is the single-rider mammoth; the larger Grand Ice Mammoth is a separate Exalted purchase.",
        stepCount = 5,
        waypoints = {
            { mapID = 120, x = 0.41100000000000003, y = 0.861, step = 1, label = "Gretchen - start Sons of Hodir unlock" },
            { mapID = 120, x = 0.6609999999999999, y = 0.614, step = 3, label = "Lillehoff - Relics of Ulduar / reputation" },
            { mapID = 120, x = 0.6609999999999999, y = 0.614, step = 4, label = "Lillehoff - buy Ice Mammoth" },
        },
        tips = "Do not plan around the removed guild Bartering discount or assume the ordinary and Grand mammoths share a reputation requirement.",
        sources = {
            "https://www.wowhead.com/achievement=2082#comments:id=506930",
            "https://www.wowhead.com/achievement=2082#comments:id=1356254",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2082",
        sourceURL = "https://www.wowhead.com/achievement=2082#comments",
        difficultyReason = "Unlock the Sons of Hodir and reach the named mammoth's required reputation before purchasing it.",
        difficulty = "medium",
    },
    [2083] = {
        achievementId = 2083,
        name = "Grand Ice Mammoth",
        category = "Collections",
        sourceType = "Achievement",
        source = "Grand Ice Mammoth",
        acquisition = "Difficulty: Medium - Unlock the Sons of Hodir and reach the named mammoth's required reputation before purchasing it.\n\n1. If the Sons of Hodir are hostile, start They Took Our Men! with Gretchen Fizzlespark in K3 (41.1, 86.1). Follow the Brunnhildar, bear, drake and Thorim introduction through Sibling Rivalry and Mending Fences. Enable Trivial Quests.\n\n2. During Mending Fences, loot Slag Covered Metal and complete The Refiner's Fire and A Spark of Hope. Follow the Thorim/Hodir yellow quests until Dun Niffelem is friendly and Lillehoff's reputation turn-ins/vendor are available.\n\n3. Raise Sons of Hodir to EXALTED through unlocked dailies and batches of Relics of Ulduar turned in to Lillehoff (66.1, 61.4). You can buy relics; check your actual bar before purchasing a large surplus.\n\n4. Buy Reins of the Grand Ice Mammoth from Lillehoff. The base price is 10,000 gold before discounts, and he offers the appropriate faction item. The required Exalted standing normally makes the price 8,000 gold.\n\n5. Use the reins, confirm the achievement and check the mount collection. This three-person mammoth has two party-passenger seats, with no repair/trade NPCs.",
        stepCount = 5,
        waypoints = {
