    [2084] = {
        achievementId = 2084,
        name = "Ring of the Kirin Tor",
        category = "Collections",
        sourceType = "Achievement",
        source = "Ring of the Kirin Tor",
        acquisition = "Difficulty: Easy - Buy and use the named gold-vendor item; no rare drop or reputation rank is required.\n\n1. Go to Harold Winston inside the Cartier & Co. jewelry shop in ORIGINAL Northrend Dalaran (around 39.4, 34.8). Bring 8,500 gold to cover an original ring's base cost; Kirin Tor reputation discounts lower the displayed price, normally to 6,800 at Exalted.\n\n2. Buy one ORIGINAL qualifying variant: Signet of the Kirin Tor (40585), Band of the Kirin Tor (40586), Loop of the Kirin Tor (44934) or Ring of the Kirin Tor (44935). You do not need a later Inscribed/Etched/Runed upgrade or the much more expensive Empowered ring for this Wrath achievement.\n\n3. Check achievement credit after the purchase. If the game has not recorded it, equip your qualifying original ring when level-eligible and check again. Keep it if you want its independent Northrend Dalaran teleport.\n\n4. If considering a refund, inspect THIS item's current refund text before equipping, using, enchanting or altering it. Comment reports span different rings and patches and conflict; do not assume a gold refund or retained achievement is guaranteed. The normal buy-and-keep route needs no refund trick.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 125,
                x = 0.39399999999999996,
                y = 0.348,
                step = 1,
                label = "Harold Winston - Cartier & Co. original rings",
            },
            {
                mapID = 125,
                x = 0.39399999999999996,
                y = 0.348,
                step = 2,
                label = "Choose an original 8,500g-base ring variant",
            },
        },
        tips = "A Legion Dalaran hearthstone or a teleport from another item does not satisfy ownership of a listed original Kirin Tor ring. The 250,000-gold Empowered-ring comment refers to a different item.",
        sources = {
            "https://www.wowhead.com/achievement=2084#comments:id=380655",
            "https://www.wowhead.com/achievement=2084#comments:id=1027848",
            "https://www.wowhead.com/achievement=2084#comments:id=3251737",
