    [2094] = {
        achievementId = 2094,
        name = "A Penny For Your Thoughts",
        category = "Professions",
        sourceType = "Achievement",
        source = "A Penny For Your Thoughts",
        acquisition = "Difficulty: Medium - Fish the required fountain coin checklist; duplicate catches extend the collection effort.\n\n1. Travel to the ORIGINAL Dalaran above Crystalsong Forest in Northrend. Find the small Eventide fountain beside Marcia Chase at 52.5, 66.2. Legion Dalaran's lookalike fountain has different junk coins and does not complete these lists.\n\n2. Learn Fishing, stand at the fountain and cast into its water. Loot every catch. Track the 22 copper named coins in the achievement checklist; repeated catches of a coin you already have do not fill missing names.\n\n3. When you catch a gold coin, right-click it to throw it back for the two-minute Lucky buff. Its achievement credit was already recorded when caught. Refresh near expiry rather than throwing several at once: the buff does not stack.\n\n4. Continue fishing and maintaining Lucky while any required coin is missing. You do not need to store all coins at once. There is no fixed cast total or time guarantee for the last coin.\n\n5. Check every named criterion in this coin tier. Keep fishing the same fountain for the other two metal lists if you also want The Coin Master and its reward.",
        stepCount = 5,
        waypoints = {
            { mapID = 125, x = 0.525, y = 0.662, step = 1, label = "Eventide fountain - Northrend coin achievements" },
            { mapID = 125, x = 0.525, y = 0.662, step = 3, label = "Throw back a gold coin for Lucky" },
        },
        tips = "This uses Northrend Dalaran (map 125). A particular old combined Fishing level is not required to cast. Lucky improves coin fishing; it cannot target a specific missing name.",
        sources = {
            "https://www.wowhead.com/achievement=1957#comments:id=444463",
            "https://www.wowhead.com/achievement=1957#comments:id=1618113",
            "https://www.wowhead.com/achievement=2095#comments:id=1410600",
            "https://www.wowhead.com/achievement=2096#comments:id=6053400",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2094",
        sourceURL = "https://www.wowhead.com/achievement=2094#comments",
        difficultyReason = "Fish the required fountain coin checklist; duplicate catches extend the collection effort.",
        difficulty = "medium",
    },
