    [2096] = {
        achievementId = 2096,
        name = "The Coin Master",
        category = "Professions",
        sourceType = "Achievement",
        source = "The Coin Master",
        acquisition = "Difficulty: Medium - Fish the required fountain coin checklist; duplicate catches extend the collection effort.\n\n1. Travel to the ORIGINAL Dalaran above Crystalsong Forest in Northrend. Find the small Eventide fountain beside Marcia Chase at 52.5, 66.2. Legion Dalaran's lookalike fountain has different junk coins and does not complete these lists.\n\n2. Learn Fishing, stand at the fountain and cast into its water. Loot every catch. Track the all 52 gold, silver and copper named coins in the achievement checklist; repeated catches of a coin you already have do not fill missing names.\n\n3. When you catch a gold coin, right-click it to throw it back for the two-minute Lucky buff. Its achievement credit was already recorded when caught. Refresh near expiry rather than throwing several at once: the buff does not stack.\n\n4. Continue fishing and maintaining Lucky while any required coin is missing. You do not need to store all coins at once. There is no fixed cast total or time guarantee for the last coin.\n\n5. Complete There's Gold In That There Fountain, A Penny For Your Thoughts and Silver in the City. Together these award The Coin Master; collect its Titanium Seal of Dalaran reward from the achievement mail.",
        stepCount = 5,
        waypoints = {
            { mapID = 125, x = 0.525, y = 0.662, step = 1, label = "Eventide fountain - Northrend coin achievements" },
