    [2097] = {
        achievementId = 2097,
        name = "Get to the Choppa!",
        category = "Collections",
        sourceType = "Achievement",
        source = "Get to the Choppa!",
        acquisition = "Difficulty: Medium - Buy the tradable crafted motorcycle or complete the Northrend Engineering recipe and material requirements.\n\n1. For the direct route, buy a completed Mekgineer's Chopper (Alliance) or Mechano-hog (Horde) from the Auction House or a crafter. The OWNER does not need Engineering. Use the finished mount item to learn it and check achievement credit; merely crafting one for sale or riding in a friend's sidecar is insufficient.\n\n2. For the crafting route, the crafter needs 75 Northrend Engineering and Exalted Alliance Vanguard (Alliance) or Horde Expedition (Horde), then buys and learns the matching schematic. The Winds of the North guide explains the default-reputation farm without a championing tabard.\n\n3. Supply twelve Titansteel Bars, forty Handfuls of Cobalt Bolts and two Arctic Fur. Compare material and finished-mount prices before committing to a craft; none of these quantities is a promise of an Auction House price.\n\n4. The qualified engineer buys the specialized parts from Roxi Ramrocket in K3, Storm Peaks (40.7, 84.8): one Salvaged Iron Golem Parts, eight Goblin-machined Pistons and one Elementium-plated Exhaust Pipe. Their base combined cost is 12,500 gold; a limited-stock part may require a later visit.\n\n5. Craft the faction's motorcycle at an anvil, trade it to its intended owner if necessary, and have that owner USE the finished item. Sending an unlearned motorcycle between characters is not a dependable achievement method. Keep the learned mount and invite a party passenger to use its sidecar.",
        stepCount = 5,
        waypoints = {
            {
                mapID = 120,
                x = 0.40700000000000003,
                y = 0.848,
                step = 4,
                label = "Roxi Ramrocket - qualified engineer's specialized parts",
            },
            { mapID = 120, x = 0.40700000000000003, y = 0.848, step = 5, label = "K3 - craft at an anvil" },
            {
                mapID = 114,
                x = 0.5760000000000001,
                y = 0.664,
                step = 2,
                label = "Alliance Vanguard - schematic quartermaster at Valiance Keep",
            },
            {
                mapID = 114,
                x = 0.414,
                y = 0.536,
                step = 2,
                label = "Horde Expedition - schematic quartermaster at Warsong Hold",
            },
        },
        tips = "An engineer can craft the tradeable motorcycle for another player. The intended owner must learn the finished mount; owning the schematic or components is insufficient.",
        sources = {
            "https://www.wowhead.com/achievement=2097#comments:id=418656",
            "https://www.wowhead.com/achievement=2097#comments:id=425353",
            "https://www.wowhead.com/achievement=2097#comments:id=745922",
            "https://www.wowhead.com/achievement=2097#comments:id=870177",
            "https://www.wowhead.com/npc=31247/roxi-ramrocket",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2097",
        sourceURL = "https://www.wowhead.com/achievement=2097#comments",
        difficultyReason = "Buy the tradable crafted motorcycle or complete the Northrend Engineering recipe and material requirements.",
        difficulty = "medium",
    },
    [2136] = {
        achievementId = 2136,
        name = "Glory of the Hero",
        category = "Raids",
        sourceType = "Achievement",
        source = "Glory of the Hero",
        acquisition = "Difficulty: Hard - Complete the Heroic dungeon challenge meta, including random prisoners, vehicle colors and controlled-damage mechanics.\n\n1. Set HEROIC and track the current checklist. Plan each instance's special objectives BEFORE killing its bosses. Start with ordinary fast-kill conditions, but stop damage wherever a guide requires living adds, a sacrifice, a vehicle color or a debuff.\n\n2. Schedule the constrained attempts early: Experienced Drake Rider needs three different drake-color kills, and Violet Hold's Lockdown depends on its random prisoners across visits. A saved Heroic boss normally needs the next daily reset for another attempt. Share The Love remains a separate obtainable five-player achievement, but it is no longer required by this meta.\n\n3. Prepare controlled low damage for The Incredible Hulk and the required Scourge Hulk sword hit. Gather zombies in the Culling's final alley while leaving Arthas waiting. For What the Eck?, obtain and keep Eck Residue before killing Gal'darah. Use those individual guides instead of clearing the whole dungeon indiscriminately.\n\n4. Work through the remaining listed achievements, checking their criteria after each boss. When the meta completes, collect and learn the Red Proto-Drake reward. Ulduar, Trial of the Champion and the Frozen Halls are not part of this original dungeon meta.",
        stepCount = 4,
        waypoints = {
            { mapID = 117, x = 0.573, y = 0.467, step = 3, label = "Utgarde Pinnacle - Scourge Hulk setup" },
            { mapID = 75, x = 0.569, y = 0.8240000000000001, step = 3, label = "Culling of Stratholme - Zombiefest alley" },
            { mapID = 121, x = 0.764, y = 0.213, step = 3, label = "Gundrak - Eck Residue before Gal'darah" },
            { mapID = 114, x = 0.28600000000000003, y = 0.275, step = 2, label = "The Oculus - three drake-color visits" },
            { mapID = 125, x = 0.665, y = 0.6779999999999999, step = 2, label = "Violet Hold - random prisoner checklist" },
        },
        tips = "Many high-level kills satisfy simple conditions, but several checklist items deliberately require waiting or preserving enemies. Read the linked encounter guide first.",
        sources = { "https://www.wowhead.com/achievement=2136#comments:id=6098328" },
        wowheadUrl = "https://www.wowhead.com/achievement=2136",
        sourceURL = "https://www.wowhead.com/achievement=2136#comments",
        difficultyReason = "Complete the Heroic dungeon challenge meta, including random prisoners, vehicle colors and controlled-damage mechanics.",
        difficulty = "hard",
    },
    [2137] = {
        achievementId = 2137,
        name = "Glory of the Raider (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Glory of the Raider (10 player)",
        acquisition = "Difficulty: Hard - Complete every surviving Naxxramas, Eye of Eternity and Obsidian Sanctum challenge in the selected size.\n\n1. Set Legacy Raid Size to 10 players and track the meta's CURRENT checklist. Its three raids are Northrend Naxxramas, Obsidian Sanctum and Eye of Eternity. The removed Immortal/Undying requirements are not necessary for the current meta.\n\n2. In Naxxramas, plan the special kills before clearing: preserve Faerlina's worshippers, leave Loatheb's spores alive, synchronize the Four Horsemen after their platform split, and gather Kel'Thuzad's abominations before phase 2. Also finish the speed, resistance, polarity and small-group criteria shown in your checklist.\n\n3. In Obsidian Sanctum, use the three-drake setup for The Twilight Zone and avoid Lava Strike. In Eye of Eternity, finish the timed/small-group kill and personally kill a Scion from a hover disc. Use those individual achievement guides for the mechanics rather than treating every boss as an ordinary clear.\n\n4. Return in later lockouts for incompatible or missed criteria. Completing this meta still awards achievement credit, but its original Plagued/Black Proto-Drake reward was removed; do not farm the meta expecting those mounts.",
        stepCount = 4,
        waypoints = {
            { mapID = 115, x = 0.8740000000000001, y = 0.51, step = 2, label = "Naxxramas - encounter challenges" },
            { mapID = 115, x = 0.598, y = 0.546, step = 3, label = "Obsidian Sanctum - three drakes and Lava Strike" },
            { mapID = 114, x = 0.275, y = 0.266, step = 3, label = "Eye of Eternity - timed kill and hover disc" },
        },
        sources = {
            "https://www.wowhead.com/achievement=2137#comments:id=624222",
            "https://www.wowhead.com/achievement=2137#comments:id=676570",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2137",
        sourceURL = "https://www.wowhead.com/achievement=2137#comments",
        difficultyReason = "Complete every surviving Naxxramas, Eye of Eternity and Obsidian Sanctum challenge in the selected size.",
        difficulty = "hard",
    },
