    [2139] = {
        achievementId = 2139,
        name = "The Safety Dance (25 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "The Safety Dance (25 player)",
        acquisition = "Difficulty: Easy - A high-level fast kill or solo small-group clear satisfies the surviving Naxxramas encounter condition.\n\n1. Outside Naxxramas, set Legacy Raid Size to 25 players. Fly to the floating necropolis over eastern Dragonblight and enter the portal underneath it (87.4, 51.0). This is the Northrend raid, not the removed Eastern Plaguelands version.\n\n2. Take the Plague Quarter, defeat Noth and reach Heigan. Everyone in the group must remain alive for this encounter.\n\n3. At high level, move onto Heigan's platform and kill him immediately. No dance phase is mandatory. If the fight lasts, move through the safe floor sections during eruptions and return to attacking; any player death fails the attempt.",
        stepCount = 3,
        waypoints = {
            {
                mapID = 115,
                x = 0.8740000000000001,
                y = 0.51,
                step = 1,
                label = "Naxxramas - portal under the floating necropolis",
