        acquisition = "Difficulty: Easy - A high-level fast kill or solo small-group clear satisfies the surviving Naxxramas encounter condition.\n\n1. Outside Naxxramas, set Legacy Raid Size to 10 players. Fly to the floating necropolis over eastern Dragonblight and enter the portal underneath it (87.4, 51.0). This is the Northrend raid, not the removed Eastern Plaguelands version.\n\n2. Use the central portal to Frostwyrm Lair and reach Sapphiron. Have every participant remove old Frost Resistance equipment, resistance potions and resistance buffs before pulling.\n\n3. Defeat Sapphiron without anyone's Frost Resistance exceeding 100 during the encounter. Ordinary modern gear and an immediate high-level kill are sufficient; do not equip an old resistance set because an outdated level-80 guide recommends it.",
