        acquisition = "Difficulty: Medium - Use a Nexus Lord's hover disc and personally land a direct killing blow on a flying Scion.\n\n1. Set Legacy Raid Size to 10 players outside the instance. Fly to Coldarra in Borean Tundra and enter the EYE OF ETERNITY on the highest ring of the Nexus tower. The Nexus and Oculus portals are different instances.\n\n2. Use the central focusing device to start Malygos. Damage him to trigger phase 2. He can remain at 1 health until the scripted transitions finish; this is not a reason to reset.\n\n3. In phase 2, leave at least one Scion of Eternity alive. Kill a Nexus Lord that descends toward the floor, click its dropped hover disc, and FLY OFF the floor before attacking your target. A disc from a Nexus Lord is the reliable rideable one.\n\n4. While mounted on that disc, personally land a DIRECT killing blow on a Scion of Eternity. A pet or lingering damage-over-time effect can deny credit. The achievement can award immediately; killing Malygos is not required for this particular criterion.",
        stepCount = 4,
        waypoints = { { mapID = 114, x = 0.275, y = 0.266, step = 1, label = "Eye of Eternity - highest Nexus portal" } },
        tips = "Credit is personal: being on a disc while someone else kills the Scion is insufficient. Rise above the floor before dealing the killing blow.",
        sources = {
            "https://www.wowhead.com/achievement=2148#comments:id=1712621",
            "https://www.wowhead.com/achievement=2148#comments:id=2268751",
            "https://www.wowhead.com/achievement=2148#comments:id=5378653",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=2148",
        sourceURL = "https://www.wowhead.com/achievement=2148#comments",
        difficultyReason = "Use a Nexus Lord's hover disc and personally land a direct killing blow on a flying Scion.",
        difficulty = "medium",
    },
