    [2150] = {
        achievementId = 2150,
        name = "Split Personality",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Split Personality",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Heroic and enter the Nexus at Coldarra's lowest portal. Follow the left branch to Grand Magus Telestra.\n\n2. At high level, kill Telestra immediately with a direct attack. Later Retail comments and the fast-kill thread's replies confirm that killing her before any split awards the achievement; two splits are not mandatory.\n\n3. If she does split, weaken all three images, then kill them within FIVE seconds of the first image dying. Interrupt or wait out the Frost image's Blizzard before starting that window. Repeat for any additional split, then finish Telestra.",
        stepCount = 3,
        waypoints = {
            { mapID = 114, x = 0.275, y = 0.267, step = 1, label = "The Nexus - lowest portal" },
            {
                mapID = 129,
