    [2151] = {
        achievementId = 2151,
        name = "Consumption Junction",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Consumption Junction",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Heroic and enter Drak'Tharon Keep. Clear the approach to Trollgore at the first stair chamber and prepare direct single-target damage.\n\n2. At high level, kill Trollgore immediately before his Consume buff reaches TEN stacks. Later Retail comments confirm a one-hit kill; waiting for the first Consume is unnecessary.\n\n3. If the fight lasts, remember that Consume gains stacks from multiple eligible targets in his line of sight, including approaching enemies. Pull him beside the stair pillar so the group can break line of sight before a Consume, and kill incoming trolls before they join him. Resume damage after the cast and finish while he remains below ten stacks.",
        stepCount = 3,
        waypoints = {
            { mapID = 121, x = 0.28600000000000003, y = 0.8690000000000001, step = 1, label = "Drak'Tharon Keep - entrance" },
            {
                mapID = 160,
                x = 0.565,
                y = 0.182,
                step = 2,
                label = "Trollgore - kill below ten Consume stacks",
                mapName = "Drak'Tharon Keep - The Vestibules",
