    [2152] = {
        achievementId = 2152,
        name = "Share The Love",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Share The Love",
        acquisition = "Difficulty: Hard - Bring five eligible players and keep Gal'darah alive until every player has been impaled.\n\n1. Bring FIVE distinct player characters to Heroic Gundrak, including two characters able to exchange the boss's attention without heavy damage. Clear through the three altars and gather inside Gal'darah's arena before pulling.\n\n2. Dismiss pets, remove damage procs and use a low-damage attack to bring Gal'darah below roughly 50% so he transforms into a rhino. Stop damage; an accidental high-level hit can kill him before five impales.\n\n3. Let each non-tank be impaled. At high level, use /sit with your back toward the boss so the attempt actually lands instead of being avoided. Record the Impaling Charge announcements; merely being charged toward is not proof of an impale.\n\n4. After the second tank has been impaled, have that character taunt so the original tank can receive an impale too. Wait through additional transformations if targets repeat.\n\n5. Only after FIVE DIFFERENT characters have been impaled, kill Gal'darah. Credit is awarded on his death. This achievement is separate from Glory of the Hero and is no longer required for that mount meta.",
        stepCount = 5,
        waypoints = {
            { mapID = 121, x = 0.764, y = 0.213, step = 1, label = "Gundrak - northwest entrance" },
            { mapID = 153, x = 0.465, y = 0.27, step = 2, label = "Gal'darah - weaken, then stop damage", mapName = "Gundrak" },
            {
                mapID = 153,
                x = 0.465,
                y = 0.27,
                step = 3,
                label = "Gal'darah - /sit for five distinct impales",
                mapName = "Gundrak",
