            { mapID = 153, x = 0.465, y = 0.27, step = 4, label = "Gal'darah - exchange tanks", mapName = "Gundrak" },
            {
                mapID = 153,
                x = 0.465,
                y = 0.27,
                step = 5,
                label = "Gal'darah - kill after all five impales",
                mapName = "Gundrak",
            },
        },
        tips = "The standard five-player route avoids the fragile old disconnect-and-alt-swapping method. Recent replies confirm /sit at high level; it does not replace the five-character requirement.",
        sources = {
            "https://www.wowhead.com/achievement=2152#comments:id=590587",
