    [2153] = {
        achievementId = 2153,
        name = "A Void Dance",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "A Void Dance",
        acquisition = "Difficulty: Medium - Obtain the required randomly selected Violet Hold boss, then preserve its prohibited adds or globule condition.\n\n1. Enter the ORIGINAL Violet Hold in Northrend Dalaran on Heroic. Speak to Sinclari, clear the portal waves and watch which prisoner is released at wave 6. You need Zuramat the Obliterator; another prisoner cannot award this achievement.\n\n2. If the first prisoner is wrong, leave BEFORE killing that boss and reset from outside for another random selection, provided you have not been saved by a boss kill. Later Retail comments confirm this reroll route. Respect the hourly instance-entry limit; a saved Heroic run is not a fresh reroll.\n\n3. When Zuramat becomes attackable, kill him with direct SINGLE-TARGET damage. Leave every Void Sentry alive. If Void Shift lets you see or attack the sentries, keep targeting Zuramat; pet cleaves and random damage effects can otherwise ruin the attempt.",
        stepCount = 3,
        waypoints = {
            { mapID = 125, x = 0.665, y = 0.6779999999999999, step = 1, label = "Original Violet Hold - entrance" },
            {
                mapID = 168,
                x = 0.27190000000000003,
                y = 0.3361,
                step = 3,
                label = "Zuramat's cell - must be selected by saboteur",
                mapName = "The Violet Hold (Northrend)",
            },
        },
        tips = "Begin the random-prisoner attempts early if working on Glory of the Hero. No Void Sentry kill is required to make Zuramat vulnerable.",
        sources = {
            "https://www.wowhead.com/achievement=2153#comments:id=485222",
            "https://www.wowhead.com/achievement=2153#comments:id=1689700",
            "https://www.wowhead.com/achievement=2153#comments:id=3239923",
