        wowheadUrl = "https://www.wowhead.com/achievement=2153",
        sourceURL = "https://www.wowhead.com/achievement=2153#comments",
        difficultyReason = "Obtain the required randomly selected Violet Hold boss, then preserve its prohibited adds or globule condition.",
        difficulty = "medium",
    },
    [2154] = {
        achievementId = 2154,
        name = "Brann Spankin' New",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Brann Spankin' New",
        acquisition = "Difficulty: Medium - Hold damage for the sacrifice or defense event and preserve the exact encounter condition.\n\n1. Set Heroic and enter Halls of Stone in The Storm Peaks. Find Brann Bronzebeard, start his escort and follow him into the Tribunal of Ages. Clear the approach before starting the defense dialogue.\n\n2. Stand at the TOP of the entrance stairs, between the spawning enemies and Brann. Kill each wave immediately, including ranged casters and the larger late-event enemies. A slow, stun or ranged attack helps catch anything that slips past; a harmless ground effect alone does not guarantee aggro.\n\n3. Keep defending through the full event while avoiding the moving beam and ground hazards. Brann must take ZERO damage, not merely survive. Stay for the final dialogue and achievement credit; killing one wave and running ahead does not finish the event.",
        stepCount = 3,
        waypoints = {
            { mapID = 120, x = 0.401, y = 0.26899999999999996, step = 1, label = "Halls of Stone - entrance" },
            {
                mapID = 140,
                x = 0.8490000000000001,
                y = 0.7609999999999999,
                step = 2,
                label = "Tribunal of Ages - intercept waves at stairs",
                mapName = "Halls of Stone",
