    [2155] = {
        achievementId = 2155,
        name = "Abuse the Ooze",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Abuse the Ooze",
        acquisition = "Difficulty: Medium - Hold Sjonnir alive while combining oozes and killing five Iron Sludges without accidental boss damage.\n\n1. Set Heroic, complete Brann's Tribunal event in Halls of Stone and let him open Sjonnir's door. BEFORE combat, dismiss pets, remove damage procs and prepare a very low-damage setup. Whole-Body Shrinka' plus unequipped gear and a spec without passive damage is a later Retail suggestion.\n\n2. Carefully bring Sjonnir into the 26-49% health range, then STOP all damage to him. Above 50% the required oozes do not spawn; below roughly 25%, friendly Earthen arrive and can kill the boss before you finish.\n\n3. Leave the small MALFORMED OOZES alive. Let them reach the middle and combine into larger IRON SLUDGES; the small oozes themselves do not count. Wait for the combination animation and check the target name before attacking.\n\n4. Kill FIVE Iron Sludges with single-target attacks that cannot cleave Sjonnir or destroy the next combining oozes. Count actual Sludge deaths, not the number of small oozes spawned.\n\n5. Once five Sludges are dead, finish Sjonnir. If even your reduced-damage attacks kill him outright, use a lower-level eligible alt for another attempt rather than repeating the same lethal hit after each daily reset.",
        stepCount = 5,
        waypoints = {
            { mapID = 120, x = 0.401, y = 0.26899999999999996, step = 1, label = "Halls of Stone - entrance" },
            {
                mapID = 140,
                x = 0.8490000000000001,
                y = 0.7609999999999999,
                step = 1,
                label = "Tribunal of Ages - finish Brann's event",
                mapName = "Halls of Stone",
            },
            {
                mapID = 140,
                x = 0.49700000000000005,
                y = 0.13699999999999998,
                step = 2,
                label = "Sjonnir - stop at 26-49% health",
                mapName = "Halls of Stone",
            },
            {
                mapID = 140,
                x = 0.49700000000000005,
                y = 0.13699999999999998,
                step = 3,
                label = "Sjonnir's platform - let Malformed Oozes combine",
                mapName = "Halls of Stone",
            },
            {
                mapID = 140,
                x = 0.49700000000000005,
                y = 0.13699999999999998,
                step = 4,
                label = "Kill five IRON SLUDGES before Sjonnir",
                mapName = "Halls of Stone",
            },
        },
        tips = "Shrinka' must be activated before combat and does not guarantee that every class's attack will be weak enough. Later replies confirm both successful reduced-damage setups and remaining one-shot problems.",
        sources = {
            "https://www.wowhead.com/achievement=2155#comments:id=538017",
            "https://www.wowhead.com/achievement=2155#comments:id=1836375",
            "https://www.wowhead.com/achievement=2155#comments:id=2344296",
