    [2156] = {
        achievementId = 2156,
        name = "My Girl Loves to Skadi All the Time",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "My Girl Loves to Skadi All the Time",
        acquisition = "Difficulty: Medium - Collect the harpoons and execute Skadi's required gauntlet timing or single-pass objective.\n\n1. Set Heroic and clear Utgarde Pinnacle through Svala and Gortok. Start Skadi's gauntlet and head toward the harpoon-launcher end while clearing the enemies in your way.\n\n2. Kill Ymirjar Harpooners and LOOT THREE Harpoons. Keep them until all three are ready; firing a single early shot and waiting for another pass fails the full-health-to-dead-in-one-pass objective.\n\n3. Stand by the launchers and wait until Grauf is in range. Click the launchers in quick succession to fire all THREE shots during that SAME pass. One person can do it; alternate launchers if a gun's cooldown prevents another immediate click. The guns are clicked directly, with no aiming or vehicle action bar.\n\n4. Once Grauf is down, kill Skadi on foot and check the achievement. The successful pass does not have to be Grauf's first pass of the encounter. Old instructions asking for five or six shots predate the reduction to three.",
        stepCount = 4,
        waypoints = {
            { mapID = 117, x = 0.573, y = 0.467, step = 1, label = "Utgarde Pinnacle - upper entrance" },
            {
                mapID = 137,
                x = 0.606,
                y = 0.688,
                step = 1,
                label = "Gortok - finish stasis event before gauntlet",
                mapName = "Utgarde Pinnacle - Upper Pinnacle",
