                step = 3,
                label = "Skadi gauntlet - three launcher clicks in one pass",
                mapName = "Utgarde Pinnacle - Upper Pinnacle",
            },
        },
        tips = "Keep a free bag slot if launcher clicks appear to do nothing. Finishing the entire gauntlet within three minutes can also award Lodi Dodi We Loves the Skadi.",
