    [2157] = {
        achievementId = 2157,
        name = "King's Bane",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "King's Bane",
        acquisition = "Difficulty: Easy - A high-level direct kill satisfies the condition; avoid prohibited adds, dispels or transformations.\n\n1. Set Heroic and clear Utgarde Pinnacle through Svala, Gortok and Skadi. Continue to King Ymiron's final room.\n\n2. At high level, kill Ymiron quickly before he can cast Bane. Skipping the buff with sufficient damage satisfies the achievement.\n\n3. If Bane is cast, EVERYONE must stop attacking until the buff is removed or expires. Stop auto-attacks, control pets, and avoid lingering or automatic damage. The requirement is that Bane never TRIGGERS, not that he never casts it. Resume damage only after the buff disappears, then defeat him.",
        stepCount = 3,
        waypoints = {
            { mapID = 117, x = 0.573, y = 0.467, step = 1, label = "Utgarde Pinnacle - upper entrance" },
