    [2177] = {
        achievementId = 2177,
        name = "And They Would All Go Down Together (25 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "And They Would All Go Down Together (25 player)",
        acquisition = "Difficulty: Medium - Wait for the Four Horsemen to leave their platforms, then kill all four within fifteen seconds.\n\n1. Outside Naxxramas, set Legacy Raid Size to 25 players. Fly to the floating necropolis over eastern Dragonblight and enter the portal underneath it (87.4, 51.0). This is the Northrend raid, not the removed Eastern Plaguelands version.\n\n2. Clear Razuvious and Gothik in the Military Quarter. Walk up to the Four Horsemen WITHOUT damaging them and wait until they leave the starting platform. Killing one on that platform can reset the encounter without valid credit.\n\n3. Collect Thane Korth'azz and Baron Rivendare, the two melee horsemen that follow you. Bring them to Lady Blaumeux in the far left corner or Sir Zeliek in the far right corner.\n\n4. Kill the two followers and that stationary horseman together. Immediately run across the BACK of the room and kill the last stationary horseman. All FOUR must die within 15 seconds of the FIRST death, not 15 seconds between each pair.",
