    [2178] = {
        achievementId = 2178,
        name = "Shocking! (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Shocking! (10 player)",
        acquisition = "Difficulty: Easy - A high-level fast kill or solo small-group clear satisfies the surviving Naxxramas encounter condition.\n\n1. Outside Naxxramas, set Legacy Raid Size to 10 players. Fly to the floating necropolis over eastern Dragonblight and enter the portal underneath it (87.4, 51.0). This is the Northrend raid, not the removed Eastern Plaguelands version.\n\n2. Clear the Construct Quarter to Stalagg and Feugen. Pull them without killing one prematurely, bring them together and kill both close together in time, then jump onto Thaddius's platform.\n\n3. Solo, kill Thaddius directly. In a group, keep everyone more than 10 yards apart so opposite charges cannot damage another player. Avoid pets or movement that brings players together during Polarity Shift.\n\n4. Finish Thaddius with no polarity damage to another player. Later Retail comments confirm that a kill before the first Polarity Shift can count; the old forced-wait instructions are unnecessary.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 115,
                x = 0.8740000000000001,
