    [2184] = {
        achievementId = 2184,
        name = "Just Can't Get Enough (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Just Can't Get Enough (10 player)",
        acquisition = "Difficulty: Medium - Gather at least eighteen abominations and keep them alive until Kel'Thuzad's second phase before killing them.\n\n1. Outside Naxxramas, set Legacy Raid Size to 10 players. Fly to the floating necropolis over eastern Dragonblight and enter the portal underneath it (87.4, 51.0). This is the Northrend raid, not the removed Eastern Plaguelands version.\n\n2. Use the central portal to Frostwyrm Lair, kill Sapphiron and enter Kel'Thuzad's chamber. Prepare a ranged non-cleaving pull and remove retaliation damage or pets that could kill adds early.\n\n3. Start the event by entering the GREEN CENTRAL CIRCLE. Stay in or beside it while pulling the abomination packs from the surrounding alcoves. Do not run around the room: leaving the circle too long can reset the encounter.\n\n4. Bring at least 18 Unstoppable Abominations into the central chamber. There are 21 around the room if all packs are collected. Keep the abominations alive until Kel'Thuzad becomes active in phase 2; kill other approaching enemies as needed.\n\n5. After phase 2 begins, kill at least 18 gathered abominations INSIDE the chamber, then kill Kel'Thuzad. Check the achievement before leaving the instance.",
        stepCount = 5,
        waypoints = {
            {
                mapID = 115,
                x = 0.8740000000000001,
                y = 0.51,
                step = 1,
                label = "Naxxramas - portal under the floating necropolis",
            },
            { mapID = 167, x = 0.565, y = 0.675, step = 2, label = "Sapphiron", mapName = "Naxxramas - Upper Necropolis" },
            { mapID = 167, x = 0.365, y = 0.223, step = 2, label = "Kel'Thuzad", mapName = "Naxxramas - Upper Necropolis" },
