    [2199] = {
        achievementId = 2199,
        name = "Wintergrasp Ranger",
        category = "PvP",
        sourceType = "Achievement",
        source = "Wintergrasp Ranger",
        acquisition = "Difficulty: Hard - Earn ten player kills in each of ten named Wintergrasp areas, including locations with little regular fighting.\n\n1. Track the TEN area counters. You need ten player kills credited in EACH area, across battles. NPC kills and destroying a cannon do not substitute. The Epic Battleground is the best place to find active players; the outdoor copy can also credit kills.\n\n2. Fight within Wintergrasp Fortress, then at the middle workshops: The Broken Temple and The Sunken Ring. Watch the subzone name above the minimap and the achievement counter; standing beside an area boundary may credit a neighboring zone.\n\n3. Work through the southern objectives: Shadowsight Tower, Westspark Workshop, Winter's Edge Tower, Eastspark Workshop and Flamewatch Tower. Join fights while enemy players have a reason to attack or defend these objectives.\n\n4. Finish The Chilled Quagmire in the northwest and The Cauldron of Flames in the far southeast (84.4, 72.4). The Cauldron often sees little ordinary battleground traffic, so plan that area deliberately rather than expecting it to finish with fortress kills.\n\n5. For quiet missing areas, an opposite-faction friend can meet you in the OUTDOOR zone for the relevant PvP kills; comment reports allow these outside an active battle. Make sure both are in the same outdoor phase and the kills credit the intended subzone. Check the fortress separately in the instanced battle if outdoor fortress kills fail to advance it.\n\n6. Review all ten x/10 counters, not just the total number of kills in Wintergrasp. Glacial Falls was removed from the criterion list and is not an eleventh requirement.",
        stepCount = 6,
        waypoints = {
            {
                mapID = 1334,
                x = 0.493,
                y = 0.21100000000000002,
                step = 2,
                label = "Wintergrasp Fortress - 10 players",
