    [2256] = {
        achievementId = 2256,
        name = "Northern Exposure",
        category = "Exploration",
        sourceType = "Achievement",
        source = "One listed Northrend rare creature",
        acquisition = "Difficulty: Medium - Search known Northrend spawn areas and defeat one eligible rare; respawn timing varies.\n\n1. Track Northern Exposure. You need ONE of the 23 rares on its checklist; an unrelated silver-dragon mob or Time-Lost Proto-Drake does not substitute.\n\n2. For a compact first search, circle Coldarra in Borean Tundra for Old Crystalbark, then check the eastern snowy Death's Stand region for Icehorn. The map pins are search areas, not guaranteed spawns.\n\n3. If both are absent, try Seething Hate at the three fallen, slime-filled tree trunks in western Grizzly Hills, or use Frostbitten's full eight-zone route for another listed rare. Return later when a region is empty.\n\n4. Tag and kill a listed rare while nearby, loot if desired and check the achievement. You do not need to collect every rare's blue item or finish all 23; that is Frostbitten.",
        stepCount = 4,
        waypoints = {
            { mapID = 114, x = 0.222, y = 0.33799999999999997, step = 2, label = "Old Crystalbark - Coldarra search" },
