    [2257] = {
        achievementId = 2257,
        name = "Frostbitten",
        category = "Exploration",
        sourceType = "Achievement",
        source = "23 Northrend rare creatures",
        acquisition = "Difficulty: Hard - Find every required Northrend rare across contested spawns and long, unpredictable respawn timers.\n\n1. Track Frostbitten and mark the rares already credited. You need ALL 23 named creatures across eight zones. Visit only missing ones; the map dropdown groups the search points by zone and their pin numbers match these steps.\n\n2. Find and kill Old Crystalbark: circle Coldarra and the Nexus base. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n3. Find and kill Fumblub Gearwind: look UP for the flying gnome helicopter over the Geyser Fields. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n4. Find and kill Icehorn: search the snowy eastern Death's Stand/En'kilah region for an icy rhino. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n5. Find and kill Crazed Indu'le Survivor: search the western fields around Stars' Rest for the wandering Tuskarr. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n6. Find and kill Scarlet Highlord Daion: check ALL three separate Scarlet regions: Scarlet Point, the camp north of Naxxramas and New Hearthglen. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n7. Find and kill Tukemuth: sweep the central Dragon Wastes for a large pale mammoth. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n8. Find and kill Grocklar: check the western giant's patrols west of Granite Springs and south of Conquest Hold. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n9. Find and kill Seething Hate: inspect the THREE fallen/slime-filled tree trunks rather than just flying over the forest. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n10. Find and kill Syreian the Bonecarver: search the eastern/northeastern giant fields southeast of Westfall Brigade for the Vrykul ranger. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n11. Find and kill King Ping: follow the southwest coast and islands around Kamagua/Scalawag for the large penguin. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n12. Find and kill Perobas the Bloodthirster: check the northern lakes and Fort Wildervar region for the worgen. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n13. Find and kill Vigdis the War Maiden: search east of Nifflevar for the Vrykul on a ground-patrolling proto-drake; do not search the high-altitude flight paths. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n14. Find and kill Griegen: sweep the southwest around Zeramas, Thrym's End and the nearby fields. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n15. Find and kill Zul'drak Sentinel: follow the southwest road and the north/south road around the Argent Stand for the glowing stone giant. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n16. Find and kill Terror Spinner: check the northern/eastern temple terraces for the bone spider. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n17. Find and kill Dirkee: check the separate Engine of the Makers, Grom'arsh and eastern Thunderfall regions for the mechanical gnome. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n18. Find and kill Vyragosa: search the SKY along the southwest/central flight paths. This blue dragon shares the Time-Lost Proto-Drake spawn system, but Time-Lost itself is not a Frostbitten criterion. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n19. Find and kill Hildana Deathstealer: check both Jotunheim/Valhalas and the separate Ymirheim area for the flying Val'kyr. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n20. Find and kill High Thane Jorfus: check THREE disconnected regions: Fleshwerks, Court of Bones and Sindragosa's Fall. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n21. Find and kill Putridus the Ancient: follow the huge flesh giant's long central patrol between the gates; look beyond the immediate pin if targeting finds him. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n22. Find and kill Aotona: search the central/southern jungle around Rainspeaker and Wildgrowth Mangal for the blue parrot. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n23. Find and kill King Krush: check the northwest, central pillar area and southern basin for the green devilsaur. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n24. Find and kill Loque'nahak: visit the spirit beast's widely separated spawn areas around the entire basin, not just one camp. The map shows multiple search points for this step; patrol between them and check nearby terrain/altitude. Confirm kill credit in the checklist.\n\n25. If a rare is absent, return later or check another eligible phase with a friend who is physically there. There is no guaranteed server-restart spawn or universal respawn timer. Old claims that only one or two rares can exist in a zone at once are contradicted by later reports.\n\n26. For Aotona, King Krush and Loque'nahak, do not rely on taming alone for achievement credit: Retail reports conflict, including a failed tame in September 2026. Check your criterion immediately and use a qualifying kill if still missing. A summoned hunter pet is not the wild rare.",
        stepCount = 26,
