    research = {
        notes = {
            ["Data/Expansions/WrathOfTheLichKing/AchievementExplorationGuides.lua"] = "-- Named Retail discovery circuits, manually ordered from the exploration\n-- comment routes and corrections. Coordinates use current zone UiMapIDs.\n-- Each point is a representative spawn/patrol search location, not a promise\n-- that the rare stands there. Separate regions for the same rare are retained.",
            ["Data/Expansions/WrathOfTheLichKing/AchievementGuides.lua"] = "-- English Retail routes, manually reconciled with Wowhead comments/replies.\n-- Retired achievement IDs are excluded by the expansion catalogue.\n-- Neutral Dungeon Finder guides live in General.\n-- Both Normal and Heroic comment lists were read separately. Most contain\n-- no numbered acquisition guide. These routes combine their useful details\n-- with the named criteria and boss locations, rather than old level/gear advice.\n-- Interior coordinates: each named NPC's Retail g_mapperData; floor identities:\n-- https://wago.tools/db2/UiMap/csv and /db2/UiMapGroupMember/csv.\n-- Ahn'kahet's room pins use Retail /db2/JournalEncounter/csv (UiMap 132).\n-- A qualifying numbered profit-ending comment (no replies). Its high-level\n-- direct-kill route remains useful; the old level-100 health figures do not.\n-- The profit-ending Nadox comment describes separating the guardian from\n-- the boss. Later comments allow the simpler high-level kill before it spawns.\n-- The old profit guide uses Divine Intervention, a removed ability. Retain\n-- the timed objective, but use the later Retail direct-kill corrections.\n-- The qualifying profit comment's five-player tank swap is retained. Current\n-- corrections add the health threshold and /sit for high-level dodge chance.\n-- The four faction/difficulty pages each have separate comment lists. All\n-- five enemy champions AND both Argent bosses require more than one visit.\n-- Two old Pit of Saron mechanic achievements were retired in 12.0.1.\n-- Normal/Heroic clear achievements remain; temporary seasonal credit issues\n-- do not establish permanent retirement. Retail review: 2026-11-04.\n-- https://www.curseforge.com/wow/addons/krowi-achievement-filter/files/9058137\n-- https://eu.forums.blizzard.com/en/wow/t/pit-of-saron-achievement-bugged/613785/7\n-- The latest Retail comment confirms ordinary fast wave kills in Midnight;\n-- the old 2024 stuck-ending reports and hand-timed workaround are not the route.\n-- Current correction: fragments are not reliably rootable/slowable. The\n-- grate route is confirmed in October 2026 replies. Coordinates are from\n-- replies 1793445 and 1812853 to the detailed Hunter guide, not guessed pins.\n-- The two Azjol-Nerub pages below were read in full: 246 parent comments\n-- for Watch Him Die and 93 for Hadronox Denied, with no qualifying profit\n-- list. Modern direct-kill reports replace obsolete ledge/racer setups.\n-- No qualifying numbered profit list was found on these six pages.\n-- The full parent-comment lists and the selected modern guide replies\n-- were reviewed before writing these Retail routes.\n-- Emerald Void: all 66 parent comments were read; no qualifying profit\n-- list was present. Later Retail vehicle reports support the Ruby route\n-- without importing the old five-player Amber rotation or drake buffs.\n-- All four Halion pages were read. The 25-player Heroic numbered profit\n-- guide has three replies: they confirm the slow phase transition matters,\n-- while returning through the second portal is optional once phase 3 starts.",
            ["Data/Expansions/WrathOfTheLichKing/AchievementOwnershipGuides.lua"] = "-- Ownership achievements: retain usable vendor/quest details from the mount\n-- guides and correct achievement comments that still quote retired currencies.",
            ["Data/Expansions/WrathOfTheLichKing/AchievementProfessionGuides.lua"] = "-- Retail profession and fishing achievements, curated from the individual\n-- achievement comments and their corrections; old First Aid skill is not used.",
            ["Data/Expansions/WrathOfTheLichKing/AchievementPvPGuides.lua"] = "-- Retail objectives and comment corrections. Outdoor Wintergrasp (123) and\n-- its Epic Battleground copy (1334) share bounds, but remain separate maps.\n-- Approximate objective AREA centers read from the current Isle map artwork.\n-- These are not exact flag-click/vehicle-spawn pixels. Docks is WEST, Hangar EAST.\n-- Final Wrath metadata: this module loads after all other achievement guides.\n-- Retail availability/difficulty review, 2026-11-04. Rate acquisition effort,\n-- including prerequisites, randomness, resets and other players. Existing\n-- ratings (including the two copied mount guides) are preserved.\n-- Surviving Glory of the Raider achievements do not award the retired mounts.\n-- Ultimate Triage remains available through Tailoring. Herald is obtainable\n-- with its level/equipment restrictions. Pit of Saron's two retired mechanic\n-- achievements are excluded; its ordinary clear achievements remain.\n-- https://www.wowhead.com/achievement=141/ultimate-triage\n-- https://www.wowhead.com/achievement=3316/herald-of-the-titans\n-- https://warcraft.wiki.gg/wiki/Glory_of_the_Raider_(10_player)\n-- https://www.curseforge.com/wow/addons/krowi-achievement-filter/files/9058137\n-- https://eu.forums.blizzard.com/en/wow/t/pit-of-saron-achievement-bugged/613785/7\n-- Individual guide source/comment receipts above and in the other Wrath\n-- modules document the retained encounter, profession, quest and PvP routes.\n-- Exploration and outdoor quests.\n-- Professions, fishing and reputation.\n-- Tournament ranks and ownership achievements.\n-- Ordinary dungeons and their encounter challenges.\n-- Legacy raids: rate surviving mechanics using high-level Retail behavior.\n-- PvP: ordinary victories and finite objective checklists remain available;\n-- season-limited rewards were already excluded by the achievement catalogue.\n-- Clone shared detail groups so every retained ID keeps its own rating and\n-- route. Consumers resolving raw catalogue details see the same metadata as\n-- the walkthrough lookup; unrelated expansion data is left untouched.",
            ["Data/Expansions/WrathOfTheLichKing/AchievementRaidGuides.lua"] = "-- Retail raid walkthroughs. The old Ulduar size-specific IDs are retired;\n-- Val'anyr and Herald of the Titans remain separate, obtainable achievements.\n-- Retail boss mapper floors 1-6 match UiMaps 162-167, respectively.\n-- NPC coordinates below come from each boss's Retail g_mapperData. Its\n-- Icecrown floors 1/3/4/5/6/7 correspond to UiMaps 186/188/189/190/191/192.",
            ["Data/Expansions/WrathOfTheLichKing/AchievementReputationGuides.lua"] = "-- Retail reputation routes. Preserve the detailed, already curated tabard\n-- unlock guides, then add the achievement's Exalted requirement and farming route.",
            ["Data/Expansions/WrathOfTheLichKing/AchievementTournamentGuides.lua"] = "-- Individual Retail tournament achievement discussions were reviewed, including\n-- the repeated city-challenge guides, rank corrections and modern unlock replies.\n-- champion ID, exalted ID, city, faction, city quest giver, current NPC position,\n-- city reputation tabard/vendor/UiMapID/position, per-achievement guide comment.",
            ["Data/Expansions/WrathOfTheLichKing/AchievementWorldGuides.lua"] = "-- Hand-curated English Retail routes. Story achievements use chapters,\n-- not the obsolete quest-count totals in the original Wrath comments.",
        },
